def rueckkehr_hinweise_pruefen():
    if not isinstance(
        globals().get("spieler"),
        dict
    ):
        return

    wegstation = spieler.get(
        "wegstation_status",
        {}
    )

    funde = wegstation.get(
        "funde",
        {}
    )

    karten_status = spieler.get(
        "besondere_funde",
        {}
    ).get(
        "altes_kartenstueck"
    )

    kartenstueck_bekannt = (
        item_besitzt(
            "altes_kartenstueck"
        )
        or karten_status in (
            "erhalten",
            "zugeordnet"
        )
    )

    if (
        funde.get(
            "archiv_untersucht",
            False
        )
        and kartenstueck_bekannt
        and not funde.get(
            "geheimraum_hinweis",
            False
        )
        and not wegstation.get(
            "geheimgang_offen",
            False
        )
    ):
        rueckkehr_hinweis_aktivieren(
            "wegstation_archiv_kartenstueck"
        )

    if (
        spieler.get(
            "ignaz_wegstation_hinweis",
            False
        )
        and funde.get(
            "archiv_untersucht",
            False
        )
        and not funde.get(
            "geheimraum_hinweis",
            False
        )
        and not wegstation.get(
            "geheimgang_offen",
            False
        )
    ):
        rueckkehr_hinweis_aktivieren(
            "wegstation_archiv_kartenstueck"
        )

    if (
        spieler.get(
            "waldwaechter_schwelle_erlebt",
            False
        )
        and spieler.get(
            "wald_fragment_gefunden",
            False
        )
        and not wald_fund_bekannt(
            "wegstein_nachhall"
        )
    ):
        rueckkehr_hinweis_aktivieren(
            "wegstein_nach_erwachen"
        )

    if (
        spieler.get(
            "quest_schmied"
        ) == "abgeschlossen"
        and item_besitzt(
            "versiegeltes_register"
        )
        and wald_fund_bekannt(
            "wegstein_nachhall"
        )
        and not spieler.get(
            "alte_zeichen_verknuepft",
            False
        )
    ):
        rueckkehr_hinweis_aktivieren(
            "alte_zeichen_bjorn"
        )

    oros_abschrift_bekannt = spieler.get(
        "letzthafen_status",
        {}
    ).get(
        "spuren",
        {}
    ).get(
        "oros_abschrift",
        False
    )

    if (
        spieler.get(
            "alte_zeichen_verknuepft",
            False
        )
        and not spieler.get(
            "universitaet_oros_bekannt",
            False
        )
        and (
            oros_abschrift_bekannt
            or besonderer_fund_status(
                "strassenkarte_wegstation"
            ) == "gelesen"
        )
    ):
        rueckkehr_hinweis_aktivieren(
            "oros_tomas"
        )

    if (
        spieler.get(
            "quest_wege_verbinden"
        ) == "abgeschlossen"
        and stelle_quest_status() == "nicht_entdeckt"
    ):
        rueckkehr_hinweis_aktivieren(
            "stelle_valerie"
        )


