# SPIELZEIT
# --------------------------------------------------

_SPIELZEIT_STAND = [None, 0.0]  # [Kennung des Spielers, letzte Messung]
SPIELZEIT_MAX_PAUSE = 600  # Sekunden; längere Pausen am Stück zählen nicht

TAG_DAUER = 2400  # Sekunden Spielzeit pro Spieltag
WETTER_FOLGE = (
    "Klar", "Klar", "Klar", "Klar",
    "Bewölkt", "Bewölkt", "Nebel", "Regen",
    "Klar", "Klar"
)


def himmel_berechnen(sekunden):
    # Tageszeit und Wetter folgen allein der Spielzeit (kein Zufall): ein
    # Spieltag dauert 40 Minuten, das Wetter wechselt alle 15 Minuten.
    # Die Web-Anzeige rechnet mit derselben Formel.
    sekunden = int(sekunden or 0)
    teil = (sekunden % TAG_DAUER) / TAG_DAUER

    if teil < 0.55:
        tageszeit = "Tag"
    elif teil < 0.70:
        tageszeit = "Abend"
    elif teil < 0.90:
        tageszeit = "Nacht"
    else:
        tageszeit = "Morgen"

    wetter = WETTER_FOLGE[((sekunden // 900) * 7 + 3) % 10]

    return tageszeit, wetter


def schlaf_moeglich():
    # Geschlafen wird erst ab dem Abend; tagsüber ist es zu früh.
    spielzeit_aktualisieren()

    return spieler.get("tageszeit") in ("Abend", "Nacht")


def schlafen_bis_morgen(einleitung, heilung=None):
    # Schlafen springt bis zum Beginn des nächsten Morgens. Die Spielzeit
    # (Statistik) bleibt unberührt, nur der Zeitversatz wächst; damit ändern
    # sich auch Tageszeit und Wetter. heilung=None heilt vollständig.
    frist_handlung(FRIST_SCHLAFEN)

    gesamt = int(spieler.get("spielzeit", 0)) + int(spieler.get("zeit_versatz", 0))
    rest = gesamt % TAG_DAUER
    morgen = int(TAG_DAUER * 0.90)

    if rest < morgen:
        sprung = morgen - rest
    else:
        sprung = TAG_DAUER - rest + morgen

    spieler["zeit_versatz"] = int(spieler.get("zeit_versatz", 0)) + sprung
    spielzeit_aktualisieren()

    if heilung is None:
        spieler["lebenspunkte"] = 100
    else:
        spieler["lebenspunkte"] = min(100, spieler["lebenspunkte"] + heilung)

    print()
    text_ausgeben(einleitung)
    text_ausgeben("Du schläfst tief und wachst auf, als es hell wird.")

    zeile = himmel_zeile(
        spieler.get("tageszeit", "Tag"),
        spieler.get("wetter", "Klar")
    )

    if zeile:
        text_ausgeben(zeile)

    print()

    if heilung is None:
        print("Deine Lebenspunkte wurden vollständig wiederhergestellt.")
    else:
        print(f"Du hast dich erholt. Lebenspunkte: {spieler['lebenspunkte']}/100")


def spielzeit_aktualisieren():
    # Zählt die Zeit seit der letzten Messung zum Spielstand dazu. Wird an
    # Eingaben, beim Speichern und in der Anzeige aufgerufen; lange Pausen
    # (AFK, Handy weggelegt) werden gekappt.
    jetzt = time.monotonic()

    if not isinstance(spieler, dict):
        return 0

    if _SPIELZEIT_STAND[0] != id(spieler):
        _SPIELZEIT_STAND[0] = id(spieler)
        _SPIELZEIT_STAND[1] = jetzt

    verstrichen = jetzt - _SPIELZEIT_STAND[1]
    _SPIELZEIT_STAND[1] = jetzt

    if spieler.get("name") and verstrichen > 0:
        spieler["spielzeit"] = (
            spieler.get("spielzeit", 0)
            + min(verstrichen, SPIELZEIT_MAX_PAUSE)
        )

    if spieler.get("name"):
        spieler["tageszeit"], spieler["wetter"] = himmel_berechnen(
            spieler.get("spielzeit", 0)
            + spieler.get("zeit_versatz", 0)
        )

    return spieler.get("spielzeit", 0)


def spielzeit_text(sekunden=None):
    if sekunden is None:
        sekunden = spielzeit_aktualisieren()

    minuten = int(sekunden // 60)

    if minuten < 60:
        return f"{minuten} Min"

    return f"{minuten // 60} Std {minuten % 60} Min"


HIMMEL_ORTE = (
    "Eichenruh", "Wald", "Köhlerei", "Marktplatz", "Verlassenes Dorf"
)


def himmel_zeile(zeit, wetter):
    # Kurze Stimmungszeile für Orte im Freien; bei Tag und klarem Wetter
    # (und bei bloßer Bewölkung) steht nichts da.
    if wetter == "Regen":
        if zeit == "Nacht":
            return "Es ist Nacht und es regnet."
        return "Es regnet. Der Boden ist nass."

    if wetter == "Nebel":
        if zeit == "Nacht":
            return "Es ist Nacht, und Nebel liegt dicht über dem Land."
        return "Nebel liegt über dem Land."

    if zeit == "Nacht":
        return "Es ist Nacht. Du siehst nur wenige Schritte weit."

    if zeit == "Abend":
        return "Der Abend kommt, das Licht wird flach."

    if zeit == "Morgen":
        return "Es ist früh am Morgen und kühl."

    return None


def himmel_zeile_anzeigen(titel):
    if "spieler" not in globals() or not isinstance(spieler, dict):
        return

    ort = str(titel).split(" - ")[0].split(" am ")[0].strip()

    if ort not in HIMMEL_ORTE:
        return

    # Zeit nachführen, damit auch die erste Seite nach dem Laden stimmt.
    spielzeit_aktualisieren()

    zeile = himmel_zeile(
        spieler.get("tageszeit", "Tag"),
        spieler.get("wetter", "Klar")
    )

    if zeile:
        text_ausgeben(
            zeile,
            art="menue"
        )
        print()


