def spieler_name_formatieren(text):
    if not isinstance(
        globals().get("spieler"),
        dict
    ):
        return text

    name = spieler.get("name")

    if not name:
        return text

    name_text = f"[{name}]"

    if not text.startswith(name_text):
        return text

    farbe = spieler.get(
        "spieler_name_farbe",
        STANDARD_EINSTELLUNGEN[
            "spieler_name_farbe"
        ]
    )

    if (
        farbe == "standard"
        or not ANSI_STILE_AKTIV
        or farbe not in ANSI_STILE
    ):
        return text

    return (
        f"{ANSI_STILE[farbe]}"
        f"{name_text}"
        f"{ANSI_STILE['reset']}"
        f"{text[len(name_text):]}"
    )

