def ortstext_erster_besuch(ort_id):
    # Lange Übergangstexte nur beim ersten Mal (Nutzerfeedback 18.10.).
    gesehen = spieler.setdefault("ortstexte_gesehen", [])

    if ort_id in gesehen:
        return False

    gesehen.append(ort_id)
    return True


def ortstext_wechsel(ort_id, *varianten):
    # Wiederkehrende Ortszeilen der Reihe nach abwechseln.
    zaehler = spieler.setdefault("ortstext_zaehler", {})
    nummer = zaehler.get(ort_id, 0)
    zaehler[ort_id] = nummer + 1
    return varianten[nummer % len(varianten)]


def reise_schnellreise_gesperrt(
    strecken_daten,
    start,
    ziel
):
    # Zentrale Prüfung: Ein Eintrag (Abzweigung oder Ereignis) einer Strecke
    # trägt "schnellreise_sperre": <Bedingung>, solange er für eine offene
    # Aufgabe auf der Normalreise gebraucht wird. Gilt die Bedingung, wird
    # die Schnellreise nicht angeboten. Neue Reise-Quests brauchen nur diesen
    # einen Eintrag in den Streckendaten.
    richtung = f"{start}>{ziel}"

    eintraege = (
        list(strecken_daten.get("abzweigungen", []))
        + list(strecken_daten.get("ereignisse", []))
    )

    dauerhaft_erlebt = spieler.get(
        "reise_ereignisse",
        []
    )

    for eintrag in eintraege:
        sperre = eintrag.get(
            "schnellreise_sperre"
        )

        if not sperre:
            continue

        eintrag_richtung = eintrag.get(
            "richtung"
        )

        if (
            eintrag_richtung
            and eintrag_richtung != richtung
        ):
            continue

        schritte = eintrag.get(
            "schritte"
        )

        if (
            isinstance(schritte, dict)
            and richtung not in schritte
        ):
            continue

        # Ein einmaliges Ereignis, das schon erlebt wurde, kommt
        # nicht wieder und muss die Schnellreise nicht mehr sperren.
        if (
            eintrag.get("einmalig", False)
            and eintrag.get("id") in dauerhaft_erlebt
        ):
            continue

        if reise_bedingung_erfuellt(
            sperre
        ):
            return True

    return False


def reise(
    ziel,
    *ankunft_zeilen,
    gebiet_modus=False
):
    if akt1_reisesperre():
        akt1_reisesperre_meldung()
        return

    start = spieler["ort"]
    strecke = frozenset((start, ziel))

    if strecke not in REISE_STRECKEN:
        print(
            "Für diese Strecke ist noch keine Verbindung festgelegt."
        )
        warte_auf_taste()
        return

    reise_daten = REISE_STRECKEN[
        strecke
    ]

    weg_id = reise_daten.get(
        "weg_id"
    )

    # Strecken ohne eigene weg_id (Waldweg zur Köhlerei) nutzen
    # "routenkenntnis_id", ohne dass sich Reiseanzeige oder
    # Texte der Strecke ändern.
    kenntnis_id = reise_daten.get(
        "routenkenntnis_id",
        weg_id
    )

    # -------------------------
    # VERTRAUTE ROUTE
    # -------------------------

    if (
        kenntnis_id
        and reise_daten.get(
            "schnellreise",
            False
        )
        and routenkenntnis_bekannt(
            kenntnis_id
        )
        and not (
            akt1_riss_geschehen()
            and weg_id == "koenigsring"
        )
    ):
        schnellreise_gesperrt = reise_schnellreise_gesperrt(
            reise_daten,
            start,
            ziel
        )

        reise_name = reise_daten.get(
            "name",
            reise_daten["gebiet"]
        )

        ort_titel(
            f"Reise - {reise_name}"
        )

        print(
            f"{reise_ort_name(start)} → {reise_ort_name(ziel)}"
        )

        print()

        design_text(
            "Vertraute Route",
            design="wissen",
            art="menue"
        )

        print()

        if schnellreise_gesperrt:
            print(
                "Auf dieser Strecke wartet noch eine offene Aufgabe. "
                "Reise auf dem normalen Weg, um sie nicht zu überspringen."
            )

            menue_trenner()
            print()

            print(
                "1. Normal reisen"
            )

            print(
                "2. Zurück"
            )

            if eingabe_menu(
                1,
                2,
                sonder_tasten=()
            ) == 2:
                return

            reise_auswahl = 1

        else:
            print(
                "Du kennst diese Strecke inzwischen gut genug, "
                "um sie ohne längere Erkundung zurückzulegen."
            )

            menue_trenner()
            print()

            print(
                "1. Normal reisen"
            )

            print(
                "2. Strecke zügig zurücklegen"
            )

            print(
                "3. Zurück"
            )

            reise_auswahl = eingabe_menu(
                1,
                3,
                sonder_tasten=()
            )

            if reise_auswahl == 3:
                return

        # -------------------------
        # ZÜGIG REISEN
        # -------------------------

        if reise_auswahl == 2:

            # Zeit vergeht trotzdem.
            if reise_daten[
                "gebiet"
            ] in (
                "Wald",
                "Waldweg"
            ):
                ressourcen_vorkommen_regenerieren(
                    "wald_holz",
                    reise_daten[
                        "schritte"
                    ]
                )

            stollen_regenerieren(
                reise_daten[
                    "schritte"
                ]
            )
            frist_handlung(reise_daten["schritte"])

            if not status_schritte_abschliessen(
                reise_daten[
                    "schritte"
                ]
            ):
                return

            spieler[
                "reise"
            ] = None

            spieler[
                "ort"
            ] = ziel
            archiv_ankunft(ziel)

            # Streckennamen mit eigener Beugung ("auf der Nordstraße").
            auf_text = reise_daten.get(
                "auf_text",
                f"auf dem {reise_name}"
            )

            ort_nachricht_setzen(
                (
                    f"Du folgst den vertrauten Markierungen {auf_text} "
                    f"und vermeidest unnötige Umwege."
                ),
                *ankunft_zeilen
            )

            return

    # -------------------------
    # NORMALE REISE
    # -------------------------

    spieler["reise"] = {
        "start": start,
        "ziel": ziel,
        "gebiet": reise_daten[
            "gebiet"
        ],

        "name": reise_daten.get(
            "name",
            reise_daten["gebiet"]
        ),

        "weg_id": reise_daten.get(
            "weg_id"
        ),

        "gesamt_schritte": reise_daten[
            "schritte"
        ],

        "aktueller_schritt": 0,

        "ausgeloeste_ereignisse": [],

        "angebotene_abzweigungen": [],

        "zufallskaempfe": 0,

        "zufallsereignisse": reise_daten.get(
            "zufallsereignisse",
            True
        ),

        "ankunft_zeilen": list(
            ankunft_zeilen
        )
    }

    if gebiet_modus:
        spieler[
            "ort"
        ] = reise_daten[
            "gebiet"
        ]

        if (
            start == "Eichenruh"
            and ziel == "Köhlerei"
            and spieler.get(
                "quest_hilda"
            ) == "aktiv"
        ):
            ort_nachricht_setzen(
                "Du lässt Eichenruh hinter dir und folgst erneut "
                "dem Waldweg zur Köhlerei.",
                "Diesmal achtest du weniger auf das Ziel als auf "
                "Spuren am Wegesrand.",
                "Irgendwo auf dieser Strecke hätte Hildas Händler "
                "vorbeikommen müssen."
            )

        elif (
            start == "Eichenruh"
            and ziel == "Letzthafen"
            and spieler.get(
                "quest_ein_name_fehlt"
            ) == "letzthafen_suchen"
        ):
            ort_nachricht_setzen(
                "Du verlässt den Marktplatz über die breite Straße "
                "nach Osten.",
                "Unter Gras und Erde tauchen die alten Pflastersteine "
                "des Königsrings auf.",
                "Im Fahrtenbuch stehen nur wenige brauchbare Worte: "
                "Klippen. Hafen. Mehr hast du im Moment nicht."
            )

        elif (
            start == "Eichenruh"
            and ziel == "verlassenes_dorf"
            and spieler.get(
                "quest_schmied"
            ) == "suche_verlassenes_dorf"
        ):
            ort_nachricht_setzen(
                "Du verlässt Eichenruh nach Süden und folgst dem Weg "
                "zwischen den Feldern.",
                "Bjorns Beschreibung ist knapp: ein alter Waldweg, "
                "ein vergessenes Dorf und irgendwo darin eine Schmiede.",
                "Vor dir liegt der Pfad des Vergessens."
            )

        elif (
            start == "verlassenes_dorf"
            and ziel == "Eichenruh"
            and spieler.get(
                "quest_schmied"
            ) == "hammer_gefunden"
        ):
            ort_nachricht_setzen(
                "Du lässt die stillen Häuser des verlassenen Dorfes hinter dir.",
                "Der alte Schmiedehammer liegt sorgfältig eingewickelt "
                "in deinem Gepäck.",
                "Bjorn war derjenige, der die Geschichte kannte. "
                "Jetzt kannst du ihm zeigen, dass sie wahr war."
            )

        else:
            ort_nachricht_setzen(
                f"Du lässt {reise_ort_name(start)} hinter dir "
                "und machst dich auf den Weg.",
                f"Vor dir liegt die Strecke in Richtung "
                f"{reise_ort_name(ziel)}."
            )

        reise_speicherhinweis_setzen()
        return

    reise_speicherhinweis_setzen()
    reise_fortsetzen()


def reise_speicherhinweis_setzen():
    if spieler.get("reise_speicherhinweis_gezeigt", False):
        return
    spieler["reise_speicherhinweis_gezeigt"] = True
    nachricht = spieler.get("ort_nachricht")
    if not isinstance(nachricht, list):
        nachricht = []
    nachricht.append(
        "Tipp: Unterwegs kann es gefährlich werden. "
        "Mit [Q] Speichern / Menü sicherst du jederzeit deinen Fortschritt."
    )
    spieler["ort_nachricht"] = nachricht


def reise_strecken_daten(reise_daten):
    if not isinstance(
        reise_daten,
        dict
    ):
        return {}

    start = reise_daten.get(
        "start"
    )

    ziel = reise_daten.get(
        "ziel"
    )

    if not start or not ziel:
        return {}

    strecke = frozenset(
        (start, ziel)
    )

    return REISE_STRECKEN.get(
        strecke,
        {}
    )


def reise_schritttext_waehlen(
    reise_daten,
    schritt
):
    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    # -------------------------
    # VARIABLE REISETEXTE
    # -------------------------

    variable_texte = strecken_daten.get(
        "variable_schritt_texte",
        {}
    ).get(
        richtung,
        {}
    ).get(
        schritt,
        []
    )

    # Nach dem Riss endet am Pfad des Vergessens ein Straßengraben (Kapitel 7).
    if (
        variable_texte
        and richtung == "Eichenruh>verlassenes_dorf"
        and schritt == 5
        and akt1_riss_geschehen()
    ):
        variable_texte = variable_texte + [PFAD_GRABEN_NACH_RISS]

    if variable_texte:
        text_verlauf = spieler.setdefault(
            "reise_text_verlauf",
            {}
        )

        schluessel = (
            f'{reise_daten["start"]}>'
            f'{reise_daten["ziel"]}:'
            f'{schritt}'
        )

        letzter_text = text_verlauf.get(
            schluessel
        )

        kandidaten = [
            text
            for text in variable_texte
            if text != letzter_text
        ]

        if not kandidaten:
            kandidaten = variable_texte

        ausgewaehlter_text = random.choice(
            kandidaten
        )

        text_verlauf[
            schluessel
        ] = ausgewaehlter_text

        return ausgewaehlter_text

    # -------------------------
    # BISHERIGE FESTE REISETEXTE
    # -------------------------

    feste_texte = strecken_daten.get(
        "schritt_texte",
        {}
    ).get(
        richtung,
        []
    )

    if schritt - 1 < len(feste_texte):
        return feste_texte[
            schritt - 1
        ]

    return (
        f"Du folgst dem Weg weiter "
        f"in Richtung {reise_daten['ziel']}."
    )

def reise_beobachtung_waehlen(
    reise_daten,
    schritt
):
    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    # Feste Story- und Questereignisse
    # haben Vorrang vor Atmosphäre.
    if reise_festes_ereignis_verfuegbar(
        reise_daten,
        schritt
    ):
        return None

    beobachtungs_daten = strecken_daten.get(
        "reise_beobachtungen"
    )

    if not isinstance(
        beobachtungs_daten,
        dict
    ):
        return None

    # -------------------------
    # MAXIMUM PRO REISE
    # -------------------------

    maximum = beobachtungs_daten.get(
        "max_pro_reise",
        2
    )

    bisher = reise_daten.setdefault(
        "beobachtungen_gezeigt",
        0
    )

    if bisher >= maximum:
        return None

    # -------------------------
    # GESPERRTE SCHRITTE
    # -------------------------

    gesperrte_schritte = (
        beobachtungs_daten.get(
            "gesperrte_schritte",
            []
        )
    )

    if schritt in gesperrte_schritte:
        return None

    # -------------------------
    # ZUFALL
    # -------------------------

    chance = beobachtungs_daten.get(
        "chance",
        0.25
    )

    if random.random() >= chance:
        return None

    # -------------------------
    # RICHTUNG
    # -------------------------

    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    texte = beobachtungs_daten.get(
        "texte",
        {}
    ).get(
        richtung,
        []
    )

    if not texte:
        return None

    # -------------------------
    # WIEDERHOLUNGEN VERMEIDEN
    # -------------------------

    bereits_gezeigt = reise_daten.setdefault(
        "gezeigte_beobachtungen",
        []
    )

    kandidaten = [
        text
        for text in texte
        if text not in bereits_gezeigt
    ]

    if not kandidaten:
        kandidaten = texte

    ausgewaehlt = random.choice(
        kandidaten
    )

    bereits_gezeigt.append(
        ausgewaehlt
    )

    reise_daten[
        "beobachtungen_gezeigt"
    ] = bisher + 1

    return ausgewaehlt

def reise_entdeckung_pruefen(
    reise_daten,
    schritt
):
    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    # Feste Story- und Questereignisse
    # haben immer Vorrang.
    if reise_festes_ereignis_verfuegbar(
        reise_daten,
        schritt
    ):
        return False

    entdeckungs_daten = strecken_daten.get(
        "reise_entdeckungen"
    )

    if not isinstance(
        entdeckungs_daten,
        dict
    ):
        return False

    maximum = entdeckungs_daten.get(
        "max_pro_reise",
        1
    )

    bisher = reise_daten.setdefault(
        "entdeckungen_gezeigt",
        0
    )

    if bisher >= maximum:
        return False

    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    dauerhaft_erledigt = spieler.setdefault(
        "reise_entdeckungen",
        []
    )

    angeboten = reise_daten.setdefault(
        "angebotene_entdeckungen",
        []
    )

    kandidaten = []

    for entdeckung in entdeckungs_daten.get(
        "eintraege",
        []
    ):
        entdeckung_id = entdeckung.get(
            "id"
        )

        if not entdeckung_id:
            continue

        if entdeckung_id in angeboten:
            continue

        if (
            entdeckung.get(
                "einmalig",
                False
            )
            and entdeckung_id
            in dauerhaft_erledigt
        ):
            continue

        entdeckung_richtung = entdeckung.get(
            "richtung"
        )

        if (
            entdeckung_richtung
            and entdeckung_richtung
            != richtung
        ):
            continue

        schritte = entdeckung.get(
            "schritte",
            []
        )

        if isinstance(
            schritte,
            dict
        ):
            schritte = schritte.get(
                richtung,
                []
            )

        if (
            schritte
            and schritt not in schritte
        ):
            continue

        if not reise_bedingung_erfuellt(
            entdeckung.get(
                "bedingung"
            )
        ):
            continue

        kandidaten.append(
            entdeckung
        )

    if not kandidaten:
        return False

    chance = entdeckungs_daten.get(
        "chance",
        0.10
    )

    if not isinstance(
        chance,
        (int, float)
    ):
        return False

    wahrnehmung = spieler_pruefwert(
        "wahrnehmung"
    )

    if isinstance(
        wahrnehmung,
        (int, float)
    ):
        bonus_pro_punkt = (
            entdeckungs_daten.get(
                "wahrnehmung_bonus",
                0.015
            )
        )

        if isinstance(
            bonus_pro_punkt,
            (int, float)
        ):
            chance += (
                wahrnehmung
                * bonus_pro_punkt
            )

    if talent_bonus(spieler, "nachtauge") > 0:
        chance *= 2

    chance = min(
        chance,
        0.30
    )

    if random.random() >= chance:
        return False

    entdeckung = random.choice(
        kandidaten
    )

    entdeckung_id = entdeckung[
        "id"
    ]

    angeboten.append(
        entdeckung_id
    )

    reise_daten[
        "entdeckungen_gezeigt"
    ] = bisher + 1

    print()

    design_text(
        entdeckung.get(
            "titel",
            "[Entdeckung]"
        ),
        design=entdeckung.get(
            "design",
            "wissen"
        ),
        art="menue"
    )

    print()

    for nummer, zeile in enumerate(
        entdeckung.get(
            "text",
            []
        )
    ):
        text_ausgeben(
            zeile
        )

        if nummer < len(
            entdeckung.get(
                "text",
                []
            )
        ) - 1:
            print()

    optionen = entdeckung.get(
        "optionen",
        []
    )

    if not optionen:
        return True

    menue_trenner()
    print()

    for nummer, option in enumerate(
        optionen,
        start=1
    ):
        print(
            f'{nummer}. '
            f'{option.get("option", "Untersuchen")}'
        )

    auswahl = eingabe_menu(
        1,
        len(optionen),
        sonder_tasten=()
    )

    option = optionen[
        auswahl - 1
    ]

    ergebnis_texte = option.get(
        "ergebnis",
        []
    )

    if ergebnis_texte:
        print()

    for nummer, zeile in enumerate(
        ergebnis_texte
    ):
        text_ausgeben(
            zeile
        )

        if nummer < len(
            ergebnis_texte
        ) - 1:
            print()

    item_daten = option.get(
        "item"
    )

    if isinstance(
        item_daten,
        dict
    ):
        item_id = item_daten.get(
            "id"
        )

        anzahl = item_daten.get(
            "anzahl",
            1
        )

        if (
            item_id in ITEMS
            and item_hinzufuegen(
                item_id,
                anzahl
            )
        ):
            print()

            design_text(
                (
                    f'{anzahl}x '
                    f'{ITEMS[item_id]["name"]} erhalten'
                ),
                design="positiv",
                art="menue"
            )

    lernquelle = option.get(
        "lernerfahrung"
    )

    if lernquelle:
        akt1_lernerfahrung(
            lernquelle
        )

    if (
        option.get(
            "abschliessen",
            False
        )
        and entdeckung_id
        not in dauerhaft_erledigt
    ):
        dauerhaft_erledigt.append(
            entdeckung_id
        )

    return True

