def reise_bedingung_erfuellt(bedingung):
    if not bedingung:
        return True

    if not isinstance(
        bedingung,
        dict
    ):
        return False

    typ = bedingung.get(
        "typ"
    )

    if typ in (
        "alle",
        "eine"
    ):
        bedingungen = bedingung.get(
            "bedingungen",
            []
        )

        if not bedingungen:
            return False

        ergebnisse = [
            reise_bedingung_erfuellt(
                einzelne_bedingung
            )
            for einzelne_bedingung
            in bedingungen
        ]

        if typ == "alle":
            return all(
                ergebnisse
            )

        return any(
            ergebnisse
        )

    if typ == "nicht":
        einzelne_bedingung = bedingung.get(
            "bedingung"
        )

        if not einzelne_bedingung:
            return False

        return not reise_bedingung_erfuellt(
            einzelne_bedingung
        )

    if typ == "besonderer_fund_status":
        return besonderer_fund_status(
            bedingung.get("id")
        ) == bedingung.get("status")

    if typ == "weg_status":
        return weg_status(
            bedingung.get("id")
        ) == bedingung.get("status")

    if typ == "quest_status":
        return spieler.get(
            bedingung.get("id")
        ) == bedingung.get("status")

    if typ == "quest_status_in":
        return spieler.get(
            bedingung.get("id")
        ) in bedingung.get(
            "werte",
            []
        )

    if typ in (
        "spieler_wert_min",
        "spieler_wert_max"
    ):
        wert = spieler_pruefwert(
            bedingung.get("id")
        )

        grenze = bedingung.get(
            "grenze"
        )

        if not isinstance(
            wert,
            (int, float)
        ):
            return False

        if not isinstance(
            grenze,
            (int, float)
        ):
            return False

        if typ == "spieler_wert_min":
            return wert >= grenze

        return wert <= grenze

    if typ == "kapitel_wert":
        daten = spieler.get(bedingung.get("kapitel"))

        if not isinstance(daten, dict):
            return False

        return daten.get(bedingung.get("schluessel")) in bedingung.get("werte", [])

    return False

def reise_festes_ereignis_verfuegbar(
    reise_daten,
    schritt
):
    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    ausgeloest = reise_daten.get(
        "ausgeloeste_ereignisse",
        []
    )

    dauerhaft_erlebt = spieler.get(
        "reise_ereignisse",
        []
    )

    for ereignis in strecken_daten.get(
        "ereignisse",
        []
    ):
        ereignis_id = ereignis.get(
            "id"
        )

        if not ereignis_id:
            continue

        if ereignis.get(
            "schritt"
        ) != schritt:
            continue

        ereignis_richtung = ereignis.get(
            "richtung"
        )

        if (
            ereignis_richtung
            and ereignis_richtung != richtung
        ):
            continue

        if ereignis_id in ausgeloest:
            continue

        if (
            ereignis.get(
                "einmalig",
                False
            )
            and ereignis_id
            in dauerhaft_erlebt
        ):
            continue

        if not reise_bedingung_erfuellt(
            ereignis.get(
                "bedingung"
            )
        ):
            continue

        return True

    return False



def reise_ereignisse_pruefen(
    reise_daten,
    schritt
):
    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    ausgeloest = reise_daten.setdefault(
        "ausgeloeste_ereignisse",
        []
    )

    dauerhaft_erlebt = spieler.setdefault(
        "reise_ereignisse",
        []
    )

    ereignis_angezeigt = False

    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    for ereignis in strecken_daten.get(
        "ereignisse",
        []
    ):
        ereignis_id = ereignis.get(
            "id"
        )

        if not ereignis_id:
            continue

        if ereignis.get(
            "schritt"
        ) != schritt:
            continue

        ereignis_richtung = ereignis.get(
            "richtung"
        )

        if (
            ereignis_richtung
            and ereignis_richtung != richtung
        ):
            continue

        if ereignis_id in ausgeloest:
            continue

        if (
            ereignis.get(
                "einmalig",
                False
            )
            and ereignis_id
            in dauerhaft_erlebt
        ):
            continue

        if not reise_bedingung_erfuellt(
            ereignis.get(
                "bedingung"
            )
        ):
            continue

        ausgeloest.append(
            ereignis_id
        )

        if (
            ereignis.get(
                "einmalig",
                False
            )
            and ereignis_id
            not in dauerhaft_erlebt
        ):
            dauerhaft_erlebt.append(
                ereignis_id
            )

        aktion = ereignis.get(
            "aktion"
        )

        if aktion == "hilda_karren":
            ereignis_angezeigt = bool(
                hilda_karren_ereignis()
            )

            continue

        if aktion and aktion.startswith("laeuferpfad_"):
            laeuferpfad_etappe(aktion, reise_daten)
            ereignis_angezeigt = True
            continue

        print()

        titel = ereignis.get(
            "titel"
        )

        if titel:
            design_text(
                titel,
                design=ereignis.get(
                    "design",
                    "wissen"
                ),
                art="menue"
            )

            print()

        zeilen = ereignis.get(
            "text",
            []
        )

        for nummer, zeile in enumerate(
            zeilen
        ):
            text_ausgeben(
                zeile
            )

            if nummer < len(zeilen) - 1:
                print()

        warte_auf_taste(
            ereignis.get(
                "weiter_text",
                "Weiterreisen"
            )
        )

        ereignis_angezeigt = True

    return ereignis_angezeigt

def reise_bekannte_abzweigung_vorhanden(
    reise_daten,
    schritt
):
    richtung = (
        f'{reise_daten["start"]}>'
        f'{reise_daten["ziel"]}'
    )

    angebotene = reise_daten.setdefault(
        "angebotene_abzweigungen",
        []
    )

    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    for abzweigung in strecken_daten.get(
        "abzweigungen",
        []
    ):
        abzweigung_id = abzweigung.get(
            "id"
        )

        if not abzweigung_id:
            continue

        if abzweigung_id in angebotene:
            continue

        abzweigung_schritt = abzweigung.get(
            "schritt"
        )

        richtungs_schritte = abzweigung.get(
            "schritte",
            {}
        )

        if richtung in richtungs_schritte:
            abzweigung_schritt = (
                richtungs_schritte[richtung]
            )

        if abzweigung_schritt != schritt:
            continue

        if not reise_bedingung_erfuellt(
            abzweigung.get("bedingung")
        ):
            continue

        weg_id = abzweigung.get(
            "weg_id"
        )

        if (
            weg_id
            and weg_status(weg_id)
            == "entdeckt"
        ):
            return True

    return False

def pfad_randsteine_untersuchen(reise_daten):
    ort_titel(
        "Pfad des Vergessens - Alte Randsteine"
    )

    stille_jetzt = "pfad_stille" in reise_daten.get(
        "ausgeloeste_ereignisse",
        []
    )
    stille_frueher = (
        not stille_jetzt
        and "pfad_stille" in spieler.get("reise_ereignisse", [])
    )

    if stille_jetzt:
        text_ausgeben(
            "Eben hast du hier gemerkt, dass kein Vogel mehr ruft."
        )

        text_ausgeben(
            "Ob das etwas mit den Steinen zu tun hat, kannst du nicht sagen. "
            "Aber es ist dieselbe Stelle."
        )

        print()

    elif stille_frueher:
        text_ausgeben(
            "Du erkennst die Stelle. Hier hat damals mitten im Schritt jeder "
            "Vogel aufgehört zu rufen."
        )

        text_ausgeben(
            "Ob das etwas mit den Steinen zu tun hat, kannst du nicht sagen. "
            "Aber es ist dieselbe Stelle."
        )

        print()

    text_ausgeben(
        "Am Rand des Weges liegen alte Randsteine im Gras, wie an vielen "
        "Stellen dieses Pfades. Du bist schon an ihnen vorbeigegangen, ohne "
        "hinzusehen."
    )

    print()

    text_ausgeben(
        "Diesmal zählst du. Es sind vier. Sie liegen nicht in einer Reihe, wie "
        "Randsteine liegen sollten, sondern versetzt, in einer Anordnung, die "
        "du inzwischen kennst."
    )

    text_ausgeben(
        "Du ziehst die Linien. Sie treffen sich, wo sie sich treffen sollen. "
        "Kein Stein fehlt, keiner ist verschoben, keine Kante ist gebrochen."
    )

    print()

    text_ausgeben(
        "Das war die ganze Zeit hier. Jeder, der diesen Weg gegangen ist, ist "
        "daran vorbeigelaufen."
    )

    print()

    text_ausgeben(
        "Eine der Linien weist vom Weg in den Wald. Du hältst deine Skizze von "
        "den versunkenen Steinen daneben."
    )

    text_ausgeben(
        "Von dort aus zeigte die Linie hierher, auf diesen Abschnitt des Weges. "
        "Das stimmt."
    )

    text_ausgeben(
        "Aber die Linie von hier zeigt nicht zurück. Sie läuft an den "
        "versunkenen Steinen vorbei, ein gutes Stück daneben. Auf eine Stelle "
        "im Wald, an der nach deiner Skizze nichts liegt."
    )

    print()

    text_ausgeben(
        "Du prüfst es noch einmal. Und ein drittes Mal."
    )

    text_ausgeben(
        "Beide Anordnungen sind für sich genommen sauber. Aber sie widersprechen sich."
    )

    if spieler_pruefung("sensibilitaet", 2):
        print()

        text_ausgeben(
            "Die vier Steine gehören zusammen, daran zweifelst du nicht. Trotzdem "
            "fühlt sich die Richtung, in die sie zeigen, falsch an. Nicht kaputt. "
            "Eher wie ein Wegweiser, der fest im Boden steht und trotzdem in die "
            "falsche Richtung weist."
        )

    if untersuchung_pruefung("wahrnehmung", 3):
        print()

        text_ausgeben(
            "Ein Stück weiter enden Hufspuren mitten auf dem Weg. Du hast so "
            "etwas hier schon einmal gesehen und dir nichts dabei gedacht."
        )

    print()

    text_ausgeben(
        "Ein Ort, an dem ein Stein fehlt. Ein anderer, an dem nichts fehlt und "
        "trotzdem nichts zusammenpasst."
    )

    text_ausgeben(
        "Einmal hätte Zufall sein können. Zweimal fühlt sich nicht mehr so an."
    )

    spieler[
        "wege_pfad_randsteine_untersucht"
    ] = True

    spieler[
        "quest_wege_verbinden"
    ] = "oros_berichten"

    quest_meldung(
        "update",
        "Was die Wege verbindet",
        "Erzähl in Oros, was du an den beiden Orten gefunden hast."
    )

    warte_auf_taste(
        "Weiter"
    )


def reise_abzweigungen_pruefen(
    reise_daten,
    schritt,
    ziel,
    erkundung=False
):
    angebotene = reise_daten.setdefault(
        "angebotene_abzweigungen",
        []
    )

    verfuegbar = []

    strecken_daten = reise_strecken_daten(
        reise_daten
    )

    for abzweigung in strecken_daten.get(
        "abzweigungen",
        []
    ):
        abzweigung_id = abzweigung.get(
            "id"
        )

        if not abzweigung_id:
            continue

        richtung = (
            f'{reise_daten["start"]}>'
            f'{reise_daten["ziel"]}'
        )

        abzweigung_schritt = abzweigung.get(
            "schritt"
        )

        richtungs_schritte = abzweigung.get(
            "schritte",
            {}
        )

        if richtung in richtungs_schritte:
            abzweigung_schritt = (
                richtungs_schritte[richtung]
            )

        if abzweigung_schritt != schritt:
            continue

        if abzweigung_id in angebotene:
            continue

        if not reise_bedingung_erfuellt(
            abzweigung.get("bedingung")
        ):
            continue

        weg_id = abzweigung.get(
            "weg_id"
        )

        weg_status_aktuell = (
            weg_status(weg_id)
            if weg_id
            else None
        )

        if (
            weg_id
            and weg_status_aktuell
            == "unbekannt"
            and not reise_bedingung_erfuellt(
                abzweigung.get(
                    "entdeckungs_bedingung"
                )
            )
        ):
            continue

        if (
            weg_id
            and weg_status_aktuell
            == "entdeckt"
            and not erkundung
        ):
            continue

        if (
            erkundung
            and (
                not weg_id
                or weg_status(weg_id)
                != "entdeckt"
            )
        ):
            continue


        verfuegbar.append(
            abzweigung
        )

    if not verfuegbar:
        return False

    for abzweigung in verfuegbar:
        angebotene.append(
            abzweigung["id"]
        )

        print()

        hinweis = abzweigung.get(
            "hinweis"
        )

        if (
            hinweis
            and reise_bedingung_erfuellt(
                hinweis.get("bedingung")
            )
        ):
            titel = hinweis.get(
                "titel"
            )

            if titel:
                design_text(
                    titel,
                    design="wissen",
                    art="menue"
                )

                print()

            zeilen = hinweis.get(
                "text",
                []
            )

        else:
            weg_id = abzweigung.get(
                "weg_id"
            )

            if (
                weg_id
                and weg_status(weg_id)
                == "entdeckt"
            ):
                zeilen = abzweigung.get(
                    "bekannt_text",
                    abzweigung.get(
                        "text",
                        []
                    )
                )

            else:
                zeilen = abzweigung.get(
                    "text",
                    []
                )

        for nummer, zeile in enumerate(
            zeilen
        ):
            text_ausgeben(
                zeile
            )

            if nummer < len(zeilen) - 1:
                print()

    print()

    for nummer, abzweigung in enumerate(
        verfuegbar,
        start=1
    ):
        weg_id = abzweigung.get(
            "weg_id"
        )

        if (
            weg_id
            and weg_status(weg_id)
            == "unbekannt"
        ):
            weg_bemerken(
                weg_id
            )

        if (
            weg_id
            and weg_status(weg_id)
            == "entdeckt"
        ):
            option_text = abzweigung.get(
                "option_bekannt",
                abzweigung.get(
                    "option",
                    "Abzweigung untersuchen"
                )
            )

        else:
            option_text = abzweigung.get(
                "option",
                "Abzweigung untersuchen"
            )

        rueckkehr_hinweis = abzweigung.get(
            "rueckkehr_hinweis"
        )

        if (
            rueckkehr_hinweis
            and rueckkehr_hinweis_offen(
                rueckkehr_hinweis
            )
        ):
            option_text += " [!]"

        print(
            f"{nummer}. {option_text}"
        )

    weiter_option = len(
        verfuegbar
    ) + 1

    if (
        akt1_riss_geschehen()
        and reise_daten.get("weg_id") == "koenigsring"
    ):
        print(f"{weiter_option}. Dem Königsring weiter folgen")
    else:
        print(
            f"{weiter_option}. Weiter Richtung {reise_ort_name(ziel)}"
        )

    auswahl = eingabe_menu(
        1,
        weiter_option,
        sonder_tasten=()
    )

    if auswahl == weiter_option:
        return False

    abzweigung = verfuegbar[
        auswahl - 1
    ]

    aktion = abzweigung.get(
        "aktion"
    )

    if aktion == "pfad_randsteine":
        if spieler.get("quest_wege_verbinden") == "randsteine_finden":
            pfad_randsteine_untersuchen(
                reise_daten
            )

        return False

    if aktion == "versorgungskehre":
        versorgungskehre(
            reise_daten
        )

        ort_titel(
            f'Reise - {reise_daten.get(
                "name",
                reise_daten["gebiet"]
            )}'
        )

        print(
            f'{reise_ort_name(reise_daten["start"])} → '
            f'{reise_ort_name(reise_daten["ziel"])}'
        )

        menue_trenner()

        text_ausgeben(
            "Du kehrst auf den Faden der Erinnerung zurück.",
            art="menue"
        )

        return False

    if aktion == "alter_koehlerpfad":
        if weg_status(
            "alter_koehlerpfad"
        ) != "entdeckt":
            weg_entdecken(
                "alter_koehlerpfad"
            )
        else:
            weg_als_gesehen_markieren(
                "alter_koehlerpfad"
            )

        koehlerpfad(
            reise_daten
        )

        ort_titel(
            f'Reise - {reise_daten.get(
                "name",
                reise_daten["gebiet"]
            )}'
        )

        print(
            f'{reise_ort_name(reise_daten["start"])} → '
            f'{reise_ort_name(reise_daten["ziel"])}'
        )

        menue_trenner()

        text_ausgeben(
            "Du kehrst auf den Hauptweg zurück.",
            art="menue"
        )

        return False

    if aktion == "alter_seitenpfad":

        if (
            abzweigung.get("id") == "wege_seitenpfad"
            and spieler.get("quest_wege_verbinden") in (
                "tomas_fragen",
                "pfad_folgen"
            )
        ):
            spieler[
                "quest_wege_verbinden"
            ] = "wegstein_vergleichen"

            quest_meldung(
                "update",
                "Was die Wege verbindet",
                "Vergleiche die Richtung mit den Einkerbungen am alten Wegstein."
            )

        if weg_status(
            "alter_seitenpfad"
        ) != "entdeckt":

            weg_entdecken(
                "alter_seitenpfad"
            )

        else:
            weg_als_gesehen_markieren(
                "alter_seitenpfad"
            )

        wald_seitenpfad_navigieren()

        ort_titel(
            f'Reise - {reise_daten.get(
                "name",
                reise_daten["gebiet"]
            )}'
        )

        print(
            f'{reise_ort_name(reise_daten["start"])} → '
            f'{reise_ort_name(reise_daten["ziel"])}'
        )

        menue_trenner()

        text_ausgeben(
            "Du kehrst auf den Hauptweg zurück.",
            art="menue"
        )

        return False

    spieler[
        "ort"
    ] = abzweigung["ziel"]

    ort_nachricht_setzen(
        *abzweigung.get(
            "ankunft_zeilen",
            []
        )
    )

    return True

def reise_ort_name(ort):
    sonder_namen = {
        "verlassenes_dorf": "Verlassenes Dorf",
        "versunkene_chronik": "Versunkene Chronik",
        "archiv_schatten": "Archiv der Schatten",
        "brunnfeld": "Brunnfeld",
        "universitaet_oros": "Universität von Oros",
        "oros_haupttor": "Universität von Oros - Haupttor",
        "oros_zentrale_halle": "Universität von Oros - Zentrale Halle",
        "oros_archiv": "Universität von Oros - Archiv",
        "oros_forschungsraeume": "Universität von Oros - Forschungsräume",
        "oros_lehrhallen": "Universität von Oros - Lehrhallen",
        "tiefen_treppenschacht": "TIEFEN - Treppenschacht",
        "tiefen_messgang": "TIEFEN - Messgang",
        "tiefen_nebenkammer": "TIEFEN - Nebenkammer",
        "tiefen_wartungsnische": "TIEFEN - Wartungsnische",
        "tiefen_kammer": "TIEFEN - Kammer der Reihe",
        "tiefen_iv_c": "TIEFEN - IV-C",
        "tiefen_stollengang": "TIEFEN - Stollengang",
        "tiefen_geroellkammer": "TIEFEN - Geröllkammer"
    }

    if ort in sonder_namen:
        return sonder_namen[ort]

    return str(
        ort
    ).replace(
        "_",
        " "
    ).title()

def reise_aktiv():
    return isinstance(
        spieler.get(
            "reise"
        ),
        dict
    )


def reise_bildschirm_titel(
    zusatz=None
):
    reise_daten = spieler.get(
        "reise"
    )

    if not isinstance(
        reise_daten,
        dict
    ):
        name = "Reise"

    else:
        name = reise_daten.get(
            "name"
        )

        if not name:
            name = reise_daten.get(
                "gebiet",
                "Reise"
            )

    if zusatz:
        return (
            f"{name} - {zusatz}"
        )

    return name

def reise_umkehren():
    reise_daten = spieler.get(
        "reise"
    )

    if not isinstance(
        reise_daten,
        dict
    ):
        return False

    start = reise_daten[
        "start"
    ]

    ziel = reise_daten[
        "ziel"
    ]

    gesamt_schritte = reise_daten[
        "gesamt_schritte"
    ]

    aktueller_schritt = reise_daten[
        "aktueller_schritt"
    ]

    start_name = reise_ort_name(
        start
    )

    ziel_name = reise_ort_name(
        ziel
    )

    ort_titel(
        "Reise umkehren"
    )

    print(
        f"Aktuelles Ziel: {ziel_name}"
    )

    print(
        f"Zurück nach: {start_name}"
    )

    print(
        f"Position: "
        f"{aktueller_schritt}/"
        f"{gesamt_schritte}"
    )

    menue_trenner()
    print()

    print(
        "1. Umkehren"
    )

    print(
        f"2. Weiter Richtung "
        f"{ziel_name}"
    )

    auswahl = eingabe_menu(
        1,
        2,
        sonder_tasten=()
    )

    if auswahl == 2:
        return False

    ankunft_texte = (
        reise_daten.setdefault(
            "ankunft_texte",
            {}
        )
    )

    ankunft_texte.setdefault(
        ziel,
        list(
            reise_daten.get(
                "ankunft_zeilen",
                []
            )
        )
    )

    ankunft_texte.setdefault(
        start,
        [
            (
                f"Du erreichst wieder "
                f"{start_name}."
            )
        ]
    )

    # Noch keinen Schritt gegangen:
    # direkt zum Ausgangsort zurück.
    if aktueller_schritt <= 0:
        spieler[
            "reise"
        ] = None

        spieler[
            "ort"
        ] = start

        ort_nachricht_setzen(
            "Du entscheidest dich umzukehren.",
            (
                f"Du kehrst nach "
                f"{start_name} zurück."
            )
        )

        return True

    # Richtung wechseln.
    reise_daten[
        "start"
    ] = ziel

    reise_daten[
        "ziel"
    ] = start

    # Position auf derselben Strecke spiegeln.
    reise_daten[
        "aktueller_schritt"
    ] = (
        gesamt_schritte
        - aktueller_schritt
    )

    # Abzweigungen dürfen auf dem Rückweg
    # erneut angeboten werden.
    reise_daten[
        "angebotene_abzweigungen"
    ] = []

    reise_daten[
        "ankunft_zeilen"
    ] = list(
        ankunft_texte[
            start
        ]
    )

    ort_nachricht_setzen(
        "Du bleibst stehen und kehrst um.",
        (
            f"Du gehst nun zurück in "
            f"Richtung {start_name}."
        )
    )

    return True

def reise_kampf_status_holen(
    reise_daten,
    strecken_daten
):
    alle_status = spieler.setdefault(
        "reise_kampf_status",
        {}
    )

    if not isinstance(
        alle_status,
        dict
    ):
        alle_status = {}

        spieler[
            "reise_kampf_status"
        ] = alle_status

    # -------------------------
    # ALTES SAVE-FORMAT
    # -------------------------

    if (
        "schritte_ohne_kampf"
        in alle_status
        or "cooldown"
        in alle_status
    ):
        alle_status.clear()

    # -------------------------
    # STRECKE BESTIMMEN
    # -------------------------

    strecken_id = strecken_daten.get(
        "weg_id"
    )

    if not strecken_id:
        start = str(
            reise_daten.get(
                "start",
                ""
            )
        )

        ziel = str(
            reise_daten.get(
                "ziel",
                ""
            )
        )

        strecken_id = (
            "route:"
            + "|".join(
                sorted(
                    (
                        start,
                        ziel
                    )
                )
            )
        )

    kampf_status = alle_status.get(
        strecken_id
    )

    if not isinstance(
        kampf_status,
        dict
    ):
        kampf_status = {}

        alle_status[
            strecken_id
        ] = kampf_status

    kampf_status.setdefault(
        "schritte_ohne_kampf",
        0
    )

    kampf_status.setdefault(
        "cooldown",
        0
    )

    return kampf_status

def kampf_situation_reise(
    reise_daten
):
    gebiet = reise_daten.get(
        "gebiet",
        "Unbekannt"
    )

    if gebiet in (
        "Wald",
        "Waldweg"
    ):
        umgebung = "Dichter Wald"

    else:
        umgebung = "Offener Weg"

    return {
        "gebiet": gebiet,
        "umgebung": umgebung,
        "tageszeit": spieler.get(
            "tageszeit",
            "Tag"
        ),
        "wetter": spieler.get(
            "wetter",
            "Klar"
        )
    }



def reise_abschnitt(reise_daten, kampf_daten):
    # Strecken mit "abschnitte" legen Gegner je nach Lage fest, gezählt vom Ort
    # "abschnitte_von" aus. None: Strecke ohne Abschnitte (wie bisher);
    # False: an dieser Stelle keine Begegnung.
    abschnitte = kampf_daten.get("abschnitte")

    if not abschnitte:
        return None

    schritt = reise_daten.get("aktueller_schritt", 0)

    if reise_daten.get("start") != kampf_daten.get("abschnitte_von"):
        schritt = reise_daten.get("gesamt_schritte", 0) + 1 - schritt

    for abschnitt in abschnitte:
        if abschnitt["von"] <= schritt <= abschnitt["bis"]:
            return abschnitt

    return False


def reise_moegliche_gegner(reise_daten):
    # WM-D2, Fährtenlesen: dieselbe Gegnerauswahl wie in reise_kampfbegegnung_pruefen,
    # ohne Wurf und ohne Zähler. Leer: an dieser Stelle keine gewöhnliche Begegnung.
    kampf_daten = reise_strecken_daten(reise_daten).get("kampfbegegnungen", {})
    if not isinstance(kampf_daten, dict) or not kampf_daten.get("aktiv", False):
        return []
    if (spieler.get("prolog_rueckweg_sicher", False)
            and reise_daten.get("start") == "Köhlerei"
            and reise_daten.get("ziel") == "Eichenruh"):
        return []
    abschnitt = reise_abschnitt(reise_daten, kampf_daten)
    if abschnitt is False:
        return []
    if kampf_daten.get("erst_nach_prolog", False) and spieler.get("prolog_status") != "prolog_abgeschlossen":
        return []
    if abschnitt:
        gegner = list(abschnitt["gegner"])
    elif kampf_daten.get("gegner"):
        gegner = list(kampf_daten["gegner"])
    elif level_fortschritt(spieler)["level"] < 2:
        gegner = ["Bandit", "Wolf"]
    else:
        gegner = ["Bandit", "Wolf", "Keiler"] + (
            list(kampf_daten.get("zusatz_gegner", []))
            if level_fortschritt(spieler)["level"] >= kampf_daten.get("zusatz_ab_level", 2)
            else []
        )
    if kampf_daten.get("schmuggler_chance") and abschnitt and brunnfeld_sperre_aktiv():
        gegner.append("Schmuggler")
    return list(dict.fromkeys(gegner))


# Letzter Reisehinweis: wiederholt nur, wenn sich die möglichen Gegner ändern.
FAEHRTEN_REISE = {"reise": None, "gegner": None}


def faehrten_reisehinweis(reise_daten):
    if not faehrtensteller_aktiv(spieler):
        return
    gegner = reise_moegliche_gegner(reise_daten)
    if FAEHRTEN_REISE["reise"] is reise_daten and FAEHRTEN_REISE["gegner"] == gegner:
        return
    FAEHRTEN_REISE["reise"] = reise_daten
    FAEHRTEN_REISE["gegner"] = gegner
    print()
    if gegner:
        print("[Fährtenlesen] Auf diesem Abschnitt kannst du begegnen: " + ", ".join(gegner) + ".")
    else:
        print("[Fährtenlesen] Du findest keine eindeutigen frischen Fährten.")


def reise_abschnitt_situation(reise_daten, abschnitt):
    situation = kampf_situation_reise(reise_daten)

    if abschnitt and abschnitt.get("umgebung"):
        situation["umgebung"] = abschnitt["umgebung"]

    return situation


def reise_kampfbegegnung_pruefen(
    reise_daten
):
    strecken_daten = (
        reise_strecken_daten(
            reise_daten
        )
    )

    kampf_daten = (
        strecken_daten.get(
            "kampfbegegnungen",
            {}
        )
    )

    if not isinstance(
        kampf_daten,
        dict
    ):
        return False

    if (
        spieler.get(
            "prolog_rueckweg_sicher",
            False
        )
        and reise_daten.get(
            "start"
        ) == "Köhlerei"
        and reise_daten.get(
            "ziel"
        ) == "Eichenruh"
    ):
        return False

    if not kampf_daten.get(
        "aktiv",
        False
    ):
        return False

    abschnitt = reise_abschnitt(reise_daten, kampf_daten)

    if abschnitt is False:
        return False

    # Der ruhige Prolog bleibt kampffrei.
    if (
        kampf_daten.get(
            "erst_nach_prolog",
            False
        )
        and spieler.get(
            "prolog_status"
        ) != "prolog_abgeschlossen"
    ):
        return False

    # Ohne Waffe keine zufällige
    # Kampfbegegnung starten.
    if not spieler.get(
        "waffe"
    ):
        return False

    kampf_status = (
        reise_kampf_status_holen(
            reise_daten,
            strecken_daten
        )
    )

    # Nach einem Kampf einige Schritte Ruhe.
    # Der Cooldown läuft auch dann weiter,
    # wenn auf dieser Reise bereits ein
    # Zufallskampf stattgefunden hat.
    if kampf_status[
        "cooldown"
    ] > 0:
        kampf_status[
            "cooldown"
        ] -= 1

        return False

    kampf_status[
        "schritte_ohne_kampf"
    ] += 1

    max_pro_reise = kampf_daten.get(
        "max_pro_reise",
        1
    )

    bisherige_kaempfe = (
        reise_daten.setdefault(
            "zufallskaempfe",
            0
        )
    )

    if (
        isinstance(
            max_pro_reise,
            int
        )
        and max_pro_reise > 0
        and bisherige_kaempfe
        >= max_pro_reise
    ):
        return False

    chance = kampf_daten.get(
        "chance",
        0
    )

    if kampf_daten.get("schmuggler_chance"):
        # Läuferpfad: Die Ordnung von Kapitel 9 ändert die Tiergefahr.
        chance = brunnfeld_tier_chance(chance)

    garantie_nach = kampf_daten.get(
        "garantie_nach",
        0
    )

    # Leiser Schritt: Begegnungen seltener, Garantie und
    # Ruhezeit nach einem Kampf um ein Drittel länger.
    leiser_schritt = talent_bonus(spieler, "reise_leise") > 0

    if leiser_schritt:
        if isinstance(chance, (int, float)):
            chance = chance * 0.75

        if isinstance(garantie_nach, int) and garantie_nach > 0:
            garantie_nach = -(-garantie_nach * 4 // 3)

    # Nachts und im Nebel sind Begegnungen häufiger. Garantie, Ruhezeit
    # und Höchstzahl pro Reise bleiben unverändert.
    if isinstance(chance, (int, float)):
        if spieler.get("tageszeit") == "Nacht":
            chance = chance * 1.5

        if spieler.get("wetter") == "Nebel":
            chance = chance * 1.25

    zufall_trifft = (
        isinstance(
            chance,
            (int, float)
        )
        and random.random() < chance
    )

    garantie_trifft = (
        isinstance(
            garantie_nach,
            int
        )
        and garantie_nach > 0
        and kampf_status[
            "schritte_ohne_kampf"
        ] >= garantie_nach
    )

    schmuggler_trifft = False

    if not (
        zufall_trifft
        or garantie_trifft
    ):
        # Läuferpfad: Bei gesperrten Zugängen kommen Schmuggler, eigener Wurf.
        schmuggler_trifft = bool(
            kampf_daten.get("schmuggler_chance")
            and abschnitt
            and brunnfeld_sperre_aktiv()
            and random.random() < kampf_daten["schmuggler_chance"]
        )

        if not schmuggler_trifft:
            return False

    kampf_status[
        "schritte_ohne_kampf"
    ] = 0

    kampf_status[
        "cooldown"
    ] = max(
        0,
        int(
            kampf_daten.get(
                "cooldown",
                0
            )
        )
    )

    if leiser_schritt:
        kampf_status["cooldown"] = -(-kampf_status["cooldown"] * 4 // 3)

    reise_daten[
        "zufallskaempfe"
    ] = (
        bisherige_kaempfe
        + 1
    )

    ort_titel(
        "Wald - Begegnung"
    )

    text_ausgeben(
        "Ein Geräusch abseits des Weges "
        "lässt dich stehen bleiben."
    )

    print()

    text_ausgeben(
        "Etwas bewegt sich zwischen "
        "den Bäumen."
    )

    print()

    kampf_ergebnis = kampf_starten(
        lebenspunkte=spieler[
            "lebenspunkte"
        ],
        heiltraenke=spieler[
            "heiltränke"
        ],
        waffe=spieler[
            "waffe"
        ],
        gegner_typ=(
            # Eine Strecke kann ihre Gegner selbst festlegen (Nordstraße: nur Tiere).
            "Schmuggler"
            if schmuggler_trifft
            else random.choice(list(abschnitt["gegner"]))
            if abschnitt
            else random.choice(list(kampf_daten["gegner"]))
            if kampf_daten.get("gegner")
            else random.choice(["Bandit", "Wolf"])
            if level_fortschritt(spieler)["level"] < 2
            else random.choice(
                ["Bandit", "Wolf", "Keiler"]
                + (
                    list(kampf_daten.get("zusatz_gegner", []))
                    if level_fortschritt(spieler)["level"]
                    >= kampf_daten.get("zusatz_ab_level", 2)
                    else []
                )
            )
        ),
        kampf_situation=reise_abschnitt_situation(
            reise_daten,
            abschnitt
        ),
        reise_umgehen=True
    )

    spieler[
        "lebenspunkte"
    ] = kampf_ergebnis[
        "lebenspunkte"
    ]

    spieler[
        "heiltränke"
    ] = kampf_ergebnis[
        "heiltraenke"
    ]

    if kampf_ergebnis.get("umgangen"):
        warte_auf_taste(
            "Weiterreisen"
        )

    elif kampf_ergebnis.get(
        "gewonnen",
        False
    ):
        spieler[
            "besiegte_gegner"
        ] += 1

        gegner_typ = kampf_ergebnis.get(
            "gegner_typ"
        )

        print()
        print("-" * 34)

        design_text(
            "KAMPF GEWONNEN",
            design="positiv",
            art="ereignis"
        )

        print()

        text_ausgeben(
            "Die unmittelbare Gefahr ist vorüber. "
            "Du kommst langsam wieder zu Atem.",
            art="menue"
        )

        spieler[
            "gold"
        ] = kampf_beute_vergeben(
            gegner_typ,
            spieler[
                "gold"
            ],
            ohne_items=kampf_ergebnis.get("gegner_verschont", False)
        )

        print(
            f"Lebenspunkte: "
            f"{spieler['lebenspunkte']}"
        )

        print(
            f"Besiegte Gegner: "
            f"{spieler['besiegte_gegner']}"
        )

        print("-" * 34)

        warte_auf_taste(
            "Weiterreisen"
        )

    elif kampf_ergebnis.get(
        "gegner_geflohen",
        False
    ):
        beute = KAMPF_BEUTE.get(kampf_ergebnis.get("gegner_typ"), {})
        gold = random.randint(
            beute.get("gold_min", 0),
            beute.get("gold_max", 0)
        ) // 2
        spieler["gold"] += gold
        print()
        if gold > 0:
            text_ausgeben(
                f"Auf dem Weg liegen {gold} Gold, die er bei der Flucht verloren hat.",
                art="menue"
            )
        warte_auf_taste(
            "Weiterreisen"
        )
    elif kampf_ergebnis.get(
        "besiegt",
        False
    ):
        print()

        design_text(
            "Game Over",
            design="gefahr",
            art="menue"
        )

        spieler[
            "spiel_laeuft"
        ] = False

    return True

def reise_fortsetzen():
    global TEXT_SKIP_AKTIV
    reise_daten = spieler.get("reise")

    if not reise_daten:
        return

    if riss_koenigsring_ende(reise_daten):
        return

    start = reise_daten["start"]
    ziel = reise_daten["ziel"]
    gebiet = reise_daten["gebiet"]
    gesamt_schritte = reise_daten["gesamt_schritte"]

    zufallsereignisse = reise_daten.get(
        "zufallsereignisse",
        True
    )

    reise_name = reise_daten.get(
        "name",
        gebiet
    )

    erster_angezeigter_schritt = True

    for schritt in range(
        reise_daten["aktueller_schritt"] + 1,
        gesamt_schritte + 1
    ):
        reise_daten["aktueller_schritt"] = schritt

        TEXT_SKIP_AKTIV = False

        reise_titel = (
            reise_name
            if reise_daten.get(
                "weg_id"
            )
            else gebiet
        )

        ort_titel(
            reise_titel
        )

        if erster_angezeigter_schritt:
            ort_nachricht_anzeigen()
            erster_angezeigter_schritt = False

        print(f"{reise_ort_name(start)} → {reise_ort_name(ziel)}")
        print()

        design_text(
            f"Schritt {schritt}/{gesamt_schritte}",
            design="wissen",
            art="menue"
        )

        menue_trenner()

        print()

        schritt_text = reise_schritttext_waehlen(
            reise_daten,
            schritt
        )

        text_ausgeben(
            schritt_text,
            art="atmosphaere"
        )

        faehrten_reisehinweis(reise_daten)

        # -------------------------
        # SELTENE INTERAKTIVE ENTDECKUNG
        # -------------------------

        entdeckung_gezeigt = (
            reise_entdeckung_pruefen(
                reise_daten,
                schritt
            )
        )

        # -------------------------
        # KLEINE REISEBEOBACHTUNG
        # -------------------------

        if not entdeckung_gezeigt:
            beobachtung = (
                reise_beobachtung_waehlen(
                    reise_daten,
                    schritt
                )
            )

            if beobachtung:
                print()

                text_ausgeben(
                    beobachtung,
                    art="atmosphaere"
                )

        if reise_bekannte_abzweigung_vorhanden(
            reise_daten,
            schritt
        ):
            menue_trenner()
            print()

            print("1. Weitergehen")
            print("2. Umgebung erkunden [!]")

            schritt_auswahl = eingabe_menu(
                1,
                2,
                sonder_tasten=()
            )

            if schritt_auswahl == 2:
                if reise_abzweigungen_pruefen(
                    reise_daten,
                    schritt,
                    ziel,
                    erkundung=True
                ):
                    status_schritte_abschliessen()
                    return

                print()

                warte_auf_taste(
                    "Weitergehen"
                )

        else:
            warte_auf_taste(
                "Weitergehen"
            )

        if gebiet in (
            "Wald",
            "Waldweg"
        ):
            ressourcen_vorkommen_regenerieren(
                "wald_holz"
            )

        stollen_regenerieren()
        frist_handlung(1)

        festes_ereignis = (
            reise_ereignisse_pruefen(
                reise_daten,
                schritt
            )
        )

        kampfbegegnung = False

        if (
            not festes_ereignis
            and not entdeckung_gezeigt
        ):
            kampfbegegnung = (
                reise_kampfbegegnung_pruefen(
                    reise_daten
                )
            )

        if not spieler[
            "spiel_laeuft"
        ]:
            return


        if (
            zufallsereignisse
            and not festes_ereignis
            and not kampfbegegnung
        ):
            spieler["gold"], spieler["heiltränke"], spieler["diamanten"], \
            spieler["lebenspunkte"], spieler["spiel_laeuft"], \
            spieler["besiegte_gegner"], spieler["ort"] = zufallsereignis(
                spieler["gold"],
                spieler["heiltränke"],
                spieler["diamanten"],
                spieler["lebenspunkte"],
                spieler["spiel_laeuft"],
                spieler["besiegte_gegner"],
                spieler["ort"]
            )

            if not spieler["spiel_laeuft"]:
                return

            if spieler["fackel_dauer"] > 0:
                spieler["fackel_dauer"] -= 1

                if spieler["fackel_dauer"] == 0:
                    print()
                    print(
                        "Deine Fackel flackert ein letztes Mal auf "
                        "und erlischt."
                    )
            warte_auf_taste("Weiterreisen")


        if reise_abzweigungen_pruefen(
            reise_daten,
            schritt,
            ziel
        ):
            status_schritte_abschliessen()
            return

        if not status_schritte_abschliessen():
            return

        if schritt < gesamt_schritte:
            return


    ankunft_zeilen = reise_daten["ankunft_zeilen"]

    spieler["reise"] = None
    spieler["ort"] = ziel
    archiv_ankunft(ziel)

    if (
        spieler.get(
            "prolog_rueckweg_sicher",
            False
        )
        and start == "Köhlerei"
        and ziel == "Eichenruh"
    ):
        spieler[
            "prolog_rueckweg_sicher"
        ] = False

    if akt1_reise_lernerfahrung(
        start,
        ziel
    ):
        warte_auf_taste("Weitergehen")

    # Eine vollständig abgeschlossene Normalreise macht die Strecke
    # vertraut (nur Strecken mit "routenkenntnis_automatisch").
    abgeschlossene_strecke = reise_strecken_daten(
        reise_daten
    )

    if abgeschlossene_strecke.get(
        "routenkenntnis_automatisch",
        False
    ):
        kenntnis_id = abgeschlossene_strecke.get(
            "routenkenntnis_id",
            abgeschlossene_strecke.get("weg_id")
        )

        if (
            kenntnis_id
            and routenkenntnis_lernen(kenntnis_id)
        ):
            warte_auf_taste("Weitergehen")

    ort_nachricht_setzen(
        *ankunft_zeilen
    )


def prolog_ort_besucht(ort_name):

    if spieler.get("prolog_status") != "dorf_freigeschaltet":
        return

    besuchte_orte = spieler.get("prolog_besuchte_orte", {})

    if ort_name not in besuchte_orte:
        return

    if besuchte_orte[ort_name]:
        return

    besuchte_orte[ort_name] = True

    anzahl_besucht = sum(besuchte_orte.values())

    if anzahl_besucht == 3:
        spieler["prolog_status"] = "dorf_kennengelernt"

def prolog_laeuft():
    return spieler.get("prolog_status") != "prolog_abgeschlossen"

def prolog_joris_hinweis(quelle):
    hinweise = spieler.setdefault(
        "prolog_joris_hinweise",
        {
            "mara": False,
            "tomas": False
        }
    )

    if quelle not in hinweise:
        return

    if hinweise[quelle]:
        return

    hinweise[quelle] = True

    if all(hinweise.values()):
        spieler["prolog_status"] = "joris_hinweise_komplett"

        quest_meldung(
            "update",
            "Der verlorene Lehrling",
            "Berichte Bjorn, was du über Joris herausgefunden hast."
        )

def quest_meldung(
    status,
    name,
    ziel=None,
    belohnungen=None
):
    print()
    print("=" * 34)

    if status == "neu":
        design_text(
            "NEUE QUEST",
            design="quest_neu",
            art="ereignis"
        )

    elif status == "update":
        design_text(
            "QUEST AKTUALISIERT",
            design="quest_update",
            art="ereignis"
        )

    elif status == "abgeschlossen":
        design_text(
            "QUEST ABGESCHLOSSEN",
            design="quest_abgeschlossen",
            art="ereignis"
        )

    design_text(
        name,
        design="wichtig",
        art="menue"
    )

    # -------------------------
    # QUESTZIEL
    # -------------------------

    if ziel:
        print()

        design_text(
            "Ziel:",
            design="wissen",
            art="menue"
        )

        print(
            ziel
        )

    # -------------------------
    # BELOHNUNGEN
    # -------------------------

    if (
        status == "abgeschlossen"
        and belohnungen
    ):
        if isinstance(
            belohnungen,
            str
        ):
            belohnungen = [
                belohnungen
            ]

        print()

        design_text(
            "Belohnungen:",
            design="wissen",
            art="menue"
        )

        for belohnung in belohnungen:
            print(
                f"- {belohnung}"
            )

    print("=" * 34)
    print()

