def letzthafen_status():
    daten = spieler.setdefault(
        "letzthafen_status",
        {}
    )

    daten.setdefault(
        "angekommen",
        False
    )

    daten.setdefault(
        "besuchte_bereiche",
        []
    )

    spuren = daten.setdefault(
        "spuren",
        {}
    )

    spuren.setdefault(
        "sera_marek",
        False
    )

    spuren.setdefault(
        "marek_getroffen",
        False
    )

    spuren.setdefault(
        "marek_widerspruch",
        False
    )

    spuren.setdefault(
        "marek_muster_erkannt",
        False
    )


    spuren.setdefault(
        "register_marek",
        False
    )

    spuren.setdefault(
        "marek_adresse_bekannt",
        False
    )

    spuren.setdefault(
        "oros_abschrift",
        False
    )

    spuren.setdefault(
        "marek_zimmer_betreten",
        False
    )

    spuren.setdefault(
        "rueckkehrkerben",
        False
    )

    spuren.setdefault(
        "wegmuenzen_gefunden",
        False
    )

    spuren.setdefault(
        "elian_hinweis",
        False
    )

    spuren.setdefault(
        "elian_getroffen",
        False
    )

    spuren.setdefault(
        "brueder_begegnung",
        False
    )

    spuren.setdefault(
        "marek_widerspruch",
        False
    )


    spuren.setdefault(
        "marek_notizbuch",
        False
    )

    wiegenlied = daten.setdefault(
        "wiegenlied",
        {}
    )

