def stelle_schreiber_bauliste():
    text_ausgeben(
        "[Schreiber] Steine. Nicht Waren, nicht Namen. Steine."
    )

    text_ausgeben(
        "[Schreiber] Die meisten fragen, wer angekommen ist. Du fragst, was "
        "geblieben ist."
    )

    print()

    text_ausgeben(
        "Er zieht ein flaches, salzfleckiges Buch aus dem untersten Regal."
    )

    print()

    text_ausgeben(
        "[Schreiber] Baulisten. Wer hier etwas baut, trägt es ein. Auch wenn "
        "es nur eine Mauer ist."
    )

    print()

    text_ausgeben(
        "Holz, Kalk, Seil. Dann eine Zeile in schwerer, schräger Handschrift:"
    )

    print()

    design_text(
        "„Fundamentstein vom Steg heraufgeholt. Zu schwer zum Wegwerfen, "
        "gut genug zum Bauen. Für den Signalturm.“",
        design="wissen",
        art="menue"
    )

    print()

    text_ausgeben(
        "Kein Datum. Daneben nur das Zeichen eines Steinmetzes."
    )

    print()

    text_ausgeben(
        "[Schreiber] Der Signalturm. Heute schenkt Sera dort aus."
    )

    if (
        untersuchung_pruefung("wissen", 2)
        and not spieler.get("stelle_bauliste_schema_erkannt", False)
    ):
        menue_trenner()

        print()

        print(
            "1. Die Einträge genauer vergleichen [Wissen]"
        )

        print(
            "2. Weiter"
        )

        schema_auswahl = eingabe_menu(
            1,
            2,
            sonder_tasten=()
        )

        if schema_auswahl == 1:
            text_ausgeben(
                "Der Eintrag folgt einem älteren Schema als die Seiten danach."
            )

            text_ausgeben(
                "Material und Verwendung wurden notiert, Herkunft nur dann, "
                "wenn etwas wiederverwendet wurde."
            )

            spieler[
                "stelle_bauliste_schema_erkannt"
            ] = True

            akt1_lernerfahrung(
                "stelle_bauliste_schema"
            )

    spieler[
        "quest_was_an_seine_stelle_trat"
    ] = "steg_untersuchen"

    quest_meldung(
        "update",
        "Was an seine Stelle trat",
        "Sieh dir am Gezeitensteg an, woher der Stein stammt."
    )

    warte_auf_taste(
        "Weiter"
    )


def stelle_steg_untersuchen():
    ort_titel(
        "Gezeitensteg"
    )

    text_ausgeben(
        "Das Wasser steht niedrig. Zwischen Tang und nassem Fels liegt ein "
        "Stück Ufer frei, das sonst unter Wasser ist."
    )

    print()

    text_ausgeben(
        "Am Fuß des Stegs ist der Fels glatt geschliffen, in einer flachen, "
        "fast rechteckigen Vertiefung."
    )

    text_ausgeben(
        "Zu groß für einen Poller. Zu sorgfältig für das Meer."
    )

    print()

    text_ausgeben(
        "Am Rand der Vertiefung sitzt eine Kerbe. Dieselbe Form wie am "
        "Wegstein. Sie zeigt aufs offene Wasser."
    )

    if (
        spieler_pruefung("sensibilitaet", 2)
        and not spieler.get("stelle_steg_gespuert", False)
    ):
        menue_trenner()

        print()

        print(
            "1. Dich auf die Vertiefung konzentrieren [Sensibilität]"
        )

        print(
            "2. Weiter"
        )

        steg_auswahl = eingabe_menu(
            1,
            2,
            sonder_tasten=()
        )

        if steg_auswahl == 1:
            text_ausgeben(
                "Die Vertiefung ist leer. Das Gefühl darum herum ist es nicht."
            )

            spieler[
                "stelle_steg_gespuert"
            ] = True

            akt1_lernerfahrung(
                "stelle_steg_sensibilitaet"
            )

    spieler[
        "quest_was_an_seine_stelle_trat"
    ] = "sera_fragen"

    quest_meldung(
        "update",
        "Was an seine Stelle trat",
        "Frag Sera im „Zum letzten Licht“ nach dem Fundament."
    )

    warte_auf_taste(
        "Weiter"
    )


