def dialog_schreiber_letzthafen():
    while True:
        ort_titel(
            "Haus der Listen"
        )

        dialog_titel(
            "Schreiber"
        )

        spuren = letzthafen_status()[
            "spuren"
        ]

        quest_status = spieler.get(
            "quest_ein_name_fehlt"
        )

        marek_relevant = (
            quest_status in (
                "marek_spur_suchen",
                "marek_identitaet_pruefen",
                "marek_wohnung_untersuchen"
            )
            or spuren.get(
                "register_marek",
                False
            )
        )

        text_ausgeben(
            "Der Schreiber sitzt hinter einem breiten Pult. "
            "Seine Fingerkuppen sind dunkel von Tinte."
        )

        print()

        naechste_option = 1
        marek_option = None

        if marek_relevant:
            marek_option = naechste_option

            if spuren.get(
                "register_marek",
                False
            ):
                print(
                    f"{naechste_option}. "
                    "Mareks Einträge erneut ansehen"
                )

            elif (
                spuren.get(
                    "sera_marek",
                    False
                )
                or spuren.get(
                    "marek_getroffen",
                    False
                )
                or besonderer_fund_status(
                    "stationsregister"
                ) == "gelesen"
            ):
                print(
                    f"{naechste_option}. "
                    "Nach Marek Voss suchen"
                )

            else:
                print(
                    f"{naechste_option}. "
                    "Nach dem Fuhrmann aus Eichenruh fragen"
                )

            naechste_option += 1

        stelle_option = None

        if stelle_quest_status() == "schreiber_fragen":
            stelle_option = naechste_option

            print(
                f"{naechste_option}. "
                "Nach bewegten Steinen fragen [!]"
            )

            naechste_option += 1

        haus_option = naechste_option

        print(
            f"{naechste_option}. "
            "Was wird hier alles aufbewahrt?"
        )

        naechste_option += 1

        ende_option = naechste_option

        print(
            f"{naechste_option}. Gespräch beenden"
        )

        auswahl = eingabe_menu(
            1,
            ende_option,
            sonder_tasten=()
        )

        print()

        if (
            marek_option is not None
            and auswahl == marek_option
        ):
            letzthafen_marek_register_lesen()

        elif (
            stelle_option is not None
            and auswahl == stelle_option
        ):
            stelle_schreiber_bauliste()

        elif auswahl == haus_option:
            dialog_thema_markieren(
                "schreiber_letzthafen",
                "aufzeichnungen"
            )

            text_ausgeben(
                "[Schreiber] Handel. Schiffe. Bewohner. "
                "Geburten, Todesfälle, Besitzwechsel."
            )

            print()

            text_ausgeben(
                "[Schreiber] Alles, was später jemand "
                "bestreiten könnte."
            )

            print()

            text_ausgeben(
                "[Schreiber] Ein Hafen lebt davon, dass zwei "
                "Leute sich morgen noch darauf einigen können, "
                "was gestern war."
            )

            warte_auf_taste(
                "Weiter"
            )

        elif auswahl == ende_option:
            return

