        if auswahl == zurueck_option:
            return None

        speicher_datei = (
            speicherdatei_pfad(
                auswahl
            )
        )

        if not os.path.exists(
            speicher_datei
        ):
            return auswahl

        print()

        design_text(
            "SPIELSTAND VORHANDEN",
            design="warnung",
            art="menue"
        )

        print()
        print(
            "Dieser Speicherplatz enthält "
            "bereits einen Spielstand."
        )

        print()
        print(
            "Wenn du hier ein neues Spiel startest, "
            "wird der alte Spielstand überschrieben."
        )

        menue_trenner()
        print()

        print(
            "1. Trotzdem verwenden"
        )

        print(
            "2. Anderen Speicherplatz wählen"
        )

        bestaetigung = eingabe_menu(
            1,
            2,
            sonder_tasten=()
        )

        if bestaetigung == 1:
            return auswahl

