def verfassung_praegungsziel(
    wert
):
    if wert <= 0:
        return 4

    if wert == 1:
        return 10

    if wert == 2:
        return 18

    return None


def verfassung_effekt_text(
    verfassung_id,
    pruefwert
):
    if (
        isinstance(
            pruefwert,
            bool
        )
        or not isinstance(
            pruefwert,
            (int, float)
        )
    ):
        return None

    wert = int(
        pruefwert
    )

    if verfassung_id == "staerke":
        faktor = 1.0 + (
            wert - 2
        ) * 0.03

        faktor = max(
            0.90,
            min(
                1.25,
                faktor
            )
        )

        prozent = round(
            (
                faktor - 1.0
            ) * 100
        )

        if prozent > 0:
            return (
                f"Kampf: Waffenschaden "
                f"+{prozent} %"
            )

        if prozent < 0:
            return (
                f"Kampf: Waffenschaden "
                f"{prozent} %"
            )

        return (
            "Kampf: Waffenschaden ±0 %"
        )

    if verfassung_id == "ausdauer":
        stufen = max(
            0,
            min(
                3,
                wert - 1
            )
        )

        bonus = (
            stufen * 5
        )

        return (
            f"Kampf: +{bonus} auf "
            "Verteidigungs- und Fluchtchance"
        )

    if verfassung_id == "geschick":
        bewegung = max(
            0,
            min(
                3,
                wert - 1
            )
        )

        return (
            f"Kampf: Bewegung "
            f"+{bewegung} | "
            "bessere Deckung/Parade"
        )

    if verfassung_id == "zaehigkeit":
        stufen = max(
            0,
            min(
                3,
                wert - 1
            )
        )

        reduktion = (
            stufen * 5
        )

        return (
            f"Kampf: "
            f"{reduktion} % "
            "Schadensreduktion"
        )

    if verfassung_id == "wissen":
        return (
            f"Prüfwert {wert}: "
            "Wissen und Analyse"
        )

    if verfassung_id == "wahrnehmung":
        sicht = max(
            0,
            min(
                3,
                wert - 1
            )
        )

        return (
            f"Kampf: Sicht "
            f"+{sicht} | "
            "bessere Entdeckung"
        )

    if verfassung_id == "willenskraft":
        return (
            f"Prüfwert {wert}: "
            "mentaler Druck"
        )

    if verfassung_id == "empathie":
        return (
            f"Prüfwert {wert}: "
            "Gefühle und Motive"
        )

    return None


def verfassung_status_anzeigen(
    verfassung_id
):
    definition = (
        VERFASSUNG_DEFINITIONEN[
            verfassung_id
        ]
    )

    attribut_id = definition[
        "attribut"
    ]

    attribut_wert = spieler[
        "attribute"
    ].get(
        attribut_id,
        0
    )

    verfassung_wert = spieler[
        "verfassungen"
    ].get(
        verfassung_id,
        0
    )

    praegung = spieler[
        "verfassungs_praegung"
    ].get(
        verfassung_id,
        0
    )

    basis_pruefwert = (
        attribut_wert
        + verfassung_wert
    )

    aktueller_pruefwert = (
        spieler_pruefwert(
            verfassung_id
        )
    )

    if verfassung_wert > 0:
        vergleich = (
            f"+{verfassung_wert}"
        )

    elif verfassung_wert < 0:
        vergleich = (
            str(
                verfassung_wert
            )
        )

    else:
        vergleich = "="

    ziel = verfassung_praegungsziel(
        verfassung_wert
    )

    if ziel is None:
        praegung_text = (
            f"{praegung} Prägung"
        )

    else:
        praegung_text = (
            f"{praegung}/{ziel} Prägung"
        )

    print(
        f"{definition['name']}: "
        f"{basis_pruefwert} "
        f"({vergleich}) | "
        f"{praegung_text}"
    )

    if (
        isinstance(
            aktueller_pruefwert,
            (int, float)
        )
        and not isinstance(
            aktueller_pruefwert,
            bool
        )
        and aktueller_pruefwert
        != basis_pruefwert
    ):
        print(
            f"  Aktuell durch Status: "
            f"{aktueller_pruefwert:g}"
        )

    effekt = verfassung_effekt_text(
        verfassung_id,
        aktueller_pruefwert
    )

    if effekt:
        print(
            f"  {effekt}"
        )

