SELENE_UEBUNGEN_REIHE = (
    "wm_lauschen_uebung", "wm_resonanz_uebung", "wm_kontrolle_uebung", "wm_anker_uebung"
)


def selene_uebung(kennung):
    uebung = SELENE_UEBUNGEN[kennung]
    ort_titel("Selene – " + uebung["name"])

    for zeile in uebung["einleitung"]:
        text_ausgeben(zeile)

    wahl = chronik_auswahl([
        ("falsch", uebung["falsch"]),
        ("richtig", uebung["richtig"]),
        ("zurueck", "Übung abbrechen")
    ])

    if wahl == "zurueck":
        return

    for zeile in uebung["bei_" + wahl]:
        text_ausgeben(zeile)

    if wahl == "richtig" and wm_lernen(kennung) and uebung["technik"]:
        design_text(f"Neue Technik: {uebung['technik']}", design="positiv", art="menue")

    warte_auf_taste("Weiter")


def selene_erlebtes():
    # Anrechnung nur hier, beim ausdrücklichen Besuch; beim Laden geschieht nichts.
    ort_titel("Selene – Über das Erlebte")
    text_ausgeben("[Selene] Erzähl. Nicht was passiert ist. Was du dabei gespürt hast.")
    eintraege = wm_erlebtes_offen()

    for kennung, zeile in eintraege:
        print()
        text_ausgeben(zeile)
        wm_lernen(kennung)

    if wm_stein_offen():
        print()
        if chronik_auswahl([
            ("stein", "Selenes Steinübung versuchen"),
            ("zurueck", "Zurück")
        ]) == "stein":
            selene_uebung("wm_resonanz_stein")
        return

    if not eintraege:
        text_ausgeben(
            "[Selene] Dann ist im Moment nichts liegen geblieben. Komm wieder, "
            "wenn dir etwas begegnet."
        )

    warte_auf_taste("Zurück")


def selene_magier_menue():
    text_ausgeben("Selene sieht von der Sandschale auf.")
    text_ausgeben("[Selene] Du kommst wieder. Gut. Üben hört nicht auf, nur weil man es kann.")
    erstes_mal = True

    while True:
        if not erstes_mal:
            ort_titel("Selene – Magierausbildung")
        erstes_mal = False
        uebungen = [kennung for kennung in SELENE_UEBUNGEN_REIHE if not wm_gelernt(kennung)]

        if wm_stein_offen():
            uebungen.append("wm_resonanz_stein")

        wahl = chronik_auswahl([
            ("ueben", "Mit Selene üben" + (" [!]" if uebungen else "")),
            ("erlebt", "Mit Selene über das Erlebte sprechen" + (" [!]" if wm_erlebtes_offen() else "")),
            ("klasse", "Grundklasse ansehen"),
            ("zurueck", "Zurück")
        ])

        if wahl == "zurueck":
            return
        if wahl == "klasse":
            klassenmenue()
        elif wahl == "erlebt":
            selene_erlebtes()
        elif not uebungen:
            text_ausgeben(
                "[Selene] Mehr kann ich dir gerade nicht zeigen. Den Rest lehrt "
                "dich, was dir begegnet."
            )
            warte_auf_taste("Weiter")
        else:
            auswahl = chronik_auswahl(
                [(kennung, SELENE_UEBUNGEN[kennung]["name"]) for kennung in uebungen]
                + [("zurueck", "Zurück")]
            )

            if auswahl != "zurueck":
                selene_uebung(auswahl)


def wm_gegenpunkt_klang():
    # Ersatzweg für den Amboss (E1); behauptet keinen Kontakt zur Dorfseite.
    ort_titel("Rand der Senke")
    text_ausgeben("Du kniest dich an den Gegenpunkt und klopfst mit dem Knöchel dagegen.")
    text_ausgeben(
        "Erst hörst du nur dein Klopfen. Dann, beim zweiten Mal, einen tieferen "
        "Ton darunter, der nicht vom Knöchel kommt, sondern vom Boden, auf dem "
        "der Stein steht."
    )
    text_ausgeben("Du klopfst noch einmal. Diesmal wartest du auf den tieferen Ton.")
    wm_lernen("wm_resonanz_klang")
    warte_auf_taste("Zurück")


def selene_magier_ausbildung():
    ort_titel("Selene – Magierausbildung")
    npc_besuch_starten("selene")

    # WM-B2: Magier üben bei Selene weiter.
    if spieler.get("prolog_status") == "prolog_abgeschlossen" and grundklasse_holen(spieler) == "magier":
        selene_magier_menue()
        return

    text_ausgeben(
        "Magistra Selene steht vor einer Schale mit feinem Sand."
    )
    print()
    text_ausgeben(
        "[Selene] Wahrnehmen und Wirken sind verschiedene Dinge. Ich kann dir "
        "zeigen, wie du eine Resonanz kontrollierst. Erleben musst du sie selbst."
    )
    print()

    # WM-B2: Über das Erlebte sprechen kann jede erwachte Figur.
    if spieler.get("prolog_status") == "prolog_abgeschlossen" and (wm_erlebtes_offen() or wm_stein_offen()):
        wahl = chronik_auswahl([
            ("ausbildung", "Über die Magierausbildung sprechen"),
            ("erlebt", "Mit Selene über das Erlebte sprechen [!]"),
            ("zurueck", "Zurück")
        ])

        if wahl == "erlebt":
            selene_erlebtes()
            return
        if wahl == "zurueck":
            return

    print("Die Ausbildung legt deine Grundklasse noch nicht fest.")
    if spieler.get("prolog_status") != "prolog_abgeschlossen":
        print("Schließe zuerst den Prolog ab.")
        warte_auf_taste("Zurück")
        return
    if grundklasse_holen(spieler) == "magier":
        klassenmenue()
        return
    daten = spieler.get("klasse", {})
    ausbildungen = daten.get("ausbildungen", []) if isinstance(daten, dict) else []
    if isinstance(ausbildungen, list) and "magier" in ausbildungen:
        print("Selenes Magierausbildung hast du bereits abgeschlossen.")
        warte_auf_taste("Grundklasse ansehen")
        klassenmenue(wechsel_klasse="magier")
        return
    for wert_id, name, minimum in (("geist", "Geist", 2), ("uebersinnliches", "Übersinnliches", 1)):
        wert = klassen_eigener_wert(spieler, wert_id)
        if wert is None or wert < minimum:
            print()
            text_ausgeben("[Selene] Entwickle dein Verständnis und erlebe deine eigene Resonanz.")
            print()
            print(f"Voraussetzung: {name} {minimum} (eigener Wert)")
            print("Ausrüstung und vorübergehende Effekte zählen dafür nicht.")
            warte_auf_taste("Zurück")
            return
    print("Keine Gold- oder Talentpunktkosten.")
    print()
    print("1. Unter Selenes Anleitung üben")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) != 1:
        return
    text_ausgeben(
        "Selene lässt einen schmalen Metallring über der Sandschale schwingen. "
        "Du nimmst etwas wahr, das nicht allein seinem sichtbaren Ausschlag folgt."
    )
    print()
    print("1. Nur die Bewegung des Rings nachahmen")
    print("2. Ruhig werden und auf die wahrgenommene Resonanz achten")
    print("3. Ausbildung abbrechen")
    antwort = eingabe_menu(1, 3, sonder_tasten=())
    if antwort != 2:
        if antwort == 1:
            text_ausgeben("[Selene] Deine Hände bewegen sich. Deine Resonanz bleibt ungeordnet.")
            warte_auf_taste("Zurück")
        return
    text_ausgeben(
        "Im Sand entsteht eine feine Furche. Selene hebt die Hand."
    )
    print()
    text_ausgeben(
        "[Selene] Halte die Wirkung klein. Mehr Kraft ersetzt keine Kontrolle."
    )
    print()
    print("1. Die Resonanz begrenzen und gleichmäßig bündeln")
    print("2. Möglichst viel Kraft auf einmal freisetzen")
    print("3. Ausbildung abbrechen")
    antwort = eingabe_menu(1, 3, sonder_tasten=())
    if antwort != 1:
        if antwort == 2:
            text_ausgeben("Selene unterbricht die Übung.")
            print()
            text_ausgeben("[Selene] Langsamer. Halte den Ring ruhig, bevor du ihn schwingen lässt.")
            warte_auf_taste("Zurück")
        return
    text_ausgeben(
        "Die Furche hält ihre Form."
    )
    print()
    text_ausgeben(
        "[Selene] Jetzt löse sie bewusst. "
        "Eine Wirkung, die du nicht beenden kannst, beherrschst du nicht."
    )
    print()
    print("1. Die Resonanz unkontrolliert weiterlaufen lassen")
    print("2. Die Bündelung lösen und die Wirkung beenden")
    print("3. Ausbildung abbrechen")
    antwort = eingabe_menu(1, 3, sonder_tasten=())
    if antwort != 2:
        if antwort == 1:
            text_ausgeben("Selene beendet die Übung.")
            print()
            text_ausgeben("[Selene] Du musst auch loslassen können.")
            warte_auf_taste("Zurück")
        return
    if klassenausbildung_abschliessen(spieler, "magier"):
        print("Magierausbildung abgeschlossen.")
        text_ausgeben("[Selene] Vergleiche die Wege, bevor du dich entscheidest.")
        warte_auf_taste("Grundklasse ansehen")
        klassenmenue(wechsel_klasse="magier")
    else:
        print("Der vorhandene Klassenstand konnte nicht ergänzt werden.")
        warte_auf_taste("Zurück")

