def waffe_verkaufen():
    while True:
        ort_titel(
            "Bjorns Schmiede - Waffen verkaufen"
        )

        print(
            f"Gold: {spieler['gold']}"
        )

        print()

        if len(
            spieler["waffen_inventar"]
        ) == 0:
            print(
                "Du hast keine Waffe, "
                "die du verkaufen kannst."
            )

            warte_auf_taste(
                "Zurück"
            )

            return

        for i, waffe in enumerate(
            spieler["waffen_inventar"]
        ):
            if (
                waffe["name"]
                == "Hammer des Weges"
            ):
                print(
                    f"{i + 1}. {waffe['name']} "
                    "- unverkäuflich"
                )

            else:
                print(
                    f"{i + 1}. {waffe_anzeigename(waffe)} "
                    f"- {waffe['verkaufswert']} Gold"
                )

            waffenvergleich_anzeigen(waffe)
            print()

        zurueck_nummer = (
            len(
                spieler["waffen_inventar"]
            ) + 1
        )

        print(
            f"{zurueck_nummer}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=()
        )

        if auswahl == zurueck_nummer:
            return

        waffe = spieler[
            "waffen_inventar"
        ][
            auswahl - 1
        ]

        if (
            waffe["name"]
            == "Hammer des Weges"
        ):
            design_text(
                "Diese Waffe kannst du nicht verkaufen.",
                design="warnung",
                art="menue"
            )

            warte_auf_taste(
                "Weiter"
            )

            continue

        if not handel_bestaetigen(waffe_anzeigename(waffe), 1, waffe["verkaufswert"], verkauf=True):
            continue

        waffe = spieler[
            "waffen_inventar"
        ].pop(
            auswahl - 1
        )

        spieler["gold"] += (
            waffe["verkaufswert"]
        )

        design_text(
            f"{waffe_anzeigename(waffe)} verkauft",
            design="positiv",
            art="menue"
        )

        print()
        print(
            f"Du erhältst "
            f"{waffe['verkaufswert']} Gold."
        )

        print(
            f"Gold: {spieler['gold']}"
        )

        warte_auf_taste(
            "Weiter"
        )

