def holz_sammeln():
    ort_titel("Wald - Holzsuche")

    vorkommen_id = "wald_holz"

    status = ressourcen_vorkommen_status(
        vorkommen_id
    )

    daten = RESSOURCEN_VORKOMMEN[
        vorkommen_id
    ]

    if status["vorrat"] <= 0:
        print(
            "In diesem Teil des Waldes findest du "
            "kaum noch brauchbares Totholz."
        )

        print()
        print(
            "Der Abschnitt braucht etwas Zeit, "
            "bevor sich wieder genug trockenes Holz "
            "finden lässt."
        )

        warte_auf_taste()
        return

    text_ausgeben(
        "Du verlässt den Weg für einen Moment und suchst "
        "zwischen Wurzeln und trockenem Unterholz."
    )

    text_ausgeben(
        "Du achtest darauf, nur trockenes Holz mitzunehmen, "
        "das sich später gut entzünden lässt."
    )

    gefundene_menge = min(
        random.randint(
            daten["fund_min"],
            daten["fund_max"]
        ),
        status["vorrat"]
    )

    item_hinzufuegen(
        daten["item_id"],
        gefundene_menge
    )

    status["vorrat"] -= (
        gefundene_menge
    )

    akt1_lernerfahrung(
        "holzsuche"
    )

    print()

    design_text(
        f"{gefundene_menge}x Holz gesammelt",
        design="positiv",
        art="menue"
    )

    print(
        f"Holz insgesamt: "
        f"{item_anzahl('holz')}"
    )

    if status["vorrat"] == 0:
        print()
        print(
            "Viel brauchbares Totholz ist hier "
            "vorerst nicht mehr übrig."
        )

    elif status["vorrat"] == 1:
        print()
        print(
            "In diesem Teil des Waldes wird "
            "brauchbares Totholz langsam knapp."
        )

    warte_auf_taste()

def lagerfeuer():
    ort_titel("Lagerfeuer")

    holz_kosten = 2
    heilung = 25 + talent_bonus(spieler, "heilung_bonus")

    print(
        f"Für ein Lagerfeuer brauchst du "
        f"{holz_kosten} Holz."
    )

    print(
        f"Du besitzt: "
        f"{item_anzahl('holz')} Holz"
    )

    print()

    if not item_besitzt(
        "holz",
        holz_kosten
    ):
        print(
            "Du hast nicht genug trockenes Holz."
        )

        warte_auf_taste()
        return

    print("1. Lagerfeuer entzünden")
    print("2. Zurück")

    auswahl = eingabe_menu(
        1,
        2,
        sonder_tasten=()
    )

    if auswahl == 2:
        return

    item_entfernen(
        "holz",
        holz_kosten
    )

    ort_titel("Lagerfeuer")

    text_ausgeben(
        "Du sammelst das trockene Holz zu einer "
        "kleinen Feuerstelle."
    )

    text_ausgeben(
        "Nach einigen Versuchen greifen die Flammen."
    )

    print()

    print(
        f"Verbleibendes Holz: "
        f"{item_anzahl('holz')}"
    )

    warte_auf_taste(
        "Am Feuer Platz nehmen"
    )

    geruht = False

    while True:
        ort_titel("Lagerfeuer")

        print(
            f"Lebenspunkte: "
            f"{spieler['lebenspunkte']}/100"
        )

        print()
        print(
            "Das Feuer brennt ruhig vor dir."
        )

        print()
        print("1. Am Feuer ausruhen")
        print("2. Am Feuer kochen")
        print("3. Feuer verlassen")

        feuer_auswahl = eingabe_menu(
            1,
            3,
            sonder_tasten=()
        )

        if feuer_auswahl == 1:
            if geruht:
                print()
                print(
                    "Du hast dich an diesem Feuer "
                    "bereits ausgeruht."
                )

                warte_auf_taste()
                continue

            if spieler["lebenspunkte"] >= 100:
                print()
                print(
                    "Du bist bereits vollständig erholt."
                )

                warte_auf_taste()
                continue

            alte_lebenspunkte = spieler[
                "lebenspunkte"
            ]

            spieler["lebenspunkte"] = min(
                100,
                spieler["lebenspunkte"] + heilung
            )

            geheilt = (
                spieler["lebenspunkte"]
                - alte_lebenspunkte
            )

            geruht = True

            print()

            text_ausgeben(
                "Du setzt dich in die Wärme und ruhst "
                "dich eine Weile aus."
            )

            print()

            design_text(
                f"Du regenerierst {geheilt} Lebenspunkte.",
                design="positiv",
                art="menue"
            )

            print(
                f"Lebenspunkte: "
                f"{spieler['lebenspunkte']}/100"
            )

            warte_auf_taste()

        elif feuer_auswahl == 2:
            if (
                item_besitzt(
                    "wildfleisch"
                )
                and not rezept_ist_gelernt(
                    "gebratenes_wildfleisch"
                )
            ):
                print()

                text_ausgeben(
                    "Das rohe Wildfleisch lässt sich "
                    "direkt über der Glut zubereiten."
                )

                rezept_lernen(
                    "gebratenes_wildfleisch"
                )

                warte_auf_taste(
                    "Weiter"
                )

            kochen(
                titel="Kochen am Lagerfeuer"
            )

        elif feuer_auswahl == 3:
            return

def gegenstaende_inventar():
    while True:
        ort_titel("Inventar - Gegenstände")

        inventar_items = spieler.get(
            "inventar_items",
            {}
        )

        gruppen_definitionen = [
            ("Nahrung und Verbrauchsgüter",
             {"Nahrung", "Mahlzeit", "Verbrauchsgegenstand"}),
            ("Materialien und Zutaten", {"Material", "Ressource", "Zutat"}),
            ("Questgegenstände", {"Questgegenstand"}),
            ("Aufzeichnungen und Funde",
             {"Reiseunterlage", "Aufzeichnung", "Besonderer Fund"}),
            ("Sonstiges", set())
        ]
        gruppen = [[] for _ in gruppen_definitionen]

        for item_id, anzahl in inventar_items.items():
            if item_id not in ITEMS:
                continue

            typ = ITEMS[item_id].get("typ", "")
            gruppe_index = len(gruppen) - 1
            for index, (_, typen) in enumerate(gruppen_definitionen):
                if typ in typen:
                    gruppe_index = index
                    break
            gruppen[gruppe_index].append((item_id, anzahl))

        for gruppe in gruppen:
            gruppe.sort(key=lambda eintrag: ITEMS[eintrag[0]]["name"].casefold())

        sichtbare_items = [
            eintrag
            for gruppe in gruppen
            for eintrag in gruppe
        ]


        if not sichtbare_items:
            print(
                "Du trägst momentan keine "
                "Gegenstände bei dir."
            )

            warte_auf_taste()
            return

        print("Wähle einen Gegenstand:")
        print()

        nummer = 0
        for (titel, _), gruppe in zip(gruppen_definitionen, gruppen):
            if not gruppe:
                continue

            design_text(titel, design="wichtig", art="menue")
            print()
            for item_id, anzahl in gruppe:
                nummer += 1
                item_daten = ITEMS[item_id]
                menge_text = f" x{anzahl}" if anzahl > 1 else ""
                print(f"{nummer}. {item_daten['name']}{menge_text}")
                print(f"   {item_daten['typ']}")
            print()


        zurueck_nummer = len(sichtbare_items) + 1

        print(f"{zurueck_nummer}. Zurück")

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=()
        )

        if auswahl == zurueck_nummer:
            return

        item_id, anzahl = sichtbare_items[
            auswahl - 1
        ]

        item_daten = ITEMS[item_id]

        ort_titel(item_daten["name"])

        print(
            f"Typ: {item_daten['typ']}"
        )

        print(
            f"Anzahl: {anzahl}"
        )

        print()
        print(
            item_daten["beschreibung"]
        )

        inhalt = item_daten.get(
            "inhalt"
        )

        if inhalt:
            print()

            design_text(
                "Inhalt:",
                design="wissen",
                art="menue"
            )

            print()

            for zeile in inhalt:
                print(
                    zeile
                )

        if item_id == "messmappe_wegstation":
            wegstation_messmappe_anzeigen()

        if (
            item_id == "mareks_routenmappe"
            and routenkenntnis_bekannt(
                "koenigsring"
            )
        ):
            print()

            design_text(
                "Routenkenntnis: Königsring",
                design="wissen",
                art="menue"
            )

            print(
                "Bei Reisen zwischen Eichenruh und Letzthafen "
                "kannst du die vertraute Strecke zügig zurücklegen."
            )

        kueche_bonus = gute_kueche_bonus(item_daten)

        heilung = item_daten.get(
            "heilung",
            0
        )

        if heilung > 0:
            heilung += kueche_bonus

        status_eintraege = item_daten.get(
            "status_effekte",
            []
        )

        if not isinstance(
            status_eintraege,
            list
        ):
            status_eintraege = []

        if heilung > 0:
            print()
            print(
                f"Heilung: {heilung} HP"
            )

        for effekt in status_eintraege:
            if not isinstance(
                effekt,
                dict
            ):
                continue

            status_id = effekt.get(
                "id"
            )

            definition = STATUS_EFFEKTE.get(
                status_id
            )

            if not definition:
                continue

            print()

            design_text(
                (
                    f"Effekt: "
                    f"{definition['name']}"
                ),
                design=definition.get(
                    "design",
                    "wissen"
                ),
                art="menue"
            )

            print(
                definition.get(
                    "beschreibung",
                    ""
                )
            )

            dauer = effekt.get(
                "dauer",
                definition.get(
                    "standard_dauer"
                )
            )

            einheit = effekt.get(
                "einheit",
                definition.get(
                    "standard_einheit"
                )
            )

            dauer = gute_kueche_dauer(
                dauer,
                einheit,
                kueche_bonus
            )

            if (
                dauer is not None
                and einheit
            ):
                if einheit == "schritte":
                    einheit_text = (
                        "Schritt"
                        if dauer == 1
                        else "Schritte"
                    )

                elif einheit == "runden":
                    einheit_text = (
                        "Kampfrunde"
                        if dauer == 1
                        else "Kampfrunden"
                    )

                else:
                    einheit_text = einheit

                print(
                    f"Dauer: "
                    f"{dauer} "
                    f"{einheit_text}"
                )

        if (
            heilung > 0
            or status_eintraege
            or item_id in ("bandage", "gegengift")
        ):
            print()
            if item_id == "bandage":
                print("1. Bandage anlegen")
            elif item_id == "gegengift":
                print("1. Gegengift trinken")
            elif item_id == "wundsalbe":
                print("1. Wundsalbe auftragen")
            else:
                print("1. Essen")
            print("2. Zurück")

            detail_auswahl = eingabe_menu(
                1,
                2,
                sonder_tasten=()
            )

            if detail_auswahl == 1:
                item_benutzen(
                    item_id
                )

        else:
            warte_auf_taste()

def ausruestungs_boni_anzeigen(gegenstand):
    if not isinstance(gegenstand, dict):
        return

    gegenstand_id = gegenstand.get("id")
    if not isinstance(gegenstand_id, str):
        return

    daten = AUSRUESTUNGS_GEGENSTAENDE.get(gegenstand_id, {})
    boni = daten.get("pruefwert_boni", {})
    namen = {"wahrnehmung": "Wahrnehmung", "ausdauer": "Ausdauer", "geschick": "Geschick"}

    for wert_id, bonus in boni.items():
        if isinstance(bonus, int) and not isinstance(bonus, bool) and bonus != 0:
            name = namen.get(wert_id, wert_id)
            print(f"   Bonus beim Tragen: {name} {bonus:+d}")



def ausruestungs_slot_verwalten(
    slot
):
    slot_namen = {
        "ruestung": "Rüstung",
        "zubehoer": "Zubehör",
        "werkzeug": "Werkzeug"
    }

    slot_name = slot_namen[
        slot
    ]

    while True:
        ort_titel(
            f"Inventar - {slot_name}"
        )

        aktueller_gegenstand = (
            ausruestung_holen(
                slot
            )
        )

        print(
            f"Ausgerüstet: "
            f"{aktueller_gegenstand['name']}"
            if isinstance(
                aktueller_gegenstand,
                dict
            )
            else "Ausgerüstet: Keine"
        )

        if (
            slot == "ruestung"
            and isinstance(
                aktueller_gegenstand,
                dict
            )
        ):
            print(
                f"Schutz: "
                f"{aktueller_gegenstand.get('schutz', 0)}"
            )

        ausruestungs_boni_anzeigen(aktueller_gegenstand)
        print()


        verfuegbar = (
            ausruestungsinventar_fuer_slot(
                slot
            )
        )

        for nummer, (
            _inventar_index,
            gegenstand
        ) in enumerate(
            verfuegbar,
            start=1
        ):
            if slot == "ruestung":
                schutz = gegenstand.get(
                    "schutz",
                    0
                )

                if isinstance(
                    aktueller_gegenstand,
                    dict
                ):
                    aktueller_schutz = (
                        aktueller_gegenstand.get(
                            "schutz",
                            0
                        )
                    )

                    delta = vergleichs_delta(
                        schutz,
                        aktueller_schutz
                    )

                    print(
                        f"{nummer}. "
                        f"{gegenstand['name']} "
                        f"- Schutz: "
                        f"{schutz} "
                        f"({delta})"
                    )

                else:
                    print(
                        f"{nummer}. "
                        f"{gegenstand['name']} "
                        f"- Schutz: "
                        f"{schutz}"
                    )

            else:
                print(
                    f"{nummer}. "
                    f"{gegenstand['name']}"
                )

            ausruestungs_boni_anzeigen(gegenstand)
            print()

        naechste_nummer = (
            len(verfuegbar) + 1
        )

        ablegen_nummer = None

        if aktueller_gegenstand is not None:
            ablegen_nummer = (
                naechste_nummer
            )

            print(
                f"{ablegen_nummer}. "
                f"{slot_name} ablegen"
            )

            naechste_nummer += 1

        zurueck_nummer = (
            naechste_nummer
        )

        print(
            f"{zurueck_nummer}. Zurück"
        )

        auswahl = eingabe_menu(
            1,
            zurueck_nummer,
            sonder_tasten=()
        )

        if auswahl == zurueck_nummer:
            return

        if (
            ablegen_nummer is not None
            and auswahl == ablegen_nummer
        ):
            (
                erfolgreich,
                gegenstand
            ) = ausruestung_in_inventar_ablegen(
                slot
            )

            if erfolgreich:
                print()

                design_text(
                    f"{gegenstand['name']} abgelegt",
                    design="wissen",
                    art="menue"
                )

                warte_auf_taste(
                    "Weiter"
                )

            continue

        auswahl_index = (
            auswahl - 1
        )

        if auswahl_index >= len(
            verfuegbar
        ):
            continue

        inventar_index = (
            verfuegbar[
                auswahl_index
            ][0]
        )

        (
            erfolgreich,
            neuer_gegenstand,
            alter_gegenstand
        ) = ausruestungsgegenstand_ausruesten(
            inventar_index
        )

        if not erfolgreich:
            continue

        print()

        design_text(
            f"{neuer_gegenstand['name']} ausgerüstet",
            design="positiv",
            art="menue"
        )

        if alter_gegenstand is not None:
            print()

            print(
                f"{alter_gegenstand['name']} "
                f"wurde ins Inventar gelegt."
            )

        warte_auf_taste(
            "Weiter"
        )


def ausruestung_anzeigen():
    while True:
        ort_titel("Inventar - Ausrüstung")
        ausruestung_sicherstellen()

        slot_namen = {
            "waffe": "Waffe",
            "ruestung": "Rüstung",
            "zubehoer": "Zubehör",
            "werkzeug": "Werkzeug"
        }
        for slot, slot_name in slot_namen.items():
            gegenstand = ausruestung_holen(slot)
            if isinstance(gegenstand, dict):
                print(f"{slot_name}: {gegenstand.get('name', 'Unbekannt')}")
                if slot == "waffe":
                    waffenvergleich_anzeigen(gegenstand)
                elif slot == "ruestung":
                    print(f"   Schutz: {gegenstand.get('schutz', 0)}")
                ausruestungs_boni_anzeigen(gegenstand)
            else:
                print(f"{slot_name}: Keine")
            print()

        print("Nur ein Zubehörstück kann gleichzeitig getragen werden.")
        menue_trenner()
        print()
        print("1. Waffe verwalten")
        print("2. Rüstung verwalten")
        print("3. Zubehör verwalten")
        print("4. Werkzeug verwalten")
        print("5. Zurück")

        auswahl = eingabe_menu(1, 5, sonder_tasten=())
        if auswahl == 5:
            return
        if auswahl == 1:
            waffeninventar()
        else:
            slot = ("ruestung", "zubehoer", "werkzeug")[auswahl - 2]
            ausruestungs_slot_verwalten(slot)



def inventar():
    while True:
        ort_titel("Inventar")

        print(
            f"Lebenspunkte: "
            f"{spieler['lebenspunkte']}/100"
        )

        print(
            f"Heiltränke: "
            f"{spieler['heiltränke']}"
        )

        print(
            f"Fackeln: "
            f"{spieler['fackeln']}"
        )

        print(
            f"Diamanten: "
            f"{spieler['diamanten']}"
        )

        aktuelle_waffe = spieler.get(
            "waffe"
        )

        print()

        if aktuelle_waffe:
            print(
                f"Aktuelle Waffe: "
                f"{aktuelle_waffe['name']}"
            )

        else:
            print(
                "Aktuelle Waffe: Keine"
            )

        print(f"Gold: {spieler['gold']}")
        menue_trenner()
        print()

        print("1. Gegenstände")
        print("2. Heiltrank benutzen")
        print("3. Waffen")
        print("4. Ausrüstung")
        print("5. Status")
        print("6. Zurück")

        inventar_auswahl = eingabe_menu(
            1,
            6,
            sonder_tasten=()
        )

        if inventar_auswahl == 1:
            gegenstaende_inventar()

        elif inventar_auswahl == 2:
            spieler[
                "lebenspunkte"
            ], spieler[
                "heiltränke"
            ] = heiltrank_benutzen(
                spieler["lebenspunkte"],
                spieler["heiltränke"]
            )

            warte_auf_taste()

        elif inventar_auswahl == 3:
            waffeninventar()

        elif inventar_auswahl == 4:
            ausruestung_anzeigen()

        elif inventar_auswahl == 5:
            status_anzeigen()

        elif inventar_auswahl == 6:
            return

def handel_bestaetigen(artikel, anzahl, preis, verkauf=False):
    gesamt = anzahl * preis
    ort_titel("Verkauf bestätigen" if verkauf else "Kauf bestätigen")
    print(f"Gegenstand: {artikel}")
    print(f"Menge: {anzahl}")
    print(f"Preis pro Stück: {preis} Gold")
    print(f"{'Du erhältst' if verkauf else 'Du bezahlst'}: {gesamt} Gold")
    danach = spieler["gold"] + gesamt if verkauf else spieler["gold"] - gesamt
    print(f"Gold: {spieler['gold']} → {danach}")
    print()
    print("1. Ja, verkaufen" if verkauf else "1. Ja, kaufen")
    print("2. Nein, zurück")
    return eingabe_menu(1, 2, sonder_tasten=()) == 1



def heiltrank_limit():
    # Die Gürteltasche erlaubt einen Heiltrank mehr.
    if item_besitzt("guerteltasche"):
        return MAX_HEILTRÄNKE + 1

    return MAX_HEILTRÄNKE


BJORN_HILFSMITTEL = {
    "wurfnetz": {
        "zutaten": {"netzgarn": 2},
        "gold": 5,
        "einmalig": False
    },
    "guerteltasche": {
        "zutaten": {"wolfsfell": 2, "keilerhauer": 1},
        "gold": 20,
        "einmalig": True
    }
}


def bjorn_hilfsmittel_herstellen(item_id):
    rezept = BJORN_HILFSMITTEL[item_id]
    name = ITEMS[item_id]["name"]
    zutaten = rezept["zutaten"]
    kosten_gold = bjorn_arbeitskosten(rezept["gold"])

    ort_titel(f"Bjorns Schmiede - {name}")
    print(ITEMS[item_id]["beschreibung"])
    print()

    if "netzgarn" in zutaten:
        print("Netzgarn: Beute von Wrackplünderern am Wrackstrand.")
    if "wolfsfell" in zutaten:
        print("Wolfsfell: Beute von Wölfen auf der Wildspur.")
    if "keilerhauer" in zutaten:
        print("Keilerhauer: Beute von Keilern auf der Wildspur.")
    print("Materialien sind nicht bei jeder Jagd garantiert.")
    print()

    fehlende_zutaten = []

    for zutat_id, anzahl in zutaten.items():
        vorhanden = item_anzahl(zutat_id)
        print(f"Benötigt: {anzahl}x {ITEMS[zutat_id]['name']} "
              f"(Du hast: {vorhanden})")
        if vorhanden < anzahl:
            fehlende_zutaten.append((zutat_id, anzahl - vorhanden))

    print(f"Arbeitskosten: {kosten_gold} Gold")
    print(f"Gold vorhanden: {spieler['gold']}")

    if rezept["einmalig"] and item_besitzt(item_id):
        design_text(f"Du besitzt bereits: {name}.",
                    design="warnung", art="menue")
        warte_auf_taste("Zurück")
        return

    fehlendes_gold = max(0, kosten_gold - spieler["gold"])

    if fehlende_zutaten or fehlendes_gold:
        design_text("Dir fehlen Materialien oder Gold.",
                    design="warnung", art="menue")
        for zutat_id, anzahl in fehlende_zutaten:
            print(f"Fehlt: {anzahl}x {ITEMS[zutat_id]['name']}")
        if fehlendes_gold:
            print(f"Fehlt: {fehlendes_gold} Gold")
        warte_auf_taste("Zurück")
        return

    menue_trenner()
    print()
    print(f"1. {name} herstellen lassen")
    print("2. Zurück")

    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    for zutat_id, anzahl in zutaten.items():
        item_entfernen(zutat_id, anzahl)

    spieler["gold"] -= kosten_gold
    item_hinzufuegen(item_id)

    design_text(f"{name} hergestellt", design="positiv", art="menue")
    print(f"{name}: {item_anzahl(item_id)}")
    print(f"Verbleibendes Gold: {spieler['gold']}")
    warte_auf_taste("Weiter")


