def joris_im_gasthaus():
    if spieler.get(
        "prolog_uebersprungen",
        False
    ):
        return False

    prolog_status = spieler.get(
        "prolog_status"
    )

    if prolog_status not in (
        "joris_gerettet",
        "koehlerei_lieferung",
        "prolog_abgeschlossen"
    ):
        return False

    daten = npc_status(
        "joris"
    )

    daten.setdefault(
        "ort",
        "gasthaus"
    )

    return daten.get(
        "ort"
    ) == "gasthaus"


def dialog_joris():
    joris_besuch = npc_besuch_starten(
        "joris"
    )

    erste_runde = True
    themen_dieses_gespraech = set()

    while True:
        ort_titel(
            "Gasthaus"
        )

        dialog_titel(
            "Joris"
        )

        if erste_runde:
            if not npc_reaktion_gezeigt(
                "joris",
                "erstes_gespraech_nach_rettung"
            ):
                dialog_stimmung_anzeigen(
                    "erleichtert"
                )

                text_ausgeben(
                    "Joris sitzt an einem der hinteren Tische. "
                    "Als er dich sieht, richtet er sich etwas auf."
                )

                print()

                text_ausgeben(
                    "[Joris] Ich schulde dir was."
                )

                text_ausgeben(
                    "[Joris] Ohne dich würde ich vermutlich noch immer "
                    "gegen diese verdammte Tür drücken."
                )

                npc_reaktion_markieren(
                    "joris",
                    "erstes_gespraech_nach_rettung"
                )

            elif (
                dialog_thema_bekannt(
                    "joris",
                    "zeitgefuehl"
                )
                and not npc_reaktion_gezeigt(
                    "joris",
                    "zeitgefuehl_nachwirkung"
                )
            ):
                dialog_stimmung_anzeigen(
                    "nachdenklich"
                )

                text_ausgeben(
                    "Joris dreht den Becher zwischen "
                    "beiden Händen, als du zu ihm trittst."
                )

                print()

                text_ausgeben(
                    "[Joris] Ich habe über das nachgedacht, "
                    "was du wegen meines Körpers gesagt hast."
                )

                text_ausgeben(
                    "[Joris] Dass ich mich nicht so gefühlt habe, "
                    "als wäre ich wirklich so lange dort unten gewesen."
                )

                print()

                text_ausgeben(
                    "Er sieht auf den Tisch."
                )

                text_ausgeben(
                    "[Joris] Ich habe immer noch keine Erklärung dafür."
                )

                npc_reaktion_markieren(
                    "joris",
                    "zeitgefuehl_nachwirkung"
                )

            else:
                begruessung = npc_begruessung_waehlen(
                    "joris",
                    [
                        "[Joris] Na? Wieder da?",
                        "[Joris] Noch eine Frage?",
                        "[Joris] Schon wieder eine Frage?",
                        (
                            "[Joris] Wenn du wieder wegen des Kellers fragst: "
                            "Ich habe leider immer noch keine bessere Erklärung."
                        ),
                        (
                            "[Joris] Mara meint, ich soll mich ausruhen. "
                            "Reden zählt hoffentlich nicht als Arbeit."
                        )
                    ]
                )

                text_ausgeben(
                    begruessung
                )

        else:
            text_ausgeben(
                "[Joris] Noch etwas?"
            )

        print()

        optionen = []

        if "keller" not in themen_dieses_gespraech:
            optionen.append(
                (
                    "keller",
                    dialog_option(
                        "joris",
                        "keller",
                        "Wie war es dort unten?"
                    )
                )
            )

        zeitgefuehl_bekannt = dialog_thema_bekannt(
            "joris",
            "zeitgefuehl"
        )

        if (
            "zeitgefuehl"
            not in themen_dieses_gespraech
            and (
                zeitgefuehl_bekannt
                or spieler_pruefung(
                    "ausdauer",
                    2
                )
            )
        ):
            optionen.append(
                (
                    "zeitgefuehl",
                    dialog_option(
                        "joris",
                        "zeitgefuehl",
                        "[Ausdauer] Dein Körper wirkt nicht, "
                        "als wärst du die ganze Nacht dort unten gewesen."
                    )
                )
            )

        if "bjorn" not in themen_dieses_gespraech:
            optionen.append(
                (
                    "bjorn",
                    dialog_option(
                        "joris",
                        "bjorn",
                        "Was sagt Bjorn zu der Sache?"
                    )
                )
            )

        optionen.append(
            (
                "ende",
                "Gespräch beenden"
            )
        )

        for nummer, (aktion, text) in enumerate(
            optionen,
            start=1
        ):
            print(
                f"{nummer}. {text}"
            )

        auswahl = eingabe_menu(
            1,
            len(optionen),
            sonder_tasten=()
        )

        aktion = optionen[
            auswahl - 1
        ][0]

        erste_runde = False

        if aktion != "ende":
            themen_dieses_gespraech.add(
                aktion
            )

        print()

        if aktion == "keller":
            schon_besprochen = dialog_thema_bekannt(
                "joris",
                "keller"
            )

            dialog_thema_markieren(
                "joris",
                "keller"
            )

            if not schon_besprochen:
                text_ausgeben(
                    "[Joris] Am Anfang war es nur dunkel."
                )

                text_ausgeben(
                    "[Joris] Dann wurde es irgendwann so still, "
                    "dass ich jeden Atemzug gezählt habe."
                )

                print()

                text_ausgeben(
                    "[Joris] Irgendwann war ich überzeugt, "
                    "dass draußen längst Nacht sein müsste."
                )

                text_ausgeben(
                    "[Joris] Dabei war kaum ein halber Vormittag vorbei."
                )

            else:
                text_ausgeben(
                    "[Joris] Ich kann dir nur sagen, "
                    "wie es sich angefühlt hat."
                )

                text_ausgeben(
                    "[Joris] Viel länger, als es gewesen sein kann."
                )

            warte_auf_taste(
                "Weiter"
            )

        elif aktion == "zeitgefuehl":
            schon_besprochen = dialog_thema_bekannt(
                "joris",
                "zeitgefuehl"
            )

            dialog_thema_markieren(
                "joris",
                "zeitgefuehl"
            )

            text_ausgeben(
                f'[{spieler["name"]}] '
                "Wenn du wirklich die ganze Nacht dort unten gewesen wärst, "
                "müsstest du viel erschöpfter sein."
            )

            print()

            if not schon_besprochen:
                text_ausgeben(
                    "Joris schaut an sich hinunter und bewegt langsam "
                    "die Finger seiner rechten Hand."
                )

                print()

                text_ausgeben(
                    "[Joris] Genau das verstehe ich nicht."
                )

                text_ausgeben(
                    "[Joris] Ich war hungrig. Durstig auch."
                )

                text_ausgeben(
                    "[Joris] Aber nicht so, wie nach einem ganzen Tag Arbeit."
                )

                print()

                text_ausgeben(
                    "[Joris] Mein Kopf sagt mir, ich war ewig dort unten."
                )

                text_ausgeben(
                    "[Joris] Mein Körper offenbar nicht."
                )

                print()

                design_text(
                    "Beobachtung: Joris' empfundenes Zeitgefühl passt "
                    "nicht zu seinem körperlichen Zustand.",
                    design="wissen",
                    art="menue"
                )

                akt1_lernerfahrung(
                    "joris_zeitgefuehl"
                )

            else:
                text_ausgeben(
                    "Joris nickt langsam."
                )

                print()

                text_ausgeben(
                    "[Joris] Mein Körper und mein Kopf sind sich "
                    "darüber immer noch nicht einig."
                )

            warte_auf_taste(
                "Weiter"
            )

        elif aktion == "bjorn":
            dialog_thema_markieren(
                "joris",
                "bjorn"
            )

            text_ausgeben(
                "[Joris] Dass ich mich ausruhen soll."
            )

            print()

            text_ausgeben(
                "[Joris] Was bei Bjorn vermutlich bedeutet, "
                "dass ich morgen doppelt so viel arbeiten darf."
            )

            warte_auf_taste(
                "Weiter"
            )

        elif aktion == "ende":
            abschied = npc_variante_waehlen(
                "joris",
                "letzter_abschied",
                [
                    "[Joris] Bis später.",
                    "[Joris] Und danke nochmal.",
                    (
                        "[Joris] Wenn Bjorn mich noch einmal in einen Keller "
                        "schickt, sage ich dir vorher Bescheid."
                    ),
                    (
                        "[Joris] Ich bleibe heute lieber hier oben. "
                        "Nur zur Sicherheit."
                    )
                ]
            )

            text_ausgeben(
                abschied
            )

            warte_auf_taste(
                "Weiter"
            )

            return

def mara_glutkrieger_portion():
    ort_titel("Mara – Kampfportion vorbereiten")
    if not glutkrieger_voraussetzungen(spieler):
        print("Dieser Lehrweg ist momentan nicht verfügbar.")
        warte_auf_taste("Zurück")
        return
    bereit = glutkrieger_portion_holen(spieler)
    if bereit is not None:
        print(f"Bereits vorbereitet: eine Kampfportion aus {GLUTKRIEGER_GERICHTE[bereit]}.")
        warte_auf_taste("Zurück")
        return
    gerichte = [gericht for gericht in GLUTKRIEGER_GERICHTE if item_anzahl(gericht) > 0]
    if not gerichte:
        print("Du benötigst eines der fünf gekochten Gerichte im Inventar.")
        warte_auf_taste("Zurück")
        return
    text_ausgeben("[Mara] Eine Portion für unterwegs. Iss sie, wenn du ihre Kraft im Kampf brauchst.")
    print("Ein Gericht wird in eine Kampfportion umgewandelt; dabei erhältst du noch keine Heilung oder Nahrungseffekte.")
    print("Die unbenutzte Portion bleibt gespeichert. Höchstens eine Portion kann vorbereitet sein.")
    print()
    for nummer, gericht in enumerate(gerichte, 1):
        print(f"{nummer}. 1x {GLUTKRIEGER_GERICHTE[gericht]} verwenden")
    zurueck = len(gerichte) + 1
    print(f"{zurueck}. Zurück")
    auswahl = eingabe_menu(1, zurueck, sonder_tasten=())
    if auswahl == zurueck:
        return
    gericht = gerichte[auswahl - 1]
    print(f"Umwandeln: 1x {GLUTKRIEGER_GERICHTE[gericht]}. Die ursprünglichen Nahrungseffekte werden durch die Kampfportion ersetzt.")
    print()
    print("1. Ja, Kampfportion vorbereiten")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) == 1:
        if glutkrieger_portion_vorbereiten(spieler, gericht, bestaetigt=True):
            print("Kampfportion vorbereitet.")
        else:
            print("Vorbereitung nicht möglich. Prüfe Gericht und Ausbildungsstand.")
    warte_auf_taste("Zurück")


def mara_glutkrieger():
    ort_titel("Mara – Glutkrieger")
    if not glutkrieger_voraussetzungen(spieler):
        print("Dieser Lehrweg ist für deinen aktuellen Ausbildungsstand nicht verfügbar.")
        warte_auf_taste("Zurück")
        return
    if hybrid_probe_offen(spieler, "glutkrieger"):
        print("Beende zuerst deine andere anstehende Hybridprüfung.")
        warte_auf_taste("Zurück")
        return
    text_ausgeben("[Mara] Teil dir deine Vorräte ein. Das gilt am Feuer genauso wie im Kampf.")
    print("Kampfportion [G]: 20 Leben heilen und für die drei Folgerunden +3 Waffenschaden; eine normale Kampfrunde.")
    print("Kraftschub [B]: Angriff 1 mit +60 % Waffenschaden während der Stärkung. Beendet danach den übrigen Schadensbonus, auch bei Verfehlen.")
    print("Nachwärme: in den drei Folgerunden jeweils 3 Leben regenerieren, auch nach Kraftschub.")
    print("Eine Portion pro Kampf. Die Kriegerklasse und Deckung halten bleiben erhalten.")
    if glutkrieger_portion_holen(spieler) is None:
        print("Keine Kampfportion vorbereitet.")
    else:
        print("Eine Kampfportion ist vorbereitet.")
    print(f"Aktuelle Lebenspunkte: {spieler['lebenspunkte']}/100")
    gelernt = glutkrieger_freigeschaltet(spieler)
    if not gelernt and spieler["lebenspunkte"] <= 35:
        print("Du bist schwer verletzt. Versorge dich vor der Prüfung.")
    anstehend = spieler.get("hybrid", {}).get("glutkrieger_probe", False)
    aktiv = hybrid_aktiv_holen(spieler) == "glutkrieger"
    if not gelernt:
        print("Prüfung im nächsten Kampf: Portion essen, mit Kraftschub treffen und gewinnen.")
        print("Prüfungsfähigkeiten ersetzen vorübergehend deinen bisherigen Hybrid. Nach jedem Versuch endet die Probe.")
        print("Heilung und Flucht sind erlaubt. Portionen und Lebenspunkte werden regulär verbraucht.")
    else:
        print("Prüfung abgeschlossen. Ein Hybridwechsel ist hier möglich; nur ein Hybrid ist aktiv.")
    print()
    print("1. Kampfportion vorbereiten")
    if gelernt:
        print("2. Als reiner Krieger weiterspielen" if aktiv else "2. Zum Glutkrieger fusionieren")
    else:
        print("2. Anstehende Prüfung ansehen" if anstehend else "2. Prüfung vorbereiten")
    print("3. Zurück")
    auswahl = eingabe_menu(1, 3, sonder_tasten=())
    if auswahl == 3:
        return
    if auswahl == 1:
        mara_glutkrieger_portion()
        return
    if gelernt:
        ziel = None if aktiv else "glutkrieger"
        print("Die Grundklasse und alle Freischaltungen bleiben erhalten. Der Wechsel kostet nichts.")
        print()
        print("1. Ja, Hybridwahl bestätigen")
        print("2. Zurück")
        if eingabe_menu(1, 2, sonder_tasten=()) == 1:
            if hybrid_beim_lehrer_waehlen(spieler, ziel, "mara", bestaetigt=True):
                print("Hybrid aktiv: Glutkrieger." if ziel else "Du spielst wieder als reiner Krieger.")
    elif anstehend:
        print("Prüfung bereit: Setze im nächsten Kampf G und anschließend einen treffenden Kraftschub B ein und gewinne.")
    elif glutkrieger_probe_starten(spieler, bestaetigt=True):
        print("Glutkrieger-Prüfung bereit für den nächsten Kampf.")
    else:
        print("Bereite zuerst eine Kampfportion vor.")
    warte_auf_taste("Zurück")


def mara_vorratskueche():
    ort_titel("Mara – Vorratsküche")
    fortschritt = koch_praxis_fortschritt(spieler)
    if (spieler.get("prolog_status") != "prolog_abgeschlossen"
            or fortschritt is None or fortschritt < 2):
        print("Schließe Maras Ausbildung ab und bereite danach zwei unterschiedliche Gerichte selbst zu.")
        warte_auf_taste("Zurück")
        return
    if koch_vorratskueche_gelernt(spieler):
        print("Vorratsküche gelernt: jede vierte erfolgreiche Zubereitung ergibt eine Zusatzportion.")
        stand = koch_portionenstand(spieler)
        if stand is None:
            print("Dein vorhandener Portionenstand konnte nicht gelesen werden; der Bonus bleibt aus.")
        else:
            print(f"Noch {4 - stand} erfolgreiche Zubereitungen bis zur Zusatzportion.")
        if glutkrieger_voraussetzungen(spieler):
            print()
            print("1. Maras weiterführenden Krieger-Koch-Lehrweg ansehen")
            print("2. Zurück")
            if eingabe_menu(1, 2, sonder_tasten=()) == 1:
                mara_glutkrieger()
        else:
            warte_auf_taste("Zurück")
        return
    text_ausgeben("[Mara] Du hast mit verschiedenen Zutaten gearbeitet. Jetzt zeige ich dir, wie du beim Vorbereiten weniger verschwendest und eine Portion mehr herausholst.")
    print("Vorratsküche: jede vierte erfolgreiche Zubereitung ergibt eine zusätzliche Portion.")
    print("Gilt für die fünf vorhandenen Rezepte, auch bei wiederholtem Kochen.")
    print("Die Zutatenkosten bleiben gleich. Abbruch und Fehlschlag zählen nicht.")
    print("Der Fortschritt wird gespeichert und beginnt mit dem Lernen bei null.")
    print("Keine Lernkosten. Deine Grundklasse bleibt unverändert.")
    print()
    print("1. Vorratsküche lernen")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) != 1:
        return
    if koch_vorratskueche_lernen(spieler, bestaetigt=True):
        text_ausgeben("[Mara] Bereite alles vor, bevor du den Topf aufsetzt. Was sauber abgetrennt und gut eingeteilt ist, muss nicht weggeworfen werden.")
        print("Kochtechnik gelernt: Vorratsküche.")
    else:
        print("Dein vorhandener Kochstand konnte nicht ergänzt werden.")
    warte_auf_taste("Zurück")


def mara_koch_ausbildung():
    ort_titel("Mara – Kochausbildung")
    if spieler.get("prolog_status") != "prolog_abgeschlossen":
        print("Die Kochausbildung ist nach dem Prolog verfügbar.")
        warte_auf_taste("Zurück")
        return
    if koch_gelernt(spieler):
        print("Beruf: Koch – Grundausbildung abgeschlossen.")
        fortschritt = koch_praxis_fortschritt(spieler)
        if fortschritt is None:
            print("Dein vorhandener Kochpraxisstand konnte nicht gelesen werden.")
        elif fortschritt >= 2:
            print(f"Eigene Gerichte: {fortschritt} – erstes Praxisziel abgeschlossen.")
            text_ausgeben("[Mara] Zwei verschiedene Gerichte. Gut. Du hast andere Zutaten verwendet und die Hitze angepasst.")
            mara_vorratskueche()
            return
        else:
            print(f"Eigene Gerichte: {fortschritt}/2 verschiedene")
            text_ausgeben("[Mara] Bereite nach der Ausbildung zwei unterschiedliche Gerichte selbst zu. Nutze die Rezepte, die du schon kennst. Zu Hause oder am Lagerfeuer geht beides.")
        warte_auf_taste("Zurück")
        return
    text_ausgeben("Mara führt dich an den Küchentisch. Neben einem Brett liegen Gemüse und ein sauberer Löffel.")
    text_ausgeben("[Mara] Du kannst hier die Grundlagen lernen. Erst sauber vorbereiten, dann die Hitze im Blick behalten.")
    print("Für jede Grundklasse, auch ohne gewählte Klasse.")
    print("Keine Attributvoraussetzung. Keine Kosten.")
    print("Mara stellt das Übungsmaterial. Du verbrauchst keine eigenen Zutaten.")
    print("Deine bekannten Rezepte und das bisherige Kochen bleiben erhalten.")
    print()
    print("1. Die Kochausbildung beginnen")
    print("2. Zurück")
    if eingabe_menu(1, 2, sonder_tasten=()) != 1:
        return
    text_ausgeben("Mara deutet auf eine Schale mit rohem Fleisch und die gewaschenen Kräuter daneben.")
    text_ausgeben("[Mara] Wie bereitest du die Zutaten vor?")
    print()
    print("1. Alles mit derselben ungewaschenen Klinge auf einem Brett schneiden")
    print("2. Rohes Fleisch getrennt halten und Brett und Klinge vor den Kräutern reinigen")
    print("3. Ausbildung abbrechen")
    antwort = eingabe_menu(1, 3, sonder_tasten=())
    if antwort != 2:
        if antwort == 1:
            text_ausgeben("[Mara] Sauberkeit zuerst. Die Kräuter sollen nichts vom rohen Fleisch abbekommen.")
            warte_auf_taste("Zurück")
        return
    text_ausgeben("Mara stellt einen Topf über die Glut. Die Suppe beginnt stark zu kochen und setzt am Boden an.")
    text_ausgeben("[Mara] Was machst du jetzt?")
    print()
    print("1. Hitze verringern und vorsichtig umrühren")
    print("2. Mehr Holz nachlegen und den Topf unbeachtet lassen")
    print("3. Ausbildung abbrechen")
    antwort = eingabe_menu(1, 3, sonder_tasten=())
    if antwort != 1:
        if antwort == 2:
            text_ausgeben("[Mara] Mehr Feuer rettet keinen angebrannten Topf. Nimm Hitze weg und behalte das Essen im Blick.")
            warte_auf_taste("Zurück")
        return
    if koch_grundausbildung_abschliessen(spieler):
        print("Koch-Grundausbildung abgeschlossen.")
        text_ausgeben("[Mara] So. Sauber arbeiten und die Hitze beherrschen. Darauf kannst du aufbauen.")
        print("Deine Grundklasse und andere Berufe bleiben erhalten.")
        print("Rezepte lernst du weiterhin aus Büchern und durch Aufgaben.")
        print("Erste Kochpraxis: zwei unterschiedliche bekannte Rezepte selbst zubereiten.")
    else:
        print("Der vorhandene Berufsstand konnte nicht ergänzt werden.")
    warte_auf_taste("Zurück")


