def gasthaus():
    ort_titel(
        "Gasthaus"
    )

    gasthaus_erstbesuch = (
        spieler.get(
            "prolog_status"
        ) == "dorf_freigeschaltet"
        and not spieler.get(
            "prolog_besuchte_orte",
            {}
        ).get(
            "gasthaus",
            False
        )
    )

    prolog_ort_besucht(
        "gasthaus"
    )

    ort_nachricht_anzeigen()

    if gasthaus_erstbesuch:
        print()

        text_ausgeben(
            "Die Gaststube ist um diese Stunde bereits belebt, "
            "ohne wirklich laut zu sein.",
            art="atmosphaere"
        )

        text_ausgeben(
            "An den schweren Holztischen stehen Becher und Teller, "
            "während aus der Küche der Geruch von warmem Brot herüberzieht.",
            art="atmosphaere"
        )

        text_ausgeben(
            "Hinter dem Tresen arbeitet Mara und behält die Gäste im Blick.",
            art="atmosphaere"
        )

    joris_da = joris_im_gasthaus()

    optionen = [
        (
            "mara",
            "Mit Mara reden"
        )
    ]

    if joris_da:
        optionen.append(
            (
                "joris",
                "Mit Joris reden"
            )
        )

    optionen.append(
        (
            "gaststube",
            "Dich in der Gaststube umsehen"
        )
    )

    if not prolog_laeuft():
        optionen.append(
            (
                "proviant",
                "Bei Mara Proviant kaufen"
            )
        )

    if spieler.get("prolog_status") == "prolog_abgeschlossen":
        optionen.append(("kochausbildung", "Bei Mara den Beruf Koch lernen"))

    if (
        not prolog_laeuft()
        and item_anzahl("holzkohle") >= 1
        and not rezept_ist_gelernt("raeucherfleisch")
    ):
        optionen.append(("raeuchern", "Mara die Holzkohle zeigen"))

    if not prolog_laeuft():
        optionen.append(
            (
                "zimmer",
                "Ein Zimmer nehmen (10 Gold)"
            )
        )
    optionen.append(
        (
            "verlassen",
            "Gasthaus verlassen"
        )
    )

    menue_trenner()
    print()

    for nummer, (_, text) in enumerate(
        optionen,
        start=1
    ):
        print(
            f"{nummer}. {text}"
        )

    print()
    print("[S] Status")
    print("[I] Inventar")
    print("[J] Questlog/Erfolge")
    print("[T] Talente")
    print("[Q] Speichern / Menü")

    gasthaus_auswahl = eingabe_menu(
        1,
        len(optionen),
        sonder_tasten=("s", "i", "j", "t", "q")
    )

    if gasthaus_auswahl == "s":
        status()
        return
    if gasthaus_auswahl == "i":
        inventar()
        return
    if gasthaus_auswahl == "j":
        questlog()
        return
    if gasthaus_auswahl == "t":
        talentmenue()
        return
    if gasthaus_auswahl == "q":
        spielmenue()
        return

    aktion = optionen[
        gasthaus_auswahl - 1
    ][0]

    if not prolog_laeuft():
        mara_daten = npc_status(
            "mara"
        )

        if aktion == "mara":
            mara_daten["direkte_besuche"] = (
                mara_daten.get(
                    "direkte_besuche",
                    0
                ) + 1
            )

        else:
            mara_daten[
                "direkte_besuche"
            ] = 0

    if aktion == "mara":
        dialog_mara()

    elif aktion == "joris":
        dialog_joris()

    elif aktion == "gaststube":
        ort_titel(
            "Gasthaus"
        )

        text_ausgeben(
            "Einige Dorfbewohner sitzen an schweren Holztischen "
            "und unterhalten sich."
        )

        text_ausgeben(
            "Aus der Küche dringt der Geruch von frisch gebackenem Brot."
        )

        warte_auf_taste()

    elif aktion == "kochausbildung":
        mara_koch_ausbildung()

    elif aktion == "raeuchern":
        mara_raeucherfleisch_zeigen()

    elif aktion == "proviant":
        mara_proviant_kaufen()
    elif aktion == "zimmer":
        gasthaus_zimmer()

    elif aktion == "verlassen":
        spieler[
            "ort"
        ] = "Eichenruh"

        ort_nachricht_setzen(
            "Du verlässt das Gasthaus.",
            "Vor dir liegen wieder die Straßen von Eichenruh."
        )

def gasthaus_zimmer():
    preis = 10

    ort_titel("Gasthaus")

    if not schlaf_moeglich():
        text_ausgeben(
            "[Mara] Jetzt schon? Komm wieder, wenn es dunkel wird."
        )
        warte_auf_taste()
        return

    if spieler["gold"] < preis:
        text_ausgeben(
            f"[Mara] Ein Zimmer kostet {preis} Gold. Das hast du gerade nicht."
        )
        warte_auf_taste()
        return

    print(f"Ein Zimmer kostet {preis} Gold. Du hast {spieler['gold']} Gold.")
    print()
    print("1. Zimmer nehmen")
    print("2. Zurück")

    auswahl = eingabe_menu(
        1,
        2,
        sonder_tasten=()
    )

    if auswahl == 2:
        return

    if not frist_schlafen_erlaubt():
        return

    spieler["gold"] -= preis

    schlafen_bis_morgen(
        "Du zahlst Mara zehn Gold und steigst die schmale Treppe zu deinem Zimmer hinauf."
    )
    print()
    text_ausgeben(
        "[Mara] Frühstück steht in der Gaststube, wenn du magst."
    )
    warte_auf_taste()


def bjorn_rezeptgruppe(titel, rezepte):
    while True:
        ort_titel("Bjorns Herstellung – " + titel)
        print("Bjorn stellt den gewählten Gegenstand für dich her.")
        print(f"Gold: {spieler['gold']} | Keilerhauer: {item_anzahl('keilerhauer')} | Wolfsfell: {item_anzahl('wolfsfell')} | Holz: {item_anzahl('holz')}")
        print("Materialkunde ist in den angezeigten Goldkosten bereits berücksichtigt.")
        print()
        for nummer, (name, basis, material, werte, quelle, rolle, herstellen) in enumerate(rezepte, 1):
            print(f"{nummer}. {name}")
            print(f"   Benötigt: {material} + {bjorn_arbeitskosten(basis)} Gold")
            print("   " + werte)
            print("   Quelle: " + quelle)
            print("   Rolle: " + rolle)
            print()
        zurueck = len(rezepte) + 1
        print(f"{zurueck}. Zurück")
        auswahl = eingabe_menu(1, zurueck, sonder_tasten=())
        if auswahl == zurueck:
            return
        rezepte[auswahl - 1][-1]()


