def schmiede():
    ort_titel("Bjorns Schmiede")

    schmiede_erstbesuch = (
        spieler.get(
            "prolog_status"
        ) == "dorf_freigeschaltet"
        and not spieler.get(
            "prolog_besuchte_orte",
            {}
        ).get(
            "schmiede",
            False
        )
    )

    prolog_ort_besucht(
        "schmiede"
    )

    ort_nachricht_anzeigen()

    if schmiede_erstbesuch:
        print()

        text_ausgeben(
            "Die Wärme der Esse liegt sofort auf deiner Haut.",
            art="atmosphaere"
        )

        text_ausgeben(
            "Kohle und heißes Metall geben der Luft einen "
            "trockenen, scharfen Geruch.",
            art="atmosphaere"
        )

        text_ausgeben(
            "Der Zwerg steht breit vor dem Amboss. Seine Hammerschläge fallen "
            "gleichmäßig, in einem Rhythmus, den du seit Jahren kennst.",
            art="atmosphaere"
        )

    if prolog_laeuft():
        menue_trenner()
        print()

        keller_verfuegbar = (
            spieler.get("prolog_status") == "joris_keller"
        )

        print("1. Mit Bjorn reden")
        print("2. Dich in der Schmiede umsehen")

        if keller_verfuegbar:
            print("3. Zum alten Lagerkeller gehen")
            print("4. Schmiede verlassen")
            prolog_maximum = 4

        else:
            print("3. Schmiede verlassen")
            prolog_maximum = 3

        print()
        print("[S] Status")
        print("[I] Inventar")
        print("[J] Questlog/Erfolge")
        print("[T] Talente")
        print("[Q] Speichern / Menü")

        prolog_schmiede_auswahl = eingabe_menu(
            1,
            prolog_maximum,
            sonder_tasten=("s", "i", "j", "t", "q")
        )

        if prolog_schmiede_auswahl == "s":
            status()
            return
        if prolog_schmiede_auswahl == "i":
            inventar()
            return
        if prolog_schmiede_auswahl == "j":
            questlog()
            return
        if prolog_schmiede_auswahl == "t":
            talentmenue()
            return
        if prolog_schmiede_auswahl == "q":
            spielmenue()
            return

        if prolog_schmiede_auswahl == 1:
            dialog_bjorn()

        elif prolog_schmiede_auswahl == 2:
            ort_titel("Bjorns Schmiede")

            text_ausgeben(
                "Nahe der Esse flimmert die Luft vor Hitze."
            )

            text_ausgeben(
                "An der Wand hängen Zangen und Hämmer in festen Reihen. "
                "Die Griffe sind dunkel vom jahrelangen Gebrauch."
            )

            text_ausgeben(
                "Auf Bjorns Werkbank liegen ein unfertiges Hufeisen, "
                "ein gesprungener Axtkopf und mehrere kleine Metallstücke."
            )

            text_ausgeben(
                "Nichts daran wirkt besonders wertvoll. "
                "Alles wartet nur darauf, wieder brauchbar zu werden."
            )

            warte_auf_taste()

        elif (
            prolog_schmiede_auswahl == 3
            and keller_verfuegbar
        ):
            spieler["ort"] = "lagerkeller"

            ort_nachricht_setzen(
                "Du gehst hinter die Schmiede.",
                "Zwischen Holzstapeln und alten Kisten findest du "
                "die schwere Falltür.",
                "Als du sie anhebst, steigt dir kühle, abgestandene "
                "Luft entgegen.",
                "Eine schmale Treppe führt in den Lagerkeller hinab."
            )

        elif (
            prolog_schmiede_auswahl == 4
            and keller_verfuegbar
        ) or (
            prolog_schmiede_auswahl == 3
            and not keller_verfuegbar
        ):
            spieler["ort"] = "Eichenruh"

            ort_nachricht_setzen(
                "Du verlässt Bjorns Schmiede."
            )

        return
    menue_trenner()
    print()

    print("1. Reden")
    print("2. Herstellen")
    print("3. Handeln")
    print("4. Waffenübung bei Bjorn")
    print("5. An Bjorns Werkbank selbst arbeiten")
    print("6. Kriegerausbildung / Grundklasse")
    print("7. Schmiedeausbildung / Beruf")
    print("8. Schmiede verlassen")

    klammern = brunnfeld_klammern_offen()

    if klammern:
        print("9. Klammern für den Steg schmieden lassen [!]")

    print()
    print("[S] Status")
    print("[I] Inventar")
    print("[J] Questlog/Erfolge")
    print("[T] Talente")
    print("[Q] Speichern / Menü")

    schmied_auswahl = eingabe_menu(
        1,
        9 if klammern else 8,
        sonder_tasten=("s", "i", "j", "t", "q")
    )

    if schmied_auswahl == "s":
        status()
        return
    if schmied_auswahl == "i":
        inventar()
        return
    if schmied_auswahl == "j":
        questlog()
        return
    if schmied_auswahl == "t":
        talentmenue()
        return
    if schmied_auswahl == "q":
        spielmenue()
        return
    if schmied_auswahl == 9:
        brunnfeld_klammern_bei_bjorn()
        return
    bjorn_daten = npc_status(
        "bjorn"
    )

    if schmied_auswahl == 1:
        bjorn_daten["direkte_besuche"] = (
            bjorn_daten.get(
                "direkte_besuche",
                0
            ) + 1
        )

    else:
        bjorn_daten[
            "direkte_besuche"
        ] = 0

    if schmied_auswahl == 1:
        dialog_bjorn()
    elif schmied_auswahl == 2:
        bjorn_herstellungsmenue()

    elif schmied_auswahl == 3:
        while True:
            ort_titel("Bjorns Schmiede - Handeln")
            lederweste_preis = AUSRUESTUNGS_GEGENSTAENDE[
                "gepolsterte_lederweste"
            ]["kaufpreis"]

            print(f"Gold: {spieler['gold']}")
            print(f"Heiltränke: {spieler['heiltränke']}")
            print()
            design_text("KAUFEN", design="wichtig", art="menue")
            print()
            print("1. Heiltrank - 25 Gold")
            print(f"2. Gepolsterte Lederweste - {lederweste_preis} Gold")
            print(f"   Schutz: {AUSRUESTUNGS_GEGENSTAENDE['gepolsterte_lederweste']['schutz']}")
            print("   Nach dem Kauf im Inventar unter Ausrüstung anlegen.")
            print()
            seil_extra = 1 if tiefen_zukauf_offen() else 0
            if seil_extra:
                print(f"3. Seil - {TIEFEN_ZUKAUF_PREISE['seil']} Gold")
                print()
            print("Den Einfachen Speer kannst du unter Herstellen anfertigen lassen.")
            print()
            design_text("VERKAUFEN", design="wichtig", art="menue")
            print()
            print(f"{3 + seil_extra}. Waffe verkaufen")
            print(f"{4 + seil_extra}. Zurück")

            kaufen_auswahl = eingabe_menu(1, 4 + seil_extra, sonder_tasten=())

            if seil_extra and kaufen_auswahl == 3:
                haendler_kaufen(
                    "Bjorns Schmiede - Seil",
                    "[Bjorn] Gutes Hanfseil. Das hält mehr aus als dich.",
                    tiefen_zukauf_sortiment(("seil",))
                )
                continue
            if seil_extra and kaufen_auswahl > 3:
                kaufen_auswahl -= 1

            if kaufen_auswahl == 1:
                freie_plaetze = max(
                    0, heiltrank_limit() - spieler["heiltränke"]
                )
                max_heiltrank = min(spieler["gold"] // 25, freie_plaetze)

                if freie_plaetze == 0:
                    design_text(
                        f"Du kannst höchstens {heiltrank_limit()} Heiltränke tragen.",
                        design="warnung", art="menue"
                    )
                    warte_auf_taste("Weiter")
                elif max_heiltrank == 0:
                    design_text("Du hast nicht genug Gold.",
                                design="warnung", art="menue")
                    warte_auf_taste("Weiter")
                else:
                    ort_titel("Bjorns Schmiede - Heiltränke kaufen")
                    print("Preis: 25 Gold pro Heiltrank")
                    print(f"Gold: {spieler['gold']}")
                    print(f"Heiltränke: {spieler['heiltränke']}/{heiltrank_limit()}")
                    print(f"Du kannst maximal {max_heiltrank} Heiltränke kaufen.")
                    print()
                    print("0. Zurück")
                    anzahl_heiltraenke = eingabe_zahl(0, max_heiltrank)
                    if anzahl_heiltraenke == 0:
                        continue
                    if not handel_bestaetigen("Heiltrank", anzahl_heiltraenke, 25):
                        continue
                    spieler["gold"] -= anzahl_heiltraenke * 25
                    spieler["heiltränke"] += anzahl_heiltraenke
                    design_text(f"{anzahl_heiltraenke} Heiltränke gekauft",
                                design="positiv", art="menue")
                    print()
                    print(f"Heiltränke: {spieler['heiltränke']}")
                    print(f"Gold: {spieler['gold']}")
                    warte_auf_taste("Weiter")

            elif kaufen_auswahl == 2:
                if ausruestungsgegenstand_besitzt("gepolsterte_lederweste"):
                    design_text("Du besitzt diese Rüstung bereits.",
                                design="warnung", art="menue")
                    warte_auf_taste("Weiter")
                elif spieler["gold"] < lederweste_preis:
                    design_text("Du hast nicht genug Gold.",
                                design="warnung", art="menue")
                    warte_auf_taste("Weiter")
                else:
                    schutz = AUSRUESTUNGS_GEGENSTAENDE["gepolsterte_lederweste"]["schutz"]
                    if not handel_bestaetigen(
                        f"Gepolsterte Lederweste (Schutz: {schutz})", 1, lederweste_preis
                    ):
                        continue
                    spieler["gold"] -= lederweste_preis
                    ausruestungsgegenstand_hinzufuegen("gepolsterte_lederweste")
                    design_text("Gepolsterte Lederweste gekauft",
                                design="positiv", art="menue")
                    print()
                    print(f"Gold: {spieler['gold']}")
                    warte_auf_taste("Weiter")

            elif kaufen_auswahl == 3:
                waffe_verkaufen()
            elif kaufen_auswahl == 4:
                break


    elif schmied_auswahl == 4:
        bjorn_fokus_uebung()

    elif schmied_auswahl == 6:
        bjorn_krieger_ausbildung()

    elif schmied_auswahl == 7:
        bjorn_schmied_ausbildung()
    elif schmied_auswahl == 5:
        bjorn_eigene_herstellung()

    elif schmied_auswahl == 8:
        spieler["ort"] = "Eichenruh"

        ort_nachricht_setzen(
            "Du verlässt die Schmiede.",
            "Die Geräusche von Eichenruh empfangen dich wieder."
        )

def brandschneise_jagd():
    if not spieler.get("brandschneise_eingefuehrt", False):
        ort_titel("Köhlerei - Brandschneise")
        text_ausgeben(
            "Rika führt dich hinter die Meiler. Dort liegt ein breiter "
            "Streifen verbrannter Baumstümpfe, durchzogen von warmer Asche."
        )
        print()
        text_ausgeben(
            "[Rika] Die Brandschneise. Hier hat das Feuer vor Jahren den Wald "
            "gefressen. Seitdem leben Tiere in der Asche, die Wärme mögen."
        )
        text_ausgeben(
            "[Rika] Glutsalamander. Wenn ihre Haut rot glüht, bleib weg oder halt "
            "sie mit etwas Langem auf Abstand. Und wenn einer in der Asche "
            "verschwindet: abwarten, nicht blind zuschlagen."
        )
        text_ausgeben(
            "[Rika] Außerdem schleichen hier Leute herum, die den Köhlern Kohle "
            "stehlen. Die werfen dir Asche in die Augen und rennen, sobald es "
            "eng wird."
        )
        spieler["brandschneise_eingefuehrt"] = True
        warte_auf_taste("Weiter")

    spur_untersucht = False

    while spieler.get("spiel_laeuft", True):
        ort_titel("Köhlerei - Brandschneise")

        lebenspunkte = spieler["lebenspunkte"]
        print(f"Lebenspunkte: {lebenspunkte}/100")

        if lebenspunkte <= 35:
            design_text(
                "Du bist schwer verletzt. Eine Jagd ist jetzt besonders "
                "gefährlich. Öffne das Inventar, um dich zu versorgen, "
                "oder kehre zur Köhlerei zurück.",
                design="warnung",
                art="menue"
            )

        print()

        spuren_erkannt = (
            spur_untersucht
            or spieler_pruefung(
                "wahrnehmung",
                3 - talent_bonus(spieler, "wildspur_schwelle")
            )
        )

        # WM-D2: Fährtenlesen erkennt die Spuren immer.
        faehrten_gelesen = not spuren_erkannt and faehrtensteller_aktiv(spieler)
        spuren_erkannt = spuren_erkannt or faehrten_gelesen

        if spuren_erkannt:
            print(faehrten_vorsatz(faehrten_gelesen) + "Du kannst die Spuren in der Asche unterscheiden.")
            faehrten_revierhinweis("brandschneise")
            print()
            print("1. Der schleifenden Aschespur folgen - Glutsalamander [1 Schritt]")
            print("2. Den Stiefelabdrücken folgen - Kohlenschmuggler [1 Schritt]")
        else:
            print("Die Spuren in der Asche verwischen ineinander.")
            print()
            print("1. Einer unbekannten Spur folgen [1 Schritt]")
            print("2. Spuren genauer untersuchen [1 zusätzlicher Schritt]")

        print("3. Inventar öffnen")
        print("4. Zurück zur Köhlerei")
        print()
        print("[Schritt]: Blutung, Gift und Mahlzeit-Wirkungen laufen dabei einen Schritt weiter.")

        auswahl = eingabe_menu(1, 4, sonder_tasten=())

        if auswahl == 4:
            return

        if auswahl == 3:
            inventar()
            continue

        if not spuren_erkannt and auswahl == 2:
            if not status_schritte_abschliessen():
                return

            spur_untersucht = True
            text_ausgeben(
                "Du kniest dich hin und siehst genauer hin. Breite Schleifspuren "
                "führen zu den Meilern, schwere Stiefelabdrücke zum Waldrand. "
                "Jetzt kannst du gezielt einer Spur folgen."
            )
            warte_auf_taste("Spur wählen")
            continue

        if not spieler.get("waffe"):
            design_text(
                "Rüste im Inventar eine Waffe aus, bevor du jagst.",
                design="warnung",
                art="menue"
            )
            warte_auf_taste("Zurück")
            continue

        if spuren_erkannt:
            gegner_typ = "Glutsalamander" if auswahl == 1 else "Kohlenschmuggler"
        else:
            gegner_typ = random.choice(("Glutsalamander", "Kohlenschmuggler"))

        if not status_schritte_abschliessen():
            return

        gegner_typ = revierherr_pruefen("brandschneise", gegner_typ)

        if gegner_typ is None:
            continue

        print()

        if gegner_typ == "Aschenkönig":
            text_ausgeben(
                "Der Aschenkönig schiebt sich aus der Glut auf dich zu."
            )
        elif gegner_typ == "Glutsalamander":    
            text_ausgeben(
                "Zwischen zwei verkohlten Stümpfen hebt sich die Asche. "
                "Ein Glutsalamander schiebt sich heraus und öffnet das Maul."
            )
        else:
            text_ausgeben(
                "Hinter einem Stumpf richtet sich ein Mann mit rußigem Gesicht auf. "
                "Ein Sack Kohle liegt neben ihm. Er greift nach seinem Knüppel."
            )

        print()

        kampf_ergebnis = kampf_starten(
            lebenspunkte=spieler["lebenspunkte"],
            heiltraenke=spieler["heiltränke"],
            waffe=spieler["waffe"],
            gegner_typ=gegner_typ,
            kampf_situation={
                "gebiet": "Wald",
                "umgebung": "Lichtung",
                "tageszeit": spieler.get("tageszeit", "Tag"),
                "wetter": spieler.get("wetter", "Klar")
            }
        )

        spieler["lebenspunkte"] = kampf_ergebnis["lebenspunkte"]
        spieler["heiltränke"] = kampf_ergebnis["heiltraenke"]

        if kampf_ergebnis.get("gewonnen", False):
            spieler["besiegte_gegner"] += 1
            print()
            print("-" * 34)
            design_text(
                "JAGD ERFOLGREICH",
                design="positiv",
                art="ereignis"
            )
            spieler["gold"] = kampf_beute_vergeben(
                gegner_typ,
                spieler["gold"],
                jaeger_jagd=gegner_typ == "Glutsalamander"
            )
            print()
            print(f"Lebenspunkte: {spieler['lebenspunkte']}")
            print("-" * 34)
            warte_auf_taste("Zur Brandschneise")

        elif kampf_ergebnis.get("gegner_geflohen", False):
            beute = KAMPF_BEUTE.get(gegner_typ, {})
            gold = random.randint(
                beute.get("gold_min", 0),
                beute.get("gold_max", 0)
            ) // 2
            spieler["gold"] += gold
            print()
            if gold > 0:
                text_ausgeben(
                    f"Auf dem Boden liegen {gold} Gold, die er bei der Flucht verloren hat.",
                    art="menue"
                )
            warte_auf_taste("Zur Brandschneise")

        elif kampf_ergebnis.get("besiegt", False):
            print()
            design_text(
                "Game Over",
                design="gefahr",
                art="menue"
            )
            spieler["spiel_laeuft"] = False
            return

        elif kampf_ergebnis.get("geflohen", False):
            print()
            text_ausgeben(
                "Du brichst die Jagd ab und ziehst dich zur Köhlerei zurück.",
                art="menue"
            )
            warte_auf_taste("Zur Köhlerei")
            return


def koehler_holzkohle_zurueckgeben():
    ort_titel("Köhlerei am Waldrand")

    anzahl = item_anzahl("holzkohle")

    text_ausgeben(
        "Ein rußverschmierter Köhler sieht die Kohle in deiner Tasche "
        "und hebt die Augenbrauen."
    )
    text_ausgeben(
        "[Köhler] Das ist brauchbare Kohle."
    )
    text_ausgeben(
        "[Köhler] Wenn du mehr davon findest, bring sie her. "
        "Ich zahl dir vier Gold pro Stück."
    )
    text_ausgeben(
        "[Köhler] Bei den Schmugglern in der Schneise ist sicher auch "
        "einiges davon gelandet."
    )
    print()
    print(f"Holzkohle im Gepäck: {anzahl}")
    print()
    print("1. Ein Stück zurückgeben (4 Gold)")
    print(f"2. Alles zurückgeben ({anzahl * 4} Gold)")
    print("3. Behalten")

    auswahl = eingabe_menu(1, 3, sonder_tasten=())

    if auswahl == 3:
        text_ausgeben(
            "[Köhler] Wie du meinst. Mara räuchert damit übrigens gern Fleisch."
        )
        warte_auf_taste("Zurück")
        return

    menge = 1 if auswahl == 1 else anzahl

    if not item_entfernen("holzkohle", menge):
        return

    spieler["gold"] += menge * 4

    text_ausgeben(
        f"Der Köhler wirft die Kohle zurück auf den Haufen und drückt dir "
        f"{menge * 4} Gold in die Hand."
    )
    print(f"Gold: {spieler['gold']}")
    warte_auf_taste("Zurück")


def brandschneise_offen():
    return (
        spieler.get("brandschneise_eingefuehrt") is True
        or spieler.get("wildspur_jagd_erfolgreich") is True
        or bool(jaeger_praxisstand(spieler))
    )


def koehlerei():
    ort_titel("Köhlerei am Waldrand")

    ort_nachricht_anzeigen()

    prolog_status = spieler.get("prolog_status")

    if prolog_status == "koehlerei_lieferung":
        text_ausgeben(
            "Zwischen den schwarzen Erdmeilern hängt ein grauer "
            "Rauchschleier über der Lichtung."
        )

        text_ausgeben(
            "Ein Köhler schaufelt feuchte Erde an die Flanke eines "
            "Meilers, während ein anderer mit einem langen Stock "
            "die Luftöffnungen prüft."
        )

        print()
        text_ausgeben(
            "Weiter hinten ruft jemand etwas über einen Meiler, "
            "der zu stark zieht."
        )

        text_ausgeben(
            "Aus dem Rauch kommt eine knappe Antwort."
        )

        text_ausgeben(
            "[Köhler] Dann mach das Zugloch kleiner!"
        )

        seite_wechseln(
            "Köhlerei am Waldrand"
        )

