ALTE_ZEICHEN_REIHENFOLGE = ("hammer", "register", "wegstein")

ALTE_ZEICHEN_ORTE = {
    "hammer": "am Hammer",
    "register": "am Register",
    "wegstein": "am Wegstein"
}


def bekannte_alte_zeichen():
    bekannt = []

    if spieler.get("alte_zeichen_verknuepft", False):
        bekannt.append("hammer")

    if (
        item_besitzt("versiegeltes_register")
        or besonderer_fund_bekannt("versiegeltes_register")
    ):
        bekannt.append("register")

    if (
        spieler.get("wald_wegstein_untersucht", False)
        or wald_fund_bekannt("wegstein_nachhall")
    ):
        bekannt.append("wegstein")

    return bekannt


def randnotiz_zeichen():
    zeichen = spieler.get("oros_randnotiz_zeichen", [])

    if not isinstance(zeichen, list):
        return []

    return [
        zeichen_id
        for zeichen_id in ALTE_ZEICHEN_REIHENFOLGE
        if zeichen_id in zeichen
    ]


def alte_zeichen_aufzaehlung(zeichen):
    orte = [ALTE_ZEICHEN_ORTE[zeichen_id] for zeichen_id in zeichen]

    if len(orte) <= 1:
        return "".join(orte)

    return ", ".join(orte[:-1]) + " und " + orte[-1]


