    print(f"{klassen_option}. Grundklassen vergleichen")
    print(f"{selene_option}. Mit Magistra Selene sprechen / Magierausbildung")
    print(f"{zurueck_option}. Zurück in die zentrale Halle")

    print()
    print("[S] Status")
    print("[I] Inventar")
    print("[J] Questlog/Erfolge")
    print("[T] Talente")
    print("[Q] Speichern / Menü")

    auswahl = eingabe_menu(
        1,
        zurueck_option,
        sonder_tasten=("s", "i", "j", "t", "q")
    )

    if auswahl == "s":
        status()
        return
    if auswahl == "i":
        inventar()
        return
    if auswahl == "j":
        questlog()
        return
    if auswahl == "t":
        talentmenue()
        return
    if auswahl == "q":
        spielmenue()
        return

    if auswahl == 1:
        if schutz_finch_brief_offen():
            schutz_finch_brief()

            warte_auf_taste(
                "Weiter"
            )

        elif mauer_finch_reihe_offen():
            mauer_finch_reihe()

        else:
            dialog_finch()

    elif (
        messbuch_option
        is not None
        and auswahl
        == messbuch_option
    ):
        oros_messbuch_recherche()

    elif (
        randnotiz_option is not None
        and auswahl == randnotiz_option
    ):
        oros_messbuch_randnotiz()

    elif (
        verzeichnis_option is not None
        and auswahl == verzeichnis_option
    ):
        oros_neuvermessungen_verzeichnis()

    elif auswahl == zurueck_option:
        spieler[
            "ort"
        ] = "oros_zentrale_halle"

        ort_nachricht_setzen(
            "Du verlässt die Lehrhallen und "
            "kehrst in die zentrale Halle zurück."
        )


    elif auswahl == mira_option:
        mira_gelehrten_ausbildung()
    elif auswahl == klassen_option:
        klassenmenue()
    elif auswahl == selene_option:
        selene_magier_ausbildung()

