# IV-C (Paket 5)
MAUER_ABSCHLUSS_TEXT = (
    "Hinter der Kammer der Reihe liegt IV-C. Auf einer beschädigten alten "
    "Inschrift erscheint das Wort „Netz“. Seine Bedeutung ist unklar. Die "
    "Schutzverwaltung hat den Zugang erneut gesperrt."
)


def mauer_bericht_zeile():
    entscheidungen = spieler.get("entscheidungen", {})

    if (
        isinstance(entscheidungen, dict)
        and entscheidungen.get("zustandsbericht") == "finch_valerie"
    ):
        return "Finch und Valerie werten die Abschrift zuerst aus."

    return "Haller hat den vollständigen Bericht erhalten."


def mauer_reihe_ziel():
    if item_besitzt("alte_messmarke"):
        return "Lege die Alte Messmarke in die Lücke der Reihe."

    return "Untersuche den Messgang weiter. Der Reihe fehlt ein Teil."


def mauer_finch_reihe_offen():
    return mauer_quest_status() == "untersuchung_ausstehend"


def mauer_finch_reihe():
    ort_titel(
        "Universität von Oros - Lehrhallen"
    )

    text_ausgeben(
        "Finch hat das Messbuch K-IV aufgeschlagen. Daneben liegt ein "
        "Blatt, auf dem er den Steinkreis aus dem Gedächtnis gezeichnet hat."
    )
    text_ausgeben("[Finch] Die Lücke lässt mich nicht los.")
    text_ausgeben("[Finch] Sie ist klein. Kleiner als jeder Stein im Kreis.")
    print()

    if item_besitzt("alte_messmarke"):
        text_ausgeben("[Finch] Zeig mir die Messmarke aus der Nische.")
        text_ausgeben(
            "Er legt sie neben seine Zeichnung. Dann misst er die Kerben mit "
            "den Fingern, wie unten im Messgang."
        )
        text_ausgeben("[Finch] Gleicher Abstand. Wie die Zeichen im Kreis.")
        text_ausgeben(
            "[Finch] Ich glaube nicht, dass jemand sie verloren hat. Ich "
            "glaube, sie wurde dort abgelegt. Für später."
        )
    else:
        text_ausgeben(
            "[Finch] Ich glaube, der Reihe fehlt ein Teil. Etwas Kleines, "
            "das genau dorthin gehört."
        )
        text_ausgeben(
            "[Finch] Im Messgang gibt es Stellen, die wir noch nicht "
            "untersucht haben."
        )

    spieler["quest_unter_der_mauer"] = "reihe_schliessen"

    quest_meldung(
        "update",
        "Unter der Mauer",
        mauer_reihe_ziel()
    )

    warte_auf_taste("Weiter")


def mauer_finch_satz():
    status = mauer_quest_status()

    if status == "untersuchung_ausstehend":
        return "[Finch] Die Lücke in der Reihe lässt mich nicht los."

    if status == "reihe_schliessen":
        return (
            "[Finch] Die Lücke in der Reihe. Ich sehe sie, sobald ich die "
            "Augen schließe."
        )

    if status == "iv_c_berichten":
        return "[Finch] Haller wartet am Zugang auf unseren Bericht."

    if status == "abgeschlossen":
        if mauer_bericht_zeile().startswith("Finch und Valerie"):
            return (
                "[Finch] Ich habe Valerie um eine Auswertung gebeten. Ich "
                "hoffe, sie erkennt etwas, das mir entgangen ist."
            )

        return (
            "[Finch] Haller hat jetzt ein Wort, das er nicht versteht. Ich "
            "auch nicht. Das macht mir Sorgen."
        )

    return None


