def stollen_kampf_situation():
    return {
        "gebiet": "Tiefen",
        "umgebung": "Tiefe mit Licht" if tiefen_licht_an() else "Dunkle Tiefe",
        "tageszeit": "Tag",
        "wetter": "Klar"
    }


def stollen_kampf(gegner_typ, rueckzug):
    # Wiederholbarer Kampf in den Nebenstollen: kein EXP, Beute mit Chance.
    if not isinstance(spieler.get("waffe"), dict):
        print()
        design_text(
            "Rüste im Inventar eine Waffe aus, bevor du kämpfst.",
            design="warnung",
            art="menue"
        )
        warte_auf_taste("Zurück")
        return

    kampf_ergebnis = kampf_starten(
        lebenspunkte=spieler["lebenspunkte"],
        heiltraenke=spieler["heiltränke"],
        waffe=spieler["waffe"],
        gegner_typ=gegner_typ,
        kampf_situation=stollen_kampf_situation()
    )

    spieler["lebenspunkte"] = kampf_ergebnis["lebenspunkte"]
    spieler["heiltränke"] = kampf_ergebnis["heiltraenke"]

    if kampf_ergebnis.get("gewonnen", False):
        spieler["besiegte_gegner"] += 1

        if gegner_typ == "Schachtspinner":
            vorkommen_id = "stollen_spinner"
        else:
            vorkommen_id = STOLLEN_TIERE[gegner_typ][0]

        status = ressourcen_vorkommen_status(vorkommen_id)
        status["vorrat"] = max(0, status["vorrat"] - 1)

        print()
        print("-" * 34)

        if gegner_typ == "Schachtspinner":
            spieler["gold"] = kampf_beute_vergeben(
                gegner_typ,
                spieler["gold"],
                jaeger_jagd=True
            )
        else:
            material = STOLLEN_TIERE[gegner_typ][2]
            chance = (
                STOLLEN_MATERIALCHANCE
                + talent_bonus(spieler, "jagd_materialchance")
            )

            print()
            design_text("BEUTE", design="wissen", art="menue")
            print()

            if random.randint(1, 100) <= chance and item_hinzufuegen(material):
                jagdbuch_eintragen(gegner_typ, beute=True)
                print(f"- 1x {ITEMS[material]['name']}")
            else:
                print("Du findest nichts Brauchbares.")

        print()
        print(f"Lebenspunkte: {spieler['lebenspunkte']}")
        print("-" * 34)
        warte_auf_taste("Weiter")

    elif kampf_ergebnis.get("besiegt", False):
        warte_auf_taste("Weiter")
        tiefen_rettung()

    else:
        print()
        text_ausgeben("Du ziehst dich zurück.", art="menue")
        warte_auf_taste("Weiter")
        rueckzug()


def stollen_spur(gegner_typ):
    vorkommen_id, _, _, fund_text = STOLLEN_TIERE[gegner_typ]
    status = ressourcen_vorkommen_status(vorkommen_id)
    zustand = tiefen_zustand()

    ort_titel("TIEFEN - Stollengang")

    if status["vorrat"] <= 0:
        anzahl = zustand.get("stollen_leer", 0)
        zustand["stollen_leer"] = anzahl + 1
        text_ausgeben(STOLLEN_LEER_TEXTE[anzahl % len(STOLLEN_LEER_TEXTE)])
        warte_auf_taste("Zurück")
        return

    jagdbuch_eintragen(gegner_typ)
    text_ausgeben(fund_text)

    menue_trenner()
    print()
    print("1. Angreifen")
    print("2. Sich zurückziehen")

    if eingabe_menu(1, 2, sonder_tasten=()) == 1:
        stollen_kampf(gegner_typ, lambda: None)


def tiefen_stollengang():
    zustand = tiefen_zustand()
    zustand.pop("spinner_umgangen", None)

    if tiefen_kopf("tiefen_stollengang"):
        if tiefen_licht_an():
            text_ausgeben(
                "Der Stollen ist eng und niedrig. Stützbalken, schwarz vor "
                "Alter, halten die Decke. Im Staub kreuzen sich Spuren: feine "
                "Krallenabdrücke, breite Schleifspuren, die Rinne eines "
                "schweren Körpers."
            )
        else:
            text_ausgeben(
                "Der Stollen ist eng. Deine Schulter streift einen Balken, dann "
                "noch einen. Unter deinen Füßen liegt weicher Staub."
            )
    else:
        text_ausgeben(
            "Der Stollengang liegt still. Die Spuren im Staub sind neu oder "
            "alt, schwer zu sagen.",
            art="menue"
        )

    optionen = [
        (STOLLEN_TIERE[gegner_typ][1], lambda g=gegner_typ: stollen_spur(g))
        for gegner_typ in STOLLEN_TIERE
    ]
    optionen.append((
        "Weiter in die Geröllkammer",
        lambda: tiefen_gehen("tiefen_geroellkammer")
    ))
    optionen.append(tiefen_laterne_option())
    optionen.append((
        "Zurück in den Messgang",
        lambda: tiefen_gehen(
            "tiefen_messgang",
            "Du kriechst durch die Lücke zurück in den Messgang."
        )
    ))

    tiefen_menue(optionen)


def stollen_suchen(fund_id):
    text, material, fund_text = STOLLEN_FUNDSTELLEN[fund_id]
    status = ressourcen_vorkommen_status(fund_id)
    zustand = tiefen_zustand()
    suche = zustand.setdefault("fund_suche", {})

    ort_titel("TIEFEN - Geröllkammer")

    # Wahrnehmung 3/2/1/0: Fund beim 1./2./3./4. Absuchen; Geübtes Auge zählt +1.
    wert = spieler_pruefwert("wahrnehmung") + talent_bonus(spieler, "untersuchung_bonus")
    noetig = max(1, 4 - max(0, min(3, wert)))
    versuche = suche.get(fund_id, 0) + 1

    if versuche < noetig:
        suche[fund_id] = versuche
        text_ausgeben(STOLLEN_SUCHTEXTE[(versuche - 1) % len(STOLLEN_SUCHTEXTE)])
        warte_auf_taste("Zurück")
        return

    suche[fund_id] = 0
    status["vorrat"] = max(0, status["vorrat"] - 1)
    item_hinzufuegen(material)
    text_ausgeben(fund_text)
    print()
    print(f"Erhalten: {ITEMS[material]['name']}")
    warte_auf_taste("Zurück")


def stollen_spinner_schleichen():
    print()

    schwelle = 3

    if talent_bonus(spieler, "reise_leise") > 0:
        schwelle -= 1

    if spieler_pruefung("geschick", schwelle):
        tiefen_zustand()["spinner_umgangen"] = True
        text_ausgeben(
            "Du bewegst dich nur, wenn das Tropfen lauter ist als deine "
            "Schritte. Die Fäden über dir bleiben ruhig."
        )
        warte_auf_taste("Weiter")
        return

    text_ausgeben(
        "Dein Ärmel streift einen Faden. Über dir lösen sich lange Beine aus "
        "dem Grau."
    )
    warte_auf_taste("Weiter")
    stollen_kampf(
        "Schachtspinner",
        lambda: tiefen_gehen("tiefen_stollengang")
    )


def tiefen_geroellkammer():
    zustand = tiefen_zustand()

    if tiefen_kopf("tiefen_geroellkammer"):
        if tiefen_licht_an():
            text_ausgeben(
                "Der Stollen öffnet sich zu einer Kammer, halb gefüllt mit "
                "Geröll. Von der Decke hängen graue Fäden, dicht wie altes "
                "Tuch. Irgendwo tropft Wasser in ein Rinnsal."
            )
        else:
            text_ausgeben(
                "Die Luft wird kühler. Unter deinen Händen Geröll, "
                "scharfkantig. Etwas Klebriges legt sich über deine Finger. "
                "Fäden."
            )
    else:
        text_ausgeben(
            "Die Geröllkammer. Das Tropfen, die Fäden, das Geröll.",
            art="menue"
        )

    spinner_da = (
        ressourcen_vorkommen_status("stollen_spinner")["vorrat"] > 0
        and zustand.get("spinner_umgangen") is not True
    )

    if spinner_da:
        jagdbuch_eintragen("Schachtspinner")
        print()

        if tiefen_licht_an():
            text_ausgeben(
                "Die Fäden an der Decke zittern. Zwischen ihnen schiebt sich "
                "ein Körper hervor, groß wie ein Hund, mit langen, gebogenen "
                "Beinen."
            )
            text_ausgeben("Er bleibt hängen und wartet.")
        else:
            text_ausgeben(
                "Über dir knistert es, als würde jemand trockenes Papier "
                "zusammenfalten. Dann nichts mehr. Du weißt, dass es noch da "
                "ist."
            )

        tiefen_menue([
            (
                "Angreifen",
                lambda: stollen_kampf(
                    "Schachtspinner",
                    lambda: tiefen_gehen("tiefen_stollengang")
                )
            ),
            (
                "Unter den Fäden hindurchschleichen [Geschick]",
                stollen_spinner_schleichen
            ),
            tiefen_laterne_option(),
            (
                "Zurück in den Stollengang",
                lambda: tiefen_gehen("tiefen_stollengang")
            )
        ])
        return

    optionen = []

    for fund_id, (text, _, _) in STOLLEN_FUNDSTELLEN.items():
        if ressourcen_vorkommen_status(fund_id)["vorrat"] > 0:
            optionen.append((text, lambda f=fund_id: stollen_suchen(f)))

    if not optionen:
        print()
        text_ausgeben("Hier findest du im Moment nichts mehr. Vielleicht später.")

    optionen.append(tiefen_laterne_option())
    optionen.append((
        "Zurück in den Stollengang",
        lambda: tiefen_gehen("tiefen_stollengang")
    ))

    tiefen_menue(optionen)


def tiefen_kammer():
    zustand = tiefen_zustand()
    titel = "TIEFEN - Kammer der Reihe"

    if tiefen_kopf("tiefen_kammer"):
        if tiefen_licht_an():
            text_ausgeben(
                "Der Messgang endet in einem Raum, der größer ist, als du "
                "nach dem schmalen Messgang erwartet hast."
            )
            text_ausgeben(
                "Die Decke trägt sich selbst, ohne Pfeiler."
            )
            seite_wechseln(titel)

            print(tiefen_licht_zeile())
        else:
            text_ausgeben(
                "Der Messgang endet. Deine Schritte klingen plötzlich "
                "anders. Das Echo kommt später zurück, als du erwartet "
                "hast."
            )
            text_ausgeben("Der Raum muss groß sein.")

        zustand["kammer_entdeckt"] = True

    elif zustand.get("reihe_geschlossen") is True:
        text_ausgeben(
            tiefen_kammer_durchgang_text(),
            art="menue"
        )

    elif zustand.get("reihe_gesehen") is True:
        text_ausgeben(
            "Die Kammer liegt still. Der Kreis aus Steinen, der leere "
            "Platz, die Platte ohne Fuge.",
            art="menue"
        )

    else:
        text_ausgeben(
            "Die Kammer liegt still. Deine Schritte hallen spät zurück.",
            art="menue"
        )

    if tiefen_licht_an() and zustand.get("reihe_gesehen") is not True:
        print()
        text_ausgeben(
            "In den Boden ist ein Kreis aus flachen Steinen eingelassen, "
            "jeder mit einem Zeichen. Ein Platz in der Reihe ist leer."
        )
        text_ausgeben("[Finch] Die Reihe.")
        text_ausgeben(
            "[Finch] Ich habe sie aus Messbüchern abgeschrieben. Ich hätte "
            "nicht gedacht, dass ich einmal auf ihr stehe."
        )
        text_ausgeben("Ahrens hört auf zu schreiben.")
        print()
        text_ausgeben(
            "Auf der gegenüberliegenden Seite führt ein Durchgang weiter. "
            "Er ist mit einer glatten Steinplatte verschlossen, ohne Griff, "
            "ohne Schloss und ohne sichtbare Fuge."
        )
        text_ausgeben("[Finch] Dahinter liegt IV-C. Wenn die Reihe stimmt.")
        text_ausgeben("[Finch] Und ich fürchte, sie stimmt.")

        zustand["reihe_gesehen"] = True
        zustand["platte_gefunden"] = True

    elif tiefen_sicht() and zustand.get("platte_gefunden") is not True:
        print()
        text_ausgeben(
            "Im Boden ahnst du einen Kreis aus flachen Steinen. Ihre "
            "Zeichen erkennst du ohne Licht nicht."
        )
        text_ausgeben(
            "Gegenüber zeichnet sich ein Durchgang ab. Eine glatte Platte "
            "verschließt ihn."
        )

        zustand["platte_gefunden"] = True

    nach_meldung = (
        zustand.get("platte_gefunden") is True
        and mauer_quest_status() in ("abstieg", "kammer_finden")
    )

    if nach_meldung:
        tiefen_quest_ziel(
            "haller_berichten",
            "Kehre zum TIEFEN-Zugang zurück und berichte Haller von der "
            "Kammer der Reihe."
        )

    optionen = []

    if zustand.get("platte_gefunden") is not True:
        optionen.append((
            "Die gegenüberliegende Wand abtasten",
            tiefen_platte_tasten
        ))

    optionen.extend(tiefen_reihe_optionen())
    optionen.append(tiefen_laterne_option())
    optionen.append((
        "Zurück in den Messgang",
        lambda: tiefen_gehen("tiefen_messgang")
    ))

    tiefen_menue(optionen, nach_meldung)


