def wegstation_status():
    status = spieler.setdefault(
        "wegstation_status",
        {}
    )

    status.setdefault(
        "entdeckt",
        False
    )

    status.setdefault(
        "aktueller_raum",
        "vorhof"
    )

    status.setdefault(
        "besuchte_raeume",
        []
    )

    status.setdefault(
        "abkuerzungen",
        []
    )

    status.setdefault(
        "funde",
        {}
    )

    status.setdefault(
        "varianten",
        {}
    )

    return status

def wegstation_varianten_initialisieren():
    status = wegstation_status()

    varianten = status[
        "varianten"
    ]

    if "wachraum" not in varianten:
        varianten[
            "wachraum"
        ] = random.choice(
            [
                "muenzen",
                "heiltrank",
                "frische_spuren",
                "leer"
            ]
        )

    if "schreibstube" not in varianten:
        varianten[
            "schreibstube"
        ] = random.choice(
            [
                "eingestuerztes_regal",
                "vogelnest",
                "persoenliche_notiz",
                "ratten"
            ]
        )

    if "keller" not in varianten:
        varianten[
            "keller"
        ] = random.choice(
            [
                "bandit",
                "wolf",
                "morsche_treppe",
                "frische_spuren"
            ]
        )

    return varianten

def wegstation_raum_betreten(raum_id):
    if raum_id not in WEGSTATION_RAEUME:
        return False

    status = wegstation_status()

    status[
        "aktueller_raum"
    ] = raum_id

    besuchte_raeume = status[
        "besuchte_raeume"
    ]

    erstmals = (
        raum_id not in besuchte_raeume
    )

    if erstmals:
        besuchte_raeume.append(
            raum_id
        )

    return erstmals

def wegstation_wachraum_untersuchen():
    status = wegstation_status()
    funde = status[
        "funde"
    ]

    if funde.get(
        "wachraum_untersucht",
        False
    ):
        return

    funde[
        "wachraum_untersucht"
    ] = True

    variante = status[
        "varianten"
    ].get(
        "wachraum"
    )

    ort_titel(
        "Alte Wegstation - Wachraum"
    )

    text_ausgeben(
        "Du untersuchst die alten Bänke, "
        "das zerbrochene Waffengestell und "
        "die Reste eines schmalen Schranks."
    )

    print()

    if variante == "muenzen":
        gold = random.randint(
            4,
            9
        )

        text_ausgeben(
            "Unter einer losen Bodenplatte "
            "entdeckst du einige alte Münzen."
        )

        spieler[
            "gold"
        ] += gold

        print()

        design_text(
            f"{gold} Gold gefunden",
            design="positiv",
            art="menue"
        )

    elif variante == "heiltrank":
        text_ausgeben(
            "Ganz hinten im Schrank steht noch "
            "eine kleine, versiegelte Glasflasche."
        )

        print()

        text_ausgeben(
            "Der Inhalt sieht erstaunlich "
            "brauchbar aus."
        )

        if (
            spieler["heiltränke"]
            < heiltrank_limit()
        ):
            spieler[
                "heiltränke"
            ] += 1

            print()

            design_text(
                "1 Heiltrank gefunden",
                design="positiv",
                art="menue"
            )

        else:
            funde[
                "wachraum_untersucht"
            ] = False

            print()

            design_text(
                (
                    "Du kannst keinen weiteren "
                    "Heiltrank tragen."
                ),
                design="warnung",
                art="menue"
            )

            print()

            text_ausgeben(
                (
                    "Du lässt die versiegelte Flasche "
                    "im Schrank zurück."
                )
            )

    elif variante == "frische_spuren":
        text_ausgeben(
            "Zwischen dem alten Staub fallen dir "
            "mehrere deutlich frischere Spuren auf."
        )

        print()

        text_ausgeben(
            "Getrockneter Schlamm haftet an einer Bank."
        )

        text_ausgeben(
            "Daneben liegt ein Stück grobes Seil, "
            "das noch nicht lange hier liegen kann."
        )

        print()

        design_text(
            "Jemand war vor nicht allzu langer Zeit hier.",
            design="warnung",
            art="menue"
        )

        funde[
            "frische_spuren_wachraum"
        ] = True

    elif variante == "leer":
        text_ausgeben(
            "Du durchsuchst den Raum gründlich."
        )

        print()

        text_ausgeben(
            "Außer einem verrosteten Gürtelhaken "
            "und zerbrochenem Holz findest du nichts, "
            "das noch von Nutzen wäre."
        )

    warte_auf_taste(
        "Weiter"
    )

