# Kapitel 5, Quest „Die letzte Abtrennung“ (Paket B1)
# --------------------------------------------------

def abtrennung_status():
    return spieler.get(
        "quest_letzte_abtrennung",
        "nicht_begonnen"
    )


def abtrennung_daten():
    daten = spieler.get("abtrennung")

    if not isinstance(daten, dict):
        daten = {}
        spieler["abtrennung"] = daten

    return daten


def abtrennung_haller_offen():
    return (
        wegstation_quest_status() == "abgeschlossen"
        and abtrennung_status() == "nicht_begonnen"
    )


def abtrennung_ziel():
    return {
        "auftrag": "Komm zum alten TIEFEN-Zugang.",
        "messgang": "Folge Finch in den Messgang."
    }.get(abtrennung_status(), "")


def abtrennung_ziel_setzen(status, neu=False):
    spieler["quest_letzte_abtrennung"] = status

    quest_meldung(
        "neu" if neu else "update",
        "Die letzte Abtrennung",
        abtrennung_ziel()
    )


def abtrennung_beginn():
    titel = "Universität von Oros - Amtsstube der Schutzverwaltung"
    ort_titel(titel)

    text_ausgeben(
        "Zwei junge Archivkräfte stellen einen flachen Aktenkasten auf "
        "Hallers Tisch."
    )
    text_ausgeben("[Nele] Die angeforderten Abschriften aus dem Archiv, Herr Verwalter.")
    text_ausgeben("[Tarek] Ignaz möchte den Empfang bestätigt haben.")
    text_ausgeben("[Haller] Ahrens, übernehmen Sie.")
    text_ausgeben("Ahrens unterschreibt. Die beiden gehen.")

    seite_wechseln(titel)
    dialog_titel("Konrad Haller")

    text_ausgeben("Haller schlägt die Schutzordnung auf und dreht sie zu dir.")
    text_ausgeben(
        "[Haller] Drei Schritte. Prüfen: die Stellung der Bezugspunkte "
        "vergleichen. Abtrennen: die gefährdete Verbindung vorläufig "
        "isolieren. Wiederanbinden: die Verbindung nach erneuter Prüfung "
        "zurückführen."
    )
    text_ausgeben("[Haller] Es ist beschrieben, Handgriff für Handgriff.")
    text_ausgeben("[Finch] Beschrieben. Nicht bezeugt.")
    text_ausgeben(
        "[Haller] Wir haben die Messungen, Professor. Wir haben Ahrens' "
        "Nachmessung. Mehr Gewissheit bekommen wir nicht, solange wir warten."
    )

    fragen = [
        ("wiederanbindung", "Was, wenn die Wiederanbindung nicht gelingt?"),
        ("schutzbereich", "Wer ist außerhalb des Schutzbereichs?"),
        ("warum_jetzt", "Warum jetzt?")
    ]
    gestellt = []

    while True:
        offen = [frage for frage in fragen if frage[0] not in gestellt]
        menue_trenner()
        print()

        for nummer, (_, text) in enumerate(offen, start=1):
            print(f"{nummer}. „{text}“")

        print(f"{len(offen) + 1}. „Ich komme mit.“")

        auswahl = eingabe_menu(1, len(offen) + 1, sonder_tasten=())

        if auswahl == len(offen) + 1:
            break

        frage_id = offen[auswahl - 1][0]
        gestellt.append(frage_id)
        print()

        if frage_id == "wiederanbindung":
            text_ausgeben(
                "[Haller] Dann ist die Verbindung abgetrennt, wie sie es "
                "ohnehin bald wäre. Nur geordnet."
            )
            text_ausgeben("[Finch] Wenn sie es ohnehin bald wäre.")

        elif frage_id == "schutzbereich":
            text_ausgeben("Haller zögert einen Moment.")
            text_ausgeben("[Haller] Die Außenstationen. Und was an ihnen hängt.")
            text_ausgeben(
                "[Haller] Ich weiß nicht genau, was das ist. Deshalb trenne "
                "ich vorläufig und nicht endgültig."
            )

        else:
            text_ausgeben(
                "[Haller] Weil Eichenruh bei der ersten Messung noch gestimmt "
                "hat und bei der zweiten nicht mehr."
            )
            text_ausgeben(
                "[Haller] Ich will nicht wissen, was bei der dritten "
                "herauskommt."
            )

    print()
    text_ausgeben("[Haller] Ich möchte Sie dabeihaben. Sie kennen die Messungen.")
    text_ausgeben(
        "[Haller] Morgen früh, am TIEFEN-Zugang. Die Schutzverwaltung stellt "
        "Licht."
    )

    abtrennung_daten()["fragen"] = gestellt
    abtrennung_ziel_setzen("auftrag", neu=True)


def abtrennung_zugang():
    titel = "Universität von Oros - Alter TIEFEN-Zugang"
    ort_titel(titel)

    text_ausgeben(
        "Vor der Öffnung stehen Laternen in einer Reihe. Arbeiter tragen "
        "Werkzeugkisten die Treppe hinab."
    )
    text_ausgeben(
        "Finch hält das Messbuch K-IV unter dem Arm. Er nickt dir zu, sagt "
        "aber nichts."
    )

    menue_trenner()
    print()
    print("1. Mit Haller und Finch hinabsteigen [!]")
    print("2. Zurück in die zentrale Halle")

    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    print()
    design_text(
        "Mit diesem Abstieg beginnt ein längerer Abschnitt der "
        "Hauptgeschichte. Reisen und freie Erkundung sind vorübergehend "
        "nicht möglich.",
        design="warnung",
        art="menue"
    )
    print()
    print("Jetzt hinabsteigen?")
    print("1. Ja, hinabsteigen")
    print("2. Noch nicht")

    if eingabe_menu(1, 2, sonder_tasten=()) == 2:
        return

    abtrennung_daten()["abstieg_bestaetigt"] = True
    abtrennung_iv_c()


def abtrennung_iv_c():
    daten = abtrennung_daten()
    titel = "Universität von Oros - Alter TIEFEN-Zugang"
    ort_titel(titel)

    text_ausgeben(
        "[Ahrens] Die Stelle war in der Schutzordnung verzeichnet. Zwei "
        "Arbeiter haben die alte Wandverkleidung entfernt. Der Rahmen liegt "
        "dahinter."
    )
    text_ausgeben("[Haller] Gehen wir.")

    titel = "TIEFEN - Abstieg"
    seite_wechseln(titel)

    text_ausgeben(
        "Die Treppe ist hell wie nie zuvor. An jeder Wendung steht eine "
        "Laterne."
    )
    text_ausgeben(
        "Im Messgang arbeitet niemand. Die Vertiefungen in der Wand liegen "
        "still im Licht."
    )
    text_ausgeben(
        "Vor dem Durchgang zu IV-C nimmt Ahrens das Siegel der "
        "Schutzverwaltung ab. Hinter der Platte ist die Luft wärmer, wie beim "
        "ersten Mal."
    )

    titel = "TIEFEN - IV-C"
    seite_wechseln(titel)

    text_ausgeben(
        "In der Wand gegenüber dem Durchgang klafft eine rechteckige "
        "Öffnung, wo bisher Verkleidung war."
    )
    text_ausgeben(
        "Dahinter liegt ein Rahmen aus Stein, so breit wie zwei "
        "ausgestreckte Arme. Darin sitzen flache Steinelemente in Schienen, "
        "jedes mit einer Kerbe."
    )
    text_ausgeben(
        "Die feinen Linien des Pfeilers laufen über den Boden bis an den "
        "Rahmen und verschwinden unter den Elementen."
    )

    menue_trenner()
    print()
    print("1. Den Sicherungsrahmen ansehen [!]")
    eingabe_menu(1, 1, sonder_tasten=())

    ort_titel(titel)
    text_ausgeben(
        "Du siehst dir die Elemente genauer an. Ihre Kerben gleichen denen "
        "auf den Pfosten der Wegstation."
    )
    text_ausgeben(
        "Bei einigen ist der Staub in den Schienen frisch verwischt. Bei den "
        "anderen hat ihn seit langer Zeit niemand berührt."
    )
    text_ausgeben("[Finch] Sie haben ihn geprüft, aber nicht bewegt?")
    text_ausgeben(
        "[Ahrens] Die Verkleidung wurde entfernt. Die Stellung der Elemente "
        "ist dokumentiert. Bewegt wurde noch nichts."
    )

    daten["rahmen"] = True

    menue_trenner()
    print()
    print("1. Haller sagen, dass du bereit bist")
    eingabe_menu(1, 1, sonder_tasten=())

    ort_titel(titel)
    text_ausgeben(
        "Ahrens liest die Schritte vor, einen nach dem anderen. Zwei Arbeiter "
        "schieben das erste Element in seiner Schiene nach außen. Stein reibt "
        "auf Stein."
    )
    text_ausgeben(
        "Finch richtet die Peilscheibe an den Markierungen des Pfeilers aus "
        "und vergleicht die Werte mit dem Messbuch K-IV."
    )
    text_ausgeben(
        "[Finch] Die Peilung, die wir Letzthafen zugeordnet haben, bleibt "
        "jetzt konstant."
    )
    text_ausgeben("[Haller] Die Werte beruhigen sich.")
    text_ausgeben(
        "[Finch] An diesem Punkt. Wir wissen nicht, was an den anderen "
        "geschieht."
    )
    text_ausgeben(
        "[Haller] Deshalb führen wir die Maßnahme kontrolliert zu Ende."
    )
    text_ausgeben("[Haller] Ahrens. Weiter.")

    seite_wechseln(titel)

    text_ausgeben("Das zweite Element. Das dritte.")
    text_ausgeben("Finch blättert zurück, dann wieder vor.")
    text_ausgeben(
        "[Finch] Oros. Bei beiden Messungen an der Wegstation hat dieser Wert "
        "noch gestimmt."
    )
    text_ausgeben("[Haller] Oros ist nicht abgetrennt.")
    text_ausgeben("[Finch] Nein. Und trotzdem stimmt er jetzt nicht mehr.")
    text_ausgeben("Haller sieht auf den Rahmen, dann auf Finch.")
    text_ausgeben("[Haller] Zurückstellen. Alle drei. Wie beschrieben.")
    text_ausgeben(
        "Die Arbeiter schieben die Elemente zurück in ihre alten Schienen. "
        "Ahrens liest die Schritte rückwärts vor."
    )

    menue_trenner()
    print()
    print("1. Mit Finch die Werte nach der Rücknahme vergleichen [!]")
    eingabe_menu(1, 1, sonder_tasten=())

    ort_titel(titel)
    text_ausgeben(
        "Finch liest ab. Einmal, zweimal. Du hältst das Messbuch, damit er "
        "beide Hände frei hat."
    )
    text_ausgeben(
        "Die Elemente stehen wieder dort, wo sie standen. Die Peilwerte am "
        "Pfeiler kehren nicht zu ihren alten Werten zurück."
    )
    text_ausgeben("[Finch] Es geht nicht zurück.")

    daten["ruecknahme"] = True

    print()
    text_ausgeben(
        "Haller nimmt Ahrens die Schutzordnung aus der Hand und liest die "
        "Seite selbst. Dann noch einmal."
    )
    text_ausgeben("[Haller] Hier steht, wie man zurückstellt.")
    text_ausgeben("Er blättert um. Die nächste Seite ist leer.")
    text_ausgeben("[Haller] Nicht, was man tut, wenn es nicht zurückgeht.")

    seite_wechseln(titel)

    text_ausgeben(
        "Aus dem Messgang kommt ein Laut, ein tiefes Knirschen, aus einer "
        "Richtung, in der niemand steht."
    )
    text_ausgeben(
        "Einer der Arbeiter dreht sich um und lässt seine Laterne fallen. Sie "
        "erlischt nicht."
    )
    text_ausgeben("[Finch] Der Messgang. Jetzt.")

    zustand = tiefen_zustand()
    besucht = zustand.setdefault("besucht", [])

    if "tiefen_messgang" not in besucht:
        besucht.append("tiefen_messgang")

    spieler["ort"] = "tiefen_messgang"

    abtrennung_ziel_setzen("messgang")
    warte_auf_taste("Weiter")


