def offene_tore_levin_da():
    # Gleiche Bedingung wie bei Ida in der Krankenstube.
    return (
        spieler.get("oros_listen_voraufgabe") is True
        and oros_listen_entscheidung_holen() != "levin_beschuldigt"
    )


def offene_tore_auswahl(punkte, schluss):
    # Jeder Punkt einmal, in beliebiger Reihenfolge; der letzte beendet.
    gewaehlt = []

    while True:
        offen = [punkt for punkt in punkte if punkt[0] not in gewaehlt]
        menue_trenner()
        print()

        for nummer, (_, text, _) in enumerate(offen, start=1):
            print(f"{nummer}. {text}")

        print(f"{len(offen) + 1}. {schluss}")

        auswahl = eingabe_menu(1, len(offen) + 1, sonder_tasten=())
        print()

        if auswahl == len(offen) + 1:
            return

        punkt_id, _, zeilen = offen[auswahl - 1]
        gewaehlt.append(punkt_id)

        for zeile in zeilen:
            text_ausgeben(zeile)


