    if buergen:
        entscheidungen["kiran_tor"] = "buergschaft"
        text_ausgeben(
            "Du gehst mit Kiran zum Tisch. Haller sieht von seinem Register auf."
        )
        text_ausgeben("[Haller] Sie wollen für ihn bürgen.")
        text_ausgeben(
            "[Haller] Dann steht Ihr Name neben seinem. Wenn sich herausstellt, "
            "dass er nicht ist, wer er sagt, stehen Sie dafür ein."
        )
        text_ausgeben(
            "Er wartet einen Augenblick. Dann schreibt er. Zwei Namen, eine "
            "Zeile."
        )
        text_ausgeben("[Haller] Vorläufig. Bürgschaft vermerkt.")
        text_ausgeben(
            "Kiran steht auf. Beim Aufstehen zählt er leise seine Schritte."
        )
    else:
        entscheidungen["kiran_tor"] = "liste"
        text_ausgeben("[Kiran] Das verstehe ich.")
        text_ausgeben("Er faltet das Blatt zusammen und steckt es weg.")
        text_ausgeben("[Kiran] Ich bleibe hier. Von hier sehe ich den Weg.")
        text_ausgeben(
            "Als du gehst, hörst du, wie er leise seine Schritte zählt."
        )

    print()
    text_ausgeben("Am Tor winkt Ahrens dich zu sich.")

    offene_tore_ziel_setzen("vermessung_auftrag")


