def zurueckgelassene_weg_suchen():
    daten = kapitel6_daten()
    ort_titel("Faden der Erinnerung - Alter Wegweiser")
    text_ausgeben(
        "Neben dem alten Wegweiser fällt der Hang steil ab. Drei Einschnitte "
        "führen hinunter: eine Rinne mit Wagenspuren, eine Geröllrinne und ein "
        "schmaler Hohlweg."
    )
    text_ausgeben(
        "[Arvid] Ich bin irgendwo hier heraufgekommen. Es war dunkel. Ich habe "
        "nur auf die Pfähle oben geachtet."
    )

    fehlgriff = False

    if daten.get("kehre_zugang") == "levin":
        print()
        text_ausgeben(
            "Levin geht an den drei alten Richtungsmarkierungen am Wegweiser "
            "entlang und bleibt vor der mittleren stehen."
        )
        text_ausgeben("[Levin] Vierzig Teilstriche. Die Geröllrinne.")
        warte_auf_taste("Weiter")
    else:
        print()
        text_ausgeben(
            "Am Wegweiser stehen drei alte Richtungsmarkierungen. In jede ist "
            "eine Zahl geschlagen, jede zeigt auf einen der Einschnitte. In den "
            "Unterlagen steht: vierzig."
        )
        print()
        print(f"{'Einschnitt':<26}{'Markierung':>11}")
        for name, wert in ZURUECKGELASSENE_MARKIERUNGEN:
            print(f"{name:<26}{wert:>11}")

        if untersuchung_pruefung("wahrnehmung", 2):
            print()
            text_ausgeben(
                "Die Wagenspuren in der ersten Rinne sind frisch. Nach zwanzig "
                "Schritten hören sie auf, als hätte jemand umgedreht."
            )

        if untersuchung_pruefung("wissen", 2):
            print()
            text_ausgeben(
                "Die alten Fuhrleute markierten Zufahrten mit Bordsteinen in "
                "Achsbreite. In der Geröllrinne liegen zwei davon unter dem "
                "Schutt."
            )

        while True:
            print()
            print("1. Der Rinne mit den Wagenspuren folgen (34)")
            print("2. Der Geröllrinne folgen (40)")
            print("3. Dem Hohlweg folgen (47)")
            print("4. Zurück auf den Faden")

            auswahl = eingabe_menu(1, 4, sonder_tasten=())

            if auswahl == 4:
                return False

            if auswahl == 2:
                break

            print()
            if auswahl == 1:
                text_ausgeben(
                    "Die Spuren enden an einer Abbruchkante. Darunter, weit "
                    "unten, liegt ein zerbrochenes Rad. Jemand hat hier "
                    "umkehren müssen. Ihr steigt wieder hinauf."
                )
            else:
                text_ausgeben(
                    "Der Hohlweg wird enger und endet an einer Felswand. Ihr "
                    "steigt wieder hinauf."
                )
            fehlgriff = True

    ort_titel("Die alte Versorgungskehre - Geröllrinne")
    text_ausgeben(
        "Unter dem Geröll liegt festgetretener Boden. Zwischen den Steinen "
        "erkennst du alte Bordsteine, so breit wie eine Wagenachse."
    )
    text_ausgeben(
        "[Arvid] Hier. Hier bin ich gekommen. Den Stein mit der Kerbe kenne ich."
    )

    if daten.get("kehre_zugang") == "levin":
        print()
        text_ausgeben("[Levin] Vierzig. Es stimmt noch.")
        text_ausgeben("Er sieht den Hang hinunter.")
        text_ausgeben(
            "[Levin] Weiter komme ich nicht mit. Ich bin kein Kletterer. Ida "
            "weiß, was zu tun ist."
        )
    elif fehlgriff:
        print()
        text_ausgeben("Die Spur sah richtig aus. Die Zahl war richtig.")

    daten["kehre_weg"] = True
    zurueckgelassene_ziel_setzen("felsweg")
    return True


