def wald_weg_text(
    start_id,
    ziel_id
):
    texte = {
        "hauptweg":
            "Zum Hauptweg zurückkehren",

        "eingang":
            "Zum Beginn des alten Seitenpfades zurückkehren",

        "bachufer":
            "Dem Geräusch des Wassers folgen",

        "verborgenes_bachufer":
            "Zwischen den Wurzeln hindurchschlüpfen",

        "lagerplatz":
            "Dem alten Pfad zwischen den Bäumen folgen",

        "furt":
            "Zur flachen Furt weitergehen",

        "schlammweg":
            "Am schlammigen Ufer entlanggehen",

        "wildspur":
            "Der Wildspur folgen",

        "felshang":
            "Zum felsigen Hang aufsteigen",

        "unterholz":
            "Ins dichte Unterholz gehen",

        "quellmulde":
            "Der feuchten Senke zwischen den "
            "Wurzeln folgen",

        "felsspalte":
            "Zur schmalen Felsspalte gehen",

        "steinstufen":
            "Den überwachsenen Steinstufen folgen",

        "wegmarken":
            "Den alten Steinmarkierungen folgen",

        "wegstein":
            "Dem alten Weg bis zum hohen Stein folgen",

        "versunkene_steine":
            "Der Linie ins Unterholz folgen"
    }

    if (
        start_id == "versunkene_steine"
        and ziel_id == "wegstein"
    ):
        return "Zum alten Wegstein zurückgehen"

    text = texte.get(
        ziel_id,
        (
            f"In Richtung "
            f"{wald_knoten_name(ziel_id)} "
            f"weitergehen"
        )
    )

    if wald_ist_abkuerzung(
        start_id,
        ziel_id
    ):
        text += " [Abkürzung]"

    return text

def wald_fund_bekannt(fund_id):
    funde = wald_erforschung_status()[
        "funde"
    ]

    return bool(
        funde.get(
            fund_id,
            False
        )
    )


def wald_fund_setzen(
    fund_id,
    wert=True
):
    funde = wald_erforschung_status()[
        "funde"
    ]

    funde[
        fund_id
    ] = wert


def wald_hinweis_anzeigen(
    titel,
    text=None
):
    print()
    print("-" * 34)

    design_text(
        "NEUER HINWEIS",
        design="wissen",
        art="menue"
    )

    print()
    print(titel)

    if text:
        print()
        print(text)

    print("-" * 34)

def wald_knoten_aktionen(knoten_id):
    aktionen = []

    # -------------------------
    # BACHSUCHE UND VERBORGENER SEITENARM
    # -------------------------

    if knoten_id == "bachufer":
        if not wald_fund_bekannt("bach_geheimweg_entdeckt"):
            aktionen.append(
                (
                    "bach_geheimweg_suchen",
                    "Das Ufer gezielt absuchen [1 Schritt]"
                )
            )

    elif knoten_id == "verborgenes_bachufer":

        if not wald_fund_bekannt(
            "alte_wegmarke_gefunden"
        ):
            aktionen.append(
                (
                    "bacharm_untersuchen",
                    "Den stillen Seitenarm untersuchen"
                )
            )

    # -------------------------
    # VERLASSENES LAGER
    # -------------------------

    elif knoten_id == "lagerplatz":

        if not wald_fund_bekannt(
            "lager_durchsucht"
        ):
            aktionen.append(
                (
                    "lager_durchsuchen",
                    "Das alte Lager durchsuchen"
                )
            )

        if (
            wald_knoten_besucht(
                "furt"
            )
            and not wald_abkuerzung_offen(
                "lager_furt"
            )
        ):
            aktionen.append(
                (
                    "lager_zaunlinie",
                    "Die alten Holzpfosten verfolgen"
                )
            )

    # -------------------------
